    function solveAcademicProblem(question, mode = "study") {
      const q = normalizeMathText(question);

      // PIB por enfoque del gasto: PIB = C + I + G + X - M
      if (/pib|producto interno bruto|\bc\s*=.*\bi\s*=.*\bg\s*=/.test(normalize(q))) {
        const c = extractNamedNumber(q, "c");
        const i = extractNamedNumber(q, "i");
        const g = extractNamedNumber(q, "g");
        const x = extractNamedNumber(q, "x");
        const m = extractNamedNumber(q, "m");
        if ([c, i, g, x, m].every(Number.isFinite)) {
          const result = c + i + g + x - m;
          return {
            summary: "Calculo el PIB por el enfoque del gasto: PIB = C + I + G + X - M.",
            steps: [
              `Consumo (C) = ${c}, inversión (I) = ${i}, gasto público (G) = ${g}, exportaciones (X) = ${x}, importaciones (M) = ${m}.`,
              `Sustituimos: PIB = ${c} + ${i} + ${g} + ${x} - ${m}.`,
              `PIB = ${roundNumber(result)}.`,
              "Interpretación: este resultado mide el valor de la demanda agregada de bienes y servicios finales producidos internamente."
            ],
            result: `PIB = ${roundNumber(result)}`
          };
        }
      }

      // PORCENTAJE: 20% de 350 / 20 por ciento de 350
      const percent = q.match(/(-?\d+(?:[\.,]\d+)?)\s*(?:%|por\s+ciento)\s*(?:de|sobre|x|\*)\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (percent) {
        const p = parseNumber(percent[1]);
        const n = parseNumber(percent[2]);
        const result = n * p / 100;
        return { summary: `Para calcular ${p}% de ${n}, se convierte el porcentaje a decimal y se multiplica.`, steps: [`Convertimos ${p}% a decimal: ${p}/100 = ${p/100}.`, `Multiplicamos: ${n} × ${p/100} = ${roundNumber(result)}.`, `Interpretación: ${p}% de ${n} equivale a ${roundNumber(result)}.`], result: String(roundNumber(result)) };
      }

      const percentOfTotal = q.match(/(-?\d+(?:[\.,]\d+)?)\s*(?:es|representa|equivale\s+a)\s*(?:qu[eé]\s+porcentaje|cu[aá]nto\s+porcentaje|que\s+%)\s*(?:de|sobre)\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (percentOfTotal) {
        const part = parseNumber(percentOfTotal[1]);
        const total = parseNumber(percentOfTotal[2]);
        if (total !== 0) {
          const result = (part / total) * 100;
          return { summary: `Para saber qué porcentaje representa ${part} de ${total}, dividimos la parte para el total y multiplicamos por 100.`, steps: [`Dividimos: ${part} / ${total} = ${roundNumber(part / total)}.`, `Multiplicamos por 100: ${roundNumber(part / total)} × 100 = ${roundNumber(result)}%.`, `Interpretación: ${part} representa el ${roundNumber(result)}% de ${total}.`], result: `${roundNumber(result)}%` };
        }
      }

      // PROMEDIO / MEDIA
      if (/promedio|media/i.test(q)) {
        const nums = extractNumbers(q);
        if (nums.length >= 2) {
          const sum = nums.reduce((a, b) => a + b, 0);
          const avg = sum / nums.length;
          return { summary: `Calculo el promedio sumando los valores y dividiendo para la cantidad de datos.`, steps: [`Datos identificados: ${nums.join(", ")}.`, `Suma: ${nums.join(" + ")} = ${roundNumber(sum)}.`, `Cantidad de datos: ${nums.length}.`, `Promedio: ${roundNumber(sum)} / ${nums.length} = ${roundNumber(avg)}.`], result: String(roundNumber(avg)) };
        }
      }

      // ECUACIÓN CUADRÁTICA: ax² + bx + c = 0
      const quadratic = q.match(/(-?\d*(?:[\.,]\d+)?)\s*x\s*[²2^]\s*([+-]\s*\d*(?:[\.,]\d+)?)\s*x\s*([+-]\s*\d+(?:[\.,]\d+)?)\s*=\s*0/i);
      if (quadratic) {
        const a = quadratic[1] === "" || quadratic[1] === "+" ? 1 : quadratic[1] === "-" ? -1 : parseNumber(quadratic[1]);
        const b = quadratic[2] ? (quadratic[2].replace(/\s+/g, "") === "+" ? 1 : quadratic[2].replace(/\s+/g, "") === "-" ? -1 : parseNumber(quadratic[2].replace(/\s+/g, ""))) : 0;
        const c = quadratic[3] ? parseNumber(quadratic[3].replace(/\s+/g, "")) : 0;
        const discriminant = b * b - 4 * a * c;
        const steps = [`Ecuación identificada: ${a}x² ${b >= 0 ? "+" : ""}${b}x ${c >= 0 ? "+" : ""}${c} = 0.`, `Discriminante: Δ = b² − 4ac = ${b}² − 4(${a})(${c}) = ${roundNumber(discriminant)}.`];
        if (discriminant > 0) {
          const x1 = (-b + Math.sqrt(discriminant)) / (2 * a);
          const x2 = (-b - Math.sqrt(discriminant)) / (2 * a);
          steps.push(`Δ > 0: dos raíces reales.`, `x₁ = (−${b} + √${roundNumber(discriminant)}) / (2·${a}) = ${roundNumber(x1)}.`, `x₂ = (−${b} − √${roundNumber(discriminant)}) / (2·${a}) = ${roundNumber(x2)}.`);
          return { summary: `Ecuación cuadrática resuelta con la fórmula general. Tiene dos raíces reales distintas.`, steps, result: `x₁ = ${roundNumber(x1)}, x₂ = ${roundNumber(x2)}` };
        } else if (discriminant === 0) {
          const x = -b / (2 * a);
          steps.push(`Δ = 0: una raíz doble.`, `x = −${b} / (2·${a}) = ${roundNumber(x)}.`);
          return { summary: `Ecuación cuadrática con raíz doble.`, steps, result: `x = ${roundNumber(x)}` };
        } else {
          steps.push(`Δ < 0: no tiene raíces reales (raíces complejas).`);
          return { summary: `Ecuación cuadrática sin soluciones reales.`, steps, result: `Sin raíces reales (Δ = ${roundNumber(discriminant)})` };
        }
      }

      // SISTEMA 2x2: ax + by = c, dx + ey = f
      const sys = q.match(/(-?\d*(?:[\.,]\d+)?)\s*x\s*([+-]\s*\d*(?:[\.,]\d+)?)\s*y\s*=\s*(-?\d+(?:[\.,]\d+)?)\s*[,;y]\s*(-?\d*(?:[\.,]\d+)?)\s*x\s*([+-]\s*\d*(?:[\.,]\d+)?)\s*y\s*=\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (sys) {
        const a1 = sys[1] === "" || sys[1] === "+" ? 1 : sys[1] === "-" ? -1 : parseNumber(sys[1]);
        const b1 = sys[2] ? (sys[2].replace(/\s+/g, "") === "+" ? 1 : sys[2].replace(/\s+/g, "") === "-" ? -1 : parseNumber(sys[2].replace(/\s+/g, ""))) : 0;
        const c1 = parseNumber(sys[3]);
        const a2 = sys[4] === "" || sys[4] === "+" ? 1 : sys[4] === "-" ? -1 : parseNumber(sys[4]);
        const b2 = sys[5] ? (sys[5].replace(/\s+/g, "") === "+" ? 1 : sys[5].replace(/\s+/g, "") === "-" ? -1 : parseNumber(sys[5].replace(/\s+/g, ""))) : 0;
        const c2 = parseNumber(sys[6]);
        const det = a1 * b2 - a2 * b1;
        if (det !== 0) {
          const x = (c1 * b2 - c2 * b1) / det;
          const y = (a1 * c2 - a2 * c1) / det;
          return { summary: `Sistema de 2 ecuaciones con 2 incógnitas resuelto por el método de Cramer.`, steps: [`Ecuación 1: ${a1}x ${b1 >= 0 ? "+" : ""}${b1}y = ${c1}.`, `Ecuación 2: ${a2}x ${b2 >= 0 ? "+" : ""}${b2}y = ${c2}.`, `Determinante: D = ${a1}·${b2} − ${a2}·${b1} = ${roundNumber(det)}.`, `x = (${c1}·${b2} − ${c2}·${b1}) / ${roundNumber(det)} = ${roundNumber(x)}.`, `y = (${a1}·${c2} − ${a2}·${c1}) / ${roundNumber(det)} = ${roundNumber(y)}.`], result: `x = ${roundNumber(x)}, y = ${roundNumber(y)}` };
        }
      }

      // REGLA DE TRES: si A es a B, cuánto es C
      const ruleOf3 = q.match(/(?:si|cuando)\s*(-?\d+(?:[\.,]\d+)?)\s*(?:es|equivale|corresponde)\s*(?:a)?\s*(-?\d+(?:[\.,]\d+)?)\s*[,;]\s*(?:cuanto|cu[aá]nto|qu[eé])\s*(?:es|ser[aá]|equivale)?\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (ruleOf3) {
        const a = parseNumber(ruleOf3[1]);
        const b = parseNumber(ruleOf3[2]);
        const c = parseNumber(ruleOf3[3]);
        const result = (c * b) / a;
        return { summary: `Regla de tres simple directa: si ${a} → ${b}, entonces ${c} → ?`, steps: [`Proporción: ${a}/${b} = ${c}/x.`, `Despejamos x: x = (${c} × ${b}) / ${a}.`, `x = ${roundNumber(c * b)} / ${a} = ${roundNumber(result)}.`], result: String(roundNumber(result)) };
      }

      // INTERÉS SIMPLE: capital al r% por t años/meses
      const intSimple = q.match(/(?:inter[eé]s simple|interes simple).*?(\d+(?:[\.,]\d+)?).*?(\d+(?:[\.,]\d+)?)\s*%.*?(\d+(?:[\.,]\d+)?)\s*(?:a[nñ]o|mes|periodo)/i);
      if (intSimple) {
        const capital = parseNumber(intSimple[1]);
        const rate = parseNumber(intSimple[2]) / 100;
        const time = parseNumber(intSimple[3]);
        const interest = capital * rate * time;
        const total = capital + interest;
        return { summary: `Interés simple: I = C × r × t`, steps: [`Capital (C): $${capital}.`, `Tasa (r): ${intSimple[2]}% = ${rate}.`, `Tiempo (t): ${time} periodos.`, `Interés: I = ${capital} × ${rate} × ${time} = $${roundNumber(interest)}.`, `Monto total: M = C + I = $${capital} + $${roundNumber(interest)} = $${roundNumber(total)}.`], result: `Interés = $${roundNumber(interest)}, Monto = $${roundNumber(total)}` };
      }

      // INTERÉS COMPUESTO: capital al r% por t periodos
      const intComp = q.match(/(?:inter[eé]s compuesto|interes compuesto).*?(\d+(?:[\.,]\d+)?).*?(\d+(?:[\.,]\d+)?)\s*%.*?(\d+(?:[\.,]\d+)?)\s*(?:a[nñ]o|mes|periodo)/i);
      if (intComp) {
        const capital = parseNumber(intComp[1]);
        const rate = parseNumber(intComp[2]) / 100;
        const time = parseNumber(intComp[3]);
        const total = capital * Math.pow(1 + rate, time);
        const interest = total - capital;
        return { summary: `Interés compuesto: M = C × (1 + r)^t`, steps: [`Capital (C): $${capital}.`, `Tasa (r): ${intComp[2]}% = ${rate}.`, `Tiempo (t): ${time} periodos.`, `Monto: M = ${capital} × (1 + ${rate})^${time} = ${capital} × ${roundNumber(Math.pow(1 + rate, time))}.`, `Monto total: M = $${roundNumber(total)}.`, `Interés ganado: I = $${roundNumber(total)} − $${capital} = $${roundNumber(interest)}.`], result: `Monto = $${roundNumber(total)}, Interés = $${roundNumber(interest)}` };
      }

      // FACTORIAL: n!
      const factMatch = q.match(/(?:factorial|fact).*?(\d+)|(?:(\d+))\s*!/i);
      if (factMatch) {
        const n = parseInt(factMatch[1] || factMatch[2]);
        if (n >= 0 && n <= 170) {
          let f = 1; for (let i = 2; i <= n; i++) f *= i;
          return { summary: `Factorial de ${n}: n! = n × (n−1) × ... × 2 × 1`, steps: [`${n}! = ${Array.from({length: Math.min(n, 8)}, (_, i) => n - i).join(" × ")}${n > 8 ? " × ..." : ""}.`, `${n}! = ${f}.`], result: `${n}! = ${f}` };
        }
      }

      // COMBINACIONES: C(n,r) o "combinaciones de n en r"
      const combMatch = q.match(/(?:combinacion|combina|C\()\s*(\d+)\s*[,en]+\s*(\d+)/i);
      if (combMatch) {
        const n = parseInt(combMatch[1]), r = parseInt(combMatch[2]);
        if (n >= r && r >= 0 && n <= 170) {
          const fac = (x) => { let f = 1; for (let i = 2; i <= x; i++) f *= i; return f; };
          const result = fac(n) / (fac(r) * fac(n - r));
          return { summary: `Combinaciones C(${n},${r}) = n! / (r! × (n−r)!)`, steps: [`C(${n},${r}) = ${n}! / (${r}! × ${n - r}!).`, `= ${fac(n)} / (${fac(r)} × ${fac(n - r)}).`, `= ${roundNumber(result)}.`], result: `C(${n},${r}) = ${roundNumber(result)}` };
        }
      }

      // PERMUTACIONES: P(n,r)
      const permMatch = q.match(/(?:permutacion|permuta|P\()\s*(\d+)\s*[,en]+\s*(\d+)/i);
      if (permMatch) {
        const n = parseInt(permMatch[1]), r = parseInt(permMatch[2]);
        if (n >= r && r >= 0 && n <= 170) {
          const fac = (x) => { let f = 1; for (let i = 2; i <= x; i++) f *= i; return f; };
          const result = fac(n) / fac(n - r);
          return { summary: `Permutaciones P(${n},${r}) = n! / (n−r)!`, steps: [`P(${n},${r}) = ${n}! / ${n - r}!.`, `= ${fac(n)} / ${fac(n - r)}.`, `= ${roundNumber(result)}.`], result: `P(${n},${r}) = ${roundNumber(result)}` };
        }
      }

      // RAÍZ CUADRADA / CÚBICA
      const sqrtMatch = q.match(/(?:ra[ií]z\s*(?:cuadrada)?|sqrt)\s*(?:de)?\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (sqrtMatch) {
        const n = parseNumber(sqrtMatch[1]);
        if (n >= 0) {
          const result = Math.sqrt(n);
          return { summary: `Raíz cuadrada de ${n}.`, steps: [`√${n} = ${roundNumber(result)}.`], result: `√${n} = ${roundNumber(result)}` };
        }
      }

      // POTENCIA: a^b o "a elevado a b"
      const powMatch = q.match(/(\d+(?:[\.,]\d+)?)\s*(?:elevado|\^|\*\*)\s*(?:a)?\s*(\d+(?:[\.,]\d+)?)/i);
      if (powMatch) {
        const base = parseNumber(powMatch[1]);
        const exp = parseNumber(powMatch[2]);
        const result = Math.pow(base, exp);
        if (Number.isFinite(result)) {
          return { summary: `${base} elevado a la ${exp}.`, steps: [`${base}^${exp} = ${roundNumber(result)}.`], result: `${base}^${exp} = ${roundNumber(result)}` };
        }
      }

      // LOGARITMO: log(x), ln(x)
      const logMatch = q.match(/(?:log|logaritmo)\s*(?:base)?\s*(\d+)?\s*(?:de)?\s*(\d+(?:[\.,]\d+)?)/i);
      if (logMatch) {
        const base = logMatch[1] ? parseNumber(logMatch[1]) : 10;
        const n = parseNumber(logMatch[2]);
        if (n > 0 && base > 0 && base !== 1) {
          const result = Math.log(n) / Math.log(base);
          return { summary: `Logaritmo base ${base} de ${n}.`, steps: [`log_${base}(${n}) = ln(${n}) / ln(${base}).`, `= ${roundNumber(Math.log(n))} / ${roundNumber(Math.log(base))} = ${roundNumber(result)}.`], result: `log_${base}(${n}) = ${roundNumber(result)}` };
        }
      }

      const lnMatch = q.match(/ln\s*(?:de)?\s*(\d+(?:[\.,]\d+)?)/i);
      if (lnMatch) {
        const n = parseNumber(lnMatch[1]);
        if (n > 0) return { summary: `Logaritmo natural de ${n}.`, steps: [`ln(${n}) = ${roundNumber(Math.log(n))}.`], result: `ln(${n}) = ${roundNumber(Math.log(n))}` };
      }

      // ECUACIÓN LINEAL: ax + b = c
      const linear = q.match(/(-?\d*(?:[\.,]\d+)?)\s*x\s*([+-]\s*\d+(?:[\.,]\d+)?)?\s*=\s*(-?\d+(?:[\.,]\d+)?)/i);
      if (linear) {
        const a = linear[1] === "" || linear[1] === "+" ? 1 : linear[1] === "-" ? -1 : parseNumber(linear[1]);
        const b = linear[2] ? parseNumber(linear[2].replace(/\s+/g, "")) : 0;
        const c = parseNumber(linear[3]);
        if (a !== 0) {
          const x = (c - b) / a;
          return { summary: `Ecuación lineal ax + b = c resuelta despejando x.`, steps: [`Ecuación: ${a}x ${b >= 0 ? "+" : ""}${b} = ${c}.`, `Restamos ${b}: ${a}x = ${roundNumber(c - b)}.`, `Dividimos para ${a}: x = ${roundNumber(c - b)} / ${a} = ${roundNumber(x)}.`], result: `x = ${roundNumber(x)}` };
        }
      }

      // EXPRESIÓN ARITMÉTICA GENERAL: 2+3*5, (10+5)/3, etc.
      const expression = q.match(/(?:calcula|resolver|resuelve|resultado de)?\s*([\d\s+\-*/().,^]+)$/i);
      if (expression && /[+\-*/^]/.test(expression[1])) {
        const expr = expression[1].replace(/,/g, ".").replace(/\^/g, "**");
        if (/^[\d\s+\-*/().*]+$/.test(expr)) {
          try {
            const result = Function(`"use strict"; return (${expr});`)();
            if (Number.isFinite(result)) {
              return { summary: `Operación aritmética resuelta con jerarquía de operaciones.`, steps: [`Expresión: ${expression[1].trim()}.`, `Se resuelven paréntesis, potencias, multiplicaciones/divisiones, sumas/restas.`, `Resultado: ${roundNumber(result)}.`], result: String(roundNumber(result)) };
            }
          } catch (error) {}
        }
      }
      return null;
    }

    function normalizeMathText(value) {
      return String(value || "").replace(/−/g, "-").replace(/×/g, "*").replace(/÷/g, "/").trim();
    }

    function parseNumber(value) {
      const clean = String(value || "").replace(/,/g, ".").replace(/\s+/g, "");
      if (clean === "" || clean === "+") return 1;
      if (clean === "-") return -1;
      return Number(clean);
    }

    function extractNumbers(value) {
      return (String(value || "").match(/-?\d+(?:[\.,]\d+)?/g) || []).map(parseNumber).filter(Number.isFinite);
    }

    function extractNamedNumber(value, name) {
      const match = String(value || "").match(new RegExp(`\\b${name}\\s*=\\s*(-?\\d+(?:[\\.,]\\d+)?)`, "i"));
      return match ? parseNumber(match[1]) : NaN;
    }

    function roundNumber(value) {
      const n = Number(value);
      if (!Number.isFinite(n)) return value;
      return Math.round((n + Number.EPSILON) * 10000) / 10000;
    }

    function renderFormulaBank() {
      if (!el.formulaList || !el.formulaSubject) return;
      const subject = subjectById(el.formulaSubject.value) || SUBJECTS.find((item) => normalize(item.name).includes("econometria")) || SUBJECTS[0];
      const formulas = formulasForSubject(subject);
      formulaVisibleCount = Math.min(Math.max(4, formulaVisibleCount || 4), Math.max(formulas.length, 4));
      const visibleItems = formulas.slice(0, formulaVisibleCount);
      const remaining = Math.max(0, formulas.length - visibleItems.length);
      el.formulaList.innerHTML = `
        <div class="formula-bank-head">
          <div>
            <span class="formula-bank-label">${escapeHtml(subject.cycleName || findCycleBySubject(subject.id)?.name || "Malla curricular")}</span>
            <strong>${escapeHtml(subject.name)}</strong>
            <p>${formulas.length} fórmulas, conceptos, métodos o indicadores disponibles para esta materia.</p>
          </div>
          <span class="formula-count">${visibleItems.length} / ${formulas.length}</span>
        </div>
        <div class="formula-grid">
          ${visibleItems.map((item) => renderFormulaCard(item)).join("") || renderEmpty("Sin fórmulas", "Todavía no hay registros para esta materia.")}
        </div>
        ${formulas.length > 4 ? `<div class="formula-more-actions">
          ${remaining > 0 ? `<button class="btn-secondary formula-load-more" type="button" data-formula-more>Mostrar 4 más ↓</button><button class="btn-ghost formula-show-all" type="button" data-formula-all>Mostrar todas</button>` : `<button class="btn-secondary formula-load-more" type="button" data-formula-less>Volver a 4 ↑</button>`}
        </div>` : ""}
      `;
      el.formulaList.querySelector("[data-formula-more]")?.addEventListener("click", () => {
        formulaVisibleCount = Math.min(formulas.length, formulaVisibleCount + 4);
        renderFormulaBank();
      });
      el.formulaList.querySelector("[data-formula-all]")?.addEventListener("click", () => {
        formulaVisibleCount = formulas.length;
        renderFormulaBank();
      });
      el.formulaList.querySelector("[data-formula-less]")?.addEventListener("click", () => {
        formulaVisibleCount = 4;
        renderFormulaBank();
      });
      el.formulaList.querySelectorAll("[data-copy-formula]").forEach((button) => {
        button.addEventListener("click", () => {
          const value = button.dataset.copyFormula || "";
          const done = () => showToast("Fórmula copiada", "Ya puedes pegarla en tus apuntes.", "success");
          if (navigator.clipboard?.writeText) navigator.clipboard.writeText(value).then(done).catch(() => fallbackCopy(value, done));
          else fallbackCopy(value, done);
        });
      });
    }

    function renderFormulaCard(item) {
      const mathLike = isMathLike(item.valor) || ["fórmula", "formula", "modelo", "indicador"].includes(normalize(item.tipo));
      return `
        <article class="formula-item ${mathLike ? "is-math" : "is-concept"}">
          <div class="formula-item-top">
            <span class="formula-topic">${escapeHtml(item.tema)}</span>
            <span class="formula-type">${escapeHtml(item.tipo || "Concepto")}</span>
          </div>
          <div class="formula-expression ${mathLike ? "math-display" : "concept-display"}">${renderMathExpression(item.valor)}</div>
          <button class="mini-action formula-copy-action" type="button" data-copy-formula="${escapeAttribute(item.valor || "")}">Copiar fórmula</button>
          ${item.definicion ? `<p class="formula-definition">${escapeHtml(item.definicion)}</p>` : ""}
          ${item.uso ? `<p class="formula-use"><strong>Uso:</strong> ${escapeHtml(item.uso)}</p>` : ""}
          <div class="formula-tags">
            <span>${escapeHtml(item.nivel || "General")}</span>
            ${(item.tags || []).map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}
          </div>
        </article>`;
    }

    function formulasForSubject(subject) {
      const subjectName = normalize(subject?.name || "");
      const cycleName = normalize(subject?.cycleName || findCycleBySubject(subject?.id)?.name || "");
      let rows = FORMULA_BANK_DATA.filter((item) => normalize(item.materia) === subjectName && (!cycleName || normalize(item.ciclo) === cycleName));
      if (!rows.length) rows = FORMULA_BANK_DATA.filter((item) => normalize(item.materia) === subjectName);
      if (!rows.length) rows = FORMULA_BANK_DATA.filter((item) => normalize(item.materia).includes(subjectName) || subjectName.includes(normalize(item.materia)));
      return rows.slice().sort((a, b) => (Number(a.num) || 0) - (Number(b.num) || 0));
    }

    function isMathLike(value) {
      return /[=+\-*/^√Σ∑∫∂∞≈≠≤≥<>%]|[₀₁₂₃₄₅₆₇₈₉ᵢⱼₙₜₖₗₘ]|[⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿ]/.test(String(value || ""));
    }

    function renderMathExpression(value) {
      const supMap = { "⁰":"0", "¹":"1", "²":"2", "³":"3", "⁴":"4", "⁵":"5", "⁶":"6", "⁷":"7", "⁸":"8", "⁹":"9", "⁺":"+", "⁻":"-", "⁼":"=", "⁽":"(", "⁾":")", "ⁿ":"n", "ᵀ":"T" };
      const subMap = { "₀":"0", "₁":"1", "₂":"2", "₃":"3", "₄":"4", "₅":"5", "₆":"6", "₇":"7", "₈":"8", "₉":"9", "₊":"+", "₋":"-", "₌":"=", "₍":"(", "₎":")", "ᵢ":"i", "ⱼ":"j", "ₙ":"n", "ₜ":"t", "ₖ":"k", "ₗ":"l", "ₘ":"m" };
      const toChars = (text, map) => [...text].map((char) => map[char] || char).join("");
      return escapeHtml(value)
        .replace(/[⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿᵀ]+/g, (match) => `<sup>${toChars(match, supMap)}</sup>`)
        .replace(/[₀₁₂₃₄₅₆₇₈₉₊₋₌₍₎ᵢⱼₙₜₖₗₘ]+/g, (match) => `<sub>${toChars(match, subMap)}</sub>`)
        .replace(/\^\{([^}]+)\}/g, "<sup>$1</sup>")
        .replace(/\^\(([^)]+)\)/g, "<sup>($1)</sup>")
        .replace(/\^([A-Za-z0-9+\-]+)/g, "<sup>$1</sup>")
        .replace(/_\{([^}]+)\}/g, "<sub>$1</sub>")
        .replace(/_([A-Za-z0-9]+)/g, "<sub>$1</sub>");
    }

    function generateStudyPlan() {
      if (!el.studyPlanResult || !el.studyPlanSubject) return;
      const subject = subjectById(el.studyPlanSubject.value) || SUBJECTS[0];
      const rawDate = el.studyPlanDate?.value;
      const days = rawDate ? Math.max(1, daysUntil(rawDate)) : 7;
      const blocks = Math.min(6, Math.max(3, Math.ceil(days / 2)));
      const topics = studyRouteForSubject(subject).slice(0, blocks);
      el.studyPlanResult.innerHTML = `
        <article class="study-plan-card">
          <span class="feature-badge recommended">${days} días</span>
          <h4>${escapeHtml(subject.name)}</h4>
          <p>Plan sugerido hasta ${rawDate ? formatDate(rawDate) : "tu próxima evaluación"}.</p>
          <ol>${topics.map((topic, index) => `<li><strong>Día ${index + 1}</strong><span>${escapeHtml(topic)}</span></li>`).join("")}</ol>
          <button class="btn-secondary" type="button" data-tab="repositorio">Buscar materiales de esta materia</button>
        </article>`;
      el.studyPlanResult.querySelector("[data-tab]")?.addEventListener("click", () => {
        repoState.search = subject.name;
        showSection("repositorio", true);
        renderRepository();
      });
      showToast("Plan generado", `Ruta de repaso lista para ${subject.name}.`, "success");
    }

    function studyRouteForSubject(subject) {
      const name = normalize(subject?.name || "");
      if (name.includes("econometria")) return ["Repasar modelo lineal y supuestos", "Interpretar coeficientes y signos", "Resolver ejercicios de MCO", "Practicar pruebas t y F", "Revisar heterocedasticidad y errores estándar", "Simular un examen corto"];
      if (name.includes("metodos dinamicos")) return ["Identificar variables de estado", "Resolver ecuaciones en diferencias", "Calcular estado estacionario", "Analizar estabilidad", "Dibujar trayectoria o fase", "Resolver ejercicio aplicado"];
      if (name.includes("algebra")) return ["Matrices y operaciones", "Determinantes", "Inversa y rango", "Sistemas lineales", "Vectores y producto punto", "Problemas de examen"];
      if (name.includes("estadistica")) return ["Medidas descriptivas", "Probabilidad básica", "Distribuciones", "Inferencia y pruebas", "Interpretación de resultados", "Ejercicios mixtos"];
      if (name.includes("finanzas")) return ["Valor del dinero en el tiempo", "VAN y TIR", "Riesgo y rendimiento", "Razones financieras", "Casos de decisión", "Simulacro de cálculo"];
      return ["Revisar conceptos centrales", "Leer apuntes principales", "Resolver ejercicios básicos", "Revisar ejemplos aplicados", "Practicar preguntas del banco", "Hacer resumen final"];
    }

    function startExamSimulator() {
      if (!el.examSimResult || !el.examSimSubject) return;
      const subjectId = el.examSimSubject.value;
      const difficulty = el.examSimDifficulty?.value || "facil";
      const subject = subjectById(subjectId);
      const pool = quizQuestions().filter((question) => question.materia === subjectId && question.difficulty === difficulty);
      const fallback = quizQuestions().filter((question) => question.materia === subjectId);
      const selected = shuffle(pool.length ? pool : fallback).slice(0, 5);
      if (!selected.length) {
        el.examSimResult.innerHTML = renderEmpty("Sin preguntas para esta materia", "Prueba otra materia o abre el Quiz de Autoevaluación.");
        return showToast("Sin preguntas", "No hay preguntas disponibles para esta materia.", "error");
      }
      examSimulatorState = { questions: selected, index: 0, answers: [], subject: subject?.name || "Materia" };
      renderExamSimulatorQuestion();
    }

    function renderExamSimulatorQuestion() {
      if (!el.examSimResult) return;
      const q = examSimulatorState.questions[examSimulatorState.index];
      if (!q) {
        const score = examSimulatorState.answers.filter(Boolean).length;
        const history = loadJson(QUIZ_HISTORY_KEY, []);
        localStorage.setItem(QUIZ_HISTORY_KEY, JSON.stringify([{ date: new Date().toISOString().slice(0, 10), score, total: examSimulatorState.questions.length, subject: examSimulatorState.subject, mode: "Simulador" }, ...history]));
        localStorage.setItem(STUDY_ACTIVITY_KEY, JSON.stringify({ ...loadJson(STUDY_ACTIVITY_KEY, {}), lastQuiz: `${examSimulatorState.subject}: ${score}/${examSimulatorState.questions.length}`, updatedAt: new Date().toISOString() }));
        renderProfileSummary();
        el.examSimResult.innerHTML = `<article class="exam-sim-card"><h4>Resultado: ${score}/${examSimulatorState.questions.length}</h4><p>${score >= 4 ? "Muy buen repaso. Puedes subir dificultad." : "Conviene repasar errores y repetir el simulador."}</p><button class="btn-primary" type="button" data-exam-sim-restart>Reintentar</button></article>`;
        return;
      }
      el.examSimResult.innerHTML = `<article class="exam-sim-card"><div class="curriculum-progress"><span style="width:${Math.round((examSimulatorState.index / examSimulatorState.questions.length) * 100)}%"></span></div><p>${examSimulatorState.index + 1}/${examSimulatorState.questions.length} · ${escapeHtml(examSimulatorState.subject)}</p><h4>${formatMathText(q.question)}</h4><div class="quiz-options-grid">${q.options.map((option, index) => `<button class="btn-secondary quiz-option" type="button" data-exam-answer="${index}">${formatMathText(option)}</button>`).join("")}</div></article>`;
    }

    function handleExamSimulatorClick(event) {
      const restart = event.target.closest("[data-exam-sim-restart]");
      if (restart) return startExamSimulator();
      const answer = event.target.closest("[data-exam-answer]");
      if (!answer) return;
      const q = examSimulatorState.questions[examSimulatorState.index];
      if (!q) return;
      const selected = Number(answer.dataset.examAnswer);
      const correct = selected === q.correct;
      examSimulatorState.answers[examSimulatorState.index] = correct;
      el.examSimResult.querySelectorAll("[data-exam-answer]").forEach((button) => {
        const value = Number(button.dataset.examAnswer);
        button.disabled = true;
        button.classList.toggle("correct", value === q.correct);
        button.classList.toggle("wrong", value === selected && !correct);
      });
      el.examSimResult.querySelector(".exam-sim-card")?.insertAdjacentHTML("beforeend", `<div class="quiz-feedback ${correct ? "success" : "error"}"><strong>${correct ? "Correcto" : "Incorrecto"}</strong><p><b>Respuesta:</b> ${formatMathText(q.options[q.correct])}</p><p>${formatMathText(q.explanation || "Revisa el concepto central y vuelve a resolver paso a paso.")}</p><p><b>Sugerencia:</b> ${formatMathText(q.tip || "Escribe datos, fórmula y reemplazo antes de elegir.")}</p><button class="btn-primary" type="button" data-exam-next>${examSimulatorState.index + 1 >= examSimulatorState.questions.length ? "Ver resultado" : "Siguiente"}</button></div>`);
      el.examSimResult.querySelector("[data-exam-next]")?.addEventListener("click", () => {
        examSimulatorState.index += 1;
        renderExamSimulatorQuestion();
      }, { once: true });
    }

    function renderStudyActivity() {
      const activity = loadJson(STUDY_ACTIVITY_KEY, {});
      const panel = document.querySelector(".study-activity-panel");
      if (panel || !el.studyPlanResult) return;
    }

    function populateGpaSubjects() {
      if (!el.gpaSubject) return;
      const cycle = findCycle(el.gpaCycle.value) || CYCLES[0];
      const current = el.gpaSubject.value;
      el.gpaSubject.innerHTML = cycle.subjects.map((subject) => `<option value="${subject.id}">${subject.name}</option>`).join("");
      el.gpaSubject.value = cycle.subjects.some((subject) => subject.id === current) ? current : cycle.subjects[0]?.id || "";
    }

    function gradeKey() { return `${el.gpaCycle.value}_${el.gpaSubject.value}`; }
    function defaultGradeRows() {
      return [
        { id: "aprovechamiento-1", name: "Primer aprovechamiento", max: 25, score: "" },
        { id: "interciclo", name: "Examen interciclo", max: 20, score: "" },
        { id: "aprovechamiento-2", name: "Segundo aprovechamiento", max: 25, score: "" },
        { id: "final", name: "Examen final", max: 30, score: "" }
      ];
    }
    function gradeRows() {
      const key = gradeKey();
      const saved = Array.isArray(appData.gradebook[key]) ? appData.gradebook[key] : [];
      appData.gradebook[key] = defaultGradeRows().map((row) => ({ ...row, score: saved.find((item) => item.id === row.id || item.name === row.name)?.score || "" }));
      return appData.gradebook[key];
    }

    function renderGpaRows() {
      if (!el.gpaRows || !el.gpaSubject.value) return;
      el.gpaRows.innerHTML = gradeRows().map((row, index) => `
        <div class="grade-row" data-grade-row="${index}">
          <label><span>Componente</span><input value="${escapeAttribute(row.name)}" readonly></label>
          <label><span>Valor máximo</span><input value="${row.max} puntos" readonly></label>
          <label><span>Tu nota sobre 100</span><input data-grade-field="score" type="number" min="0" max="100" step="0.01" value="${escapeAttribute(row.score || "")}" placeholder="0 - 100"></label>
          <span class="grade-max-note">${convertComponentScore(row.score, row.max).toFixed(2)} / ${row.max}</span>
        </div>`).join("");
      calculateGpa();
    }

    function saveGradebookFromInputs() {
      const rows = [...el.gpaRows.querySelectorAll("[data-grade-row]")].map((row) => ({
        ...gradeRows()[Number(row.dataset.gradeRow)],
        score: row.querySelector('[data-grade-field="score"]').value
      }));
      appData.gradebook[gradeKey()] = rows;
      saveData();
      [...el.gpaRows.querySelectorAll("[data-grade-row]")].forEach((row) => {
        const index = Number(row.dataset.gradeRow);
        const item = appData.gradebook[gradeKey()][index];
        const note = row.querySelector(".grade-max-note");
        if (note && item) note.textContent = `${convertComponentScore(item.score, item.max).toFixed(2)} / ${item.max}`;
      });
      calculateGpa();
    }

    function calculateGpa() {
      if (!el.gpaResult) return;
      const rows = gradeRows().map((row) => ({ ...row, hasScore: String(row.score).trim() !== "", score100: Math.min(Number(row.score) || 0, 100), contribution: convertComponentScore(row.score, row.max) }));
      const finalRow = rows.find((row) => row.id === "final");
      const beforeFinalRows = rows.filter((row) => row.id !== "final");
      const beforeFinal = beforeFinalRows.reduce((sum, row) => sum + row.contribution, 0);
      const accumulated = rows.reduce((sum, row) => sum + (row.hasScore ? row.contribution : 0), 0);
      const finalMax = 30;
      const minimumFinal = 12;
      const passScore = 60;
      const finalContribution = finalRow?.hasScore ? finalRow.contribution : 0;
      const finalScoreOver30 = finalRow?.hasScore ? finalContribution : null;
      const totalWithFinal = beforeFinal + finalContribution;
      const pointsNeeded = passScore - beforeFinal;
      const neededFinal = Math.max(minimumFinal, pointsNeeded);
      let status = "";
      if (finalRow?.hasScore) {
        const passed = totalWithFinal >= passScore && finalScoreOver30 >= minimumFinal;
        status = passed
          ? `<span class="status-pass">Apruebas con ${totalWithFinal.toFixed(2)}/100 y cumples el mínimo de ${minimumFinal}/${finalMax} en el final.</span>`
          : `<span class="status-risk">Aún no apruebas: necesitas llegar a ${passScore}/100 y sacar mínimo ${minimumFinal}/${finalMax} en el examen final.</span>`;
      } else if (neededFinal > finalMax) {
        status = `<span class="status-risk">Necesitarías ${neededFinal.toFixed(2)}/${finalMax}; matemáticamente no alcanza para aprobar con ${passScore}/100.</span>`;
      } else {
        status = `<span class="status-pass">Para aprobar necesitas ${neededFinal.toFixed(2)}/${finalMax} en el examen final. Recuerda que el final siempre debe ser mínimo ${minimumFinal}/${finalMax}.</span>`;
      }
      el.gpaResult.innerHTML = `<strong>Nota total actual: ${accumulated.toFixed(2)} / 100</strong>${rows.map((row) => `<span>${escapeHtml(row.name)}: ${row.hasScore ? row.score100.toFixed(2) : "sin ingresar"}/100 equivale a ${row.hasScore ? row.contribution.toFixed(2) : "0.00"}/${row.max}</span>`).join("")}<span>Acumulado antes del final frente a la meta de aprobación: ${beforeFinal.toFixed(2)} / ${passScore}</span>${status}`;
    }

    function convertComponentScore(score, maxValue) {
      return (Math.min(Number(score) || 0, 100) / 100) * Number(maxValue || 0);
    }

    function populateScheduleSubjects() {
      if (!el.scheduleSubject) return;
      const cycle = findCycle(el.scheduleCycle.value) || SCHEDULE_CYCLES[0];
      const current = el.scheduleSubject.value;
      el.scheduleSubject.innerHTML = cycle.subjects.map((subject) => `<option value="${subject.id}">${subject.name}</option>`).join("");
      el.scheduleSubject.value = cycle.subjects.some((subject) => subject.id === current) ? current : cycle.subjects[0]?.id || "";
    }

    function renderSchedule() {
      if (!el.scheduleTableWrap) return;
      const cycleId = el.scheduleCycle.value || SCHEDULE_CYCLES[0].id;
      const group = el.scheduleGroup?.value || "Grupo 1";
      el.scheduleCycle.value = cycleId;
      const studentItems = (appData.studentSchedules || []).map((item) => ({ ...item, source: "Mi horario" }));
      const dayOrder = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes"];
      const items = studentItems
        .filter((item) => item.cycleId === cycleId && (item.group || "Grupo 1") === group)
        .sort((a, b) => (dayOrder.indexOf(a.day) - dayOrder.indexOf(b.day)) || String(a.start || "").localeCompare(String(b.start || "")));
      const viewButtons = `<div class="schedule-view-actions" aria-label="Vista del horario">
          <button class="btn-secondary ${scheduleViewMode === "list" ? "active" : ""}" type="button" data-schedule-view="list">Ver lista</button>
          <button class="btn-secondary ${scheduleViewMode === "calendar" ? "active" : ""}" type="button" data-schedule-view="calendar">Ver calendario semanal</button>
          ${scheduleEditId ? `<button class="btn-secondary" type="button" data-schedule-cancel-edit>Cancelar edición</button>` : ""}
        </div>`;
      el.scheduleTableWrap.innerHTML = `
        <div class="form-note">Mostrando ${findCycle(cycleId)?.name || ""} · ${group}. Puedes agregar materias a tu horario y luego imprimir esta página.</div>
        ${viewButtons}
        ${scheduleViewMode === "calendar" ? renderScheduleCalendar(items) : renderScheduleList(items)}`;
    }

    function renderScheduleList(items) {
      return `<table class="schedule-table schedule-list-table">
        <thead><tr><th>Día</th><th>Materia</th><th>Inicio</th><th>Fin</th><th>Aula</th><th>Grupo</th><th>Acción</th></tr></thead>
        <tbody>${items.length ? items.map(renderScheduleRow).join("") : `<tr><td colspan="7">${renderEmpty("Sin horario registrado", "Agrega una materia para construir tu horario personalizado.")}</td></tr>`}</tbody>
      </table>`;
    }

    function renderScheduleRow(item) {
      return `<tr data-schedule-row="${item.id || ""}"><td>${escapeHtml(item.day || "")}</td><td><strong>${subjectName(item.cycleId, item.subjectId) || escapeHtml(item.subjectId)}</strong><small>${escapeHtml(item.docente || "Docente por definir")} · ${escapeHtml(item.source || "Mi horario")}</small></td><td>${escapeHtml(item.start || "")}</td><td>${escapeHtml(item.end || "")}</td><td>${escapeHtml(item.aula || "Aula por definir")}</td><td>${escapeHtml(item.group || "Grupo 1")}</td><td><div class="schedule-row-actions"><button class="schedule-edit" type="button" data-edit-student-schedule="${item.id}">Editar</button><button class="schedule-delete" type="button" data-delete-student-schedule="${item.id}">Eliminar</button></div></td></tr>`;
    }

    function renderScheduleCalendar(items) {
      const days = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes"];
      const slots = [
        ["07:00", "09:00"], ["09:00", "11:00"], ["11:00", "13:00"],
        ["13:00", "15:00"], ["15:00", "17:00"], ["17:00", "19:00"], ["19:00", "21:00"]
      ];
      return `<div class="schedule-poster">
        <div class="schedule-poster-header">
          <span class="schedule-poster-logo" aria-hidden="true">EC</span>
          <div><span>Universidad de Cuenca</span><h4>Horario Semanal de Economía</h4><p>${escapeHtml(findCycle(el.scheduleCycle.value)?.name || "Ciclo")} · ${escapeHtml(el.scheduleGroup?.value || "Grupo 1")}</p></div>
        </div>
        <div class="schedule-calendar-wrap">
          <table class="schedule-calendar-table" aria-label="Horario semanal tipo calendario">
            <thead><tr><th>Hora</th>${days.map((day) => `<th>${day}</th>`).join("")}</tr></thead>
            <tbody>${slots.map(([start, end]) => `<tr><th>${start} - ${end}</th>${days.map((day) => `<td>${renderScheduleCalendarCell(items, day, start, end)}</td>`).join("")}</tr>`).join("")}</tbody>
          </table>
        </div>
        <p class="schedule-print-note">Cada color identifica una materia. Toca una viñeta para ver docente, aula y grupo.</p>
      </div>`;
    }

    function renderScheduleCalendarCell(items, day, slotStart, slotEnd) {
      const matches = items.filter((item) => item.day === day && timeRangesOverlap(item.start, item.end, slotStart, slotEnd));
      if (!matches.length) return '<span class="calendar-empty">Disponible</span>';
      return matches.map((item) => `<article class="calendar-class" data-schedule-row="${item.id || ""}" data-schedule-detail="${item.id}" style="--schedule-color:${scheduleColor(item.subjectId)};--schedule-bg:${hexToRgba(scheduleColor(item.subjectId), 0.12)}">
        <strong>${subjectName(item.cycleId, item.subjectId) || escapeHtml(item.subjectId)}</strong>
        <span>${escapeHtml(item.start || "")} - ${escapeHtml(item.end || "")}</span>
        <small>${escapeHtml(item.aula || "Aula por definir")}</small>
        <em>${escapeHtml(item.docente || "Docente por definir")}</em>
        <button type="button" data-edit-student-schedule="${item.id}">Editar</button>
      </article>`).join("");
    }

    function scheduleColor(subjectId) {
      const palette = ["#1a56db", "#059669", "#ea580c", "#7c3aed", "#dc2626", "#0f766e", "#4f46e5", "#c8970a", "#be185d", "#0891b2"];
      const index = SUBJECTS.findIndex((subject) => subject.id === subjectId);
      return palette[Math.max(index, 0) % palette.length];
    }

    function hexToRgba(hex, alpha = 1) {
      const clean = String(hex).replace("#", "");
      const value = parseInt(clean.length === 3 ? clean.split("").map((char) => char + char).join("") : clean, 16);
      const red = (value >> 16) & 255;
      const green = (value >> 8) & 255;
      const blue = value & 255;
      return `rgba(${red},${green},${blue},${alpha})`;
    }

    function timeToMinutes(value) {
      const [hour, minute] = String(value || "00:00").split(":").map(Number);
      return (Number(hour) || 0) * 60 + (Number(minute) || 0);
    }

    function timeRangesOverlap(startA, endA, startB, endB) {
      const aStart = timeToMinutes(startA);
      const aEnd = timeToMinutes(endA);
      const bStart = timeToMinutes(startB);
      const bEnd = timeToMinutes(endB);
      return aStart < bEnd && aEnd > bStart;
    }

    function slotHour(value) { return `${String(value || "00:00").slice(0, 2)}:00`; }

    function addStudentSchedule() {
      if (!el.scheduleSubject.value) return showToast("Horario incompleto", "Selecciona una materia.", "error");
      if (!el.scheduleStart.value || !el.scheduleEnd.value) return showToast("Horario incompleto", "Selecciona hora de inicio y fin.", "error");
      if (timeToMinutes(el.scheduleEnd.value) <= timeToMinutes(el.scheduleStart.value)) return showToast("Horario inválido", "La hora de fin debe ser mayor que la hora de inicio.", "error");
      const addedId = uid();
      const editingId = scheduleEditId;
      const subjectLabel = subjectName(el.scheduleCycle.value, el.scheduleSubject.value) || el.scheduleSubject.value;
      appData.studentSchedules = appData.studentSchedules || [];
      const payload = {
        cycleId: el.scheduleCycle.value,
        group: el.scheduleGroup.value,
        subjectId: el.scheduleSubject.value,
        day: el.scheduleDay.value,
        start: el.scheduleStart.value,
        end: el.scheduleEnd.value,
        aula: el.scheduleAula.value,
        docente: el.scheduleDocente?.value.trim() || "Docente por definir"
      };
      if (editingId) {
        appData.studentSchedules = appData.studentSchedules.map((item) => item.id === editingId ? { ...item, ...payload } : item);
      } else {
        appData.studentSchedules.push({ id: addedId, ...payload });
      }
      el.scheduleAula.value = "";
      if (el.scheduleDocente) el.scheduleDocente.value = "";
      scheduleEditId = "";
      el.addStudentSchedule.textContent = "Agregar materia";
      localStorage.setItem(STUDENT_SCHEDULE_KEY, JSON.stringify(appData.studentSchedules));
      saveData();
      renderSchedule();
      renderNextClassWidget();
      checkAchievements();
      const rowId = editingId || addedId;
      const row = el.scheduleTableWrap?.querySelector(`[data-schedule-row="${CSS.escape(rowId)}"]`);
      if (row) {
        row.classList.add("row-highlight");
        setTimeout(() => row.classList.remove("row-highlight"), 2400);
      }
      showToast("Horario actualizado", `${editingId ? "Se actualizó" : "Se agregó"} ${subjectLabel} los ${el.scheduleDay.value} de ${el.scheduleStart.value} a ${el.scheduleEnd.value}.`, "success");
    }

    function handleScheduleClick(event) {
      const viewButton = event.target.closest("[data-schedule-view]");
      const cancelEditButton = event.target.closest("[data-schedule-cancel-edit]");
      const editButton = event.target.closest("[data-edit-student-schedule]");
      const deleteButton = event.target.closest("[data-delete-student-schedule]");
      const detailCard = event.target.closest("[data-schedule-detail]");
      if (viewButton) {
        scheduleViewMode = viewButton.dataset.scheduleView;
        renderSchedule();
        return;
      }
      if (cancelEditButton) {
        scheduleEditId = "";
        el.addStudentSchedule.textContent = "Agregar materia";
        el.scheduleAula.value = "";
        if (el.scheduleDocente) el.scheduleDocente.value = "";
        renderSchedule();
        showToast("Edición cancelada", "Puedes seguir agregando materias a tu horario.", "info");
        return;
      }
      if (editButton) {
        const item = (appData.studentSchedules || []).find((row) => row.id === editButton.dataset.editStudentSchedule);
        if (!item) return;
        beginScheduleEdit(item);
        return;
      }
      if (detailCard) {
        openScheduleDetail(detailCard.dataset.scheduleDetail);
        return;
      }
      if (!deleteButton) return;
      appData.studentSchedules = (appData.studentSchedules || []).filter((item) => item.id !== deleteButton.dataset.deleteStudentSchedule);
      if (scheduleEditId === deleteButton.dataset.deleteStudentSchedule) {
        scheduleEditId = "";
        el.addStudentSchedule.textContent = "Agregar materia";
      }
      localStorage.setItem(STUDENT_SCHEDULE_KEY, JSON.stringify(appData.studentSchedules));
      saveData();
      renderSchedule();
      renderNextClassWidget();
      showToast("Horario actualizado", "La materia fue eliminada de tu horario.", "info");
    }

    function openScheduleDetail(id) {
      const item = (appData.studentSchedules || []).find((row) => row.id === id);
      if (!item) return;
      const subject = subjectName(item.cycleId, item.subjectId) || item.subjectId;
      const overlay = document.createElement("div");
      overlay.className = "schedule-detail-modal";
      overlay.innerHTML = `<article class="schedule-detail-card" role="dialog" aria-modal="true" aria-labelledby="scheduleDetailTitle" style="--schedule-color:${scheduleColor(item.subjectId)};--schedule-bg:${hexToRgba(scheduleColor(item.subjectId), 0.12)}">
        <button class="schedule-detail-close" type="button" data-close-schedule-detail aria-label="Cerrar detalle">×</button>
        <span class="schedule-detail-badge">${escapeHtml(item.day || "Día")} · ${escapeHtml(item.start || "")} - ${escapeHtml(item.end || "")}</span>
        <h3 id="scheduleDetailTitle">${escapeHtml(subject)}</h3>
        <dl>
          <div><dt>Docente</dt><dd>${escapeHtml(item.docente || "Docente por definir")}</dd></div>
          <div><dt>Aula / lugar</dt><dd>${escapeHtml(item.aula || "Aula por definir")}</dd></div>
          <div><dt>Grupo</dt><dd>${escapeHtml(item.group || "Grupo 1")}</dd></div>
          <div><dt>Ciclo</dt><dd>${escapeHtml(findCycle(item.cycleId)?.name || "Ciclo")}</dd></div>
        </dl>
        <div class="modal-actions"><button class="btn-secondary" type="button" data-edit-from-detail="${item.id}">Editar materia</button><button class="btn-primary" type="button" data-close-schedule-detail>Cerrar</button></div>
      </article>`;
      const close = () => {
        document.removeEventListener("keydown", onKeydown);
        overlay.remove();
      };
      const onKeydown = (event) => { if (event.key === "Escape") close(); };
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay || event.target.closest("[data-close-schedule-detail]")) close();
        const edit = event.target.closest("[data-edit-from-detail]");
        if (edit) {
          close();
          beginScheduleEdit(item);
        }
      });
      document.addEventListener("keydown", onKeydown);
      document.body.appendChild(overlay);
      overlay.querySelector("[data-close-schedule-detail]")?.focus();
    }

    function beginScheduleEdit(item) {
      scheduleEditId = item.id;
      el.scheduleCycle.value = item.cycleId;
      populateScheduleSubjects();
      el.scheduleGroup.value = item.group || "Grupo 1";
      el.scheduleSubject.value = item.subjectId;
      el.scheduleDay.value = item.day || "Lunes";
      el.scheduleStart.value = item.start || "07:00";
      el.scheduleEnd.value = item.end || "09:00";
      el.scheduleAula.value = item.aula || "";
      if (el.scheduleDocente) el.scheduleDocente.value = item.docente || "";
      el.addStudentSchedule.textContent = "Guardar cambios";
      document.querySelector(".schedule-builder")?.scrollIntoView({ behavior: "smooth", block: "center" });
      showToast("Editando horario", "Ajusta los campos y presiona Guardar cambios.", "info");
    }

    function printScheduleCalendar() {
      scheduleViewMode = "calendar";
      renderSchedule();
      setTimeout(() => window.print(), 80);
    }

    function startPomodoro() {
      if (pomodoroRunning) return;
      requestPomodoroNotificationPermission();
      if (!pomodoroRemaining || pomodoroRemaining <= 0) resetPomodoro();
      pomodoroRunning = true;
      document.querySelector(".pomodoro-panel")?.classList.add("is-running");
      updatePomodoroDisplay();
      pomodoroTimer = setInterval(() => {
        pomodoroRemaining -= 1;
        if (pomodoroRemaining <= 0) switchPomodoroMode();
        updatePomodoroDisplay();
      }, 1000);
      showToast("Pomodoro iniciado", "Tu bloque de concentración está corriendo.", "success");
    }

    function pausePomodoro() {
      clearInterval(pomodoroTimer);
      pomodoroTimer = null;
      pomodoroRunning = false;
      document.querySelector(".pomodoro-panel")?.classList.remove("is-running");
      updatePomodoroDisplay();
      showToast("Pomodoro pausado", "Puedes retomarlo cuando quieras.", "warning");
    }

    function resetPomodoro() {
      clearInterval(pomodoroTimer);
      pomodoroTimer = null;
      pomodoroRunning = false;
      document.querySelector(".pomodoro-panel")?.classList.remove("is-running");
      pomodoroMode = el.pomodoroMode?.value || "study";
      pomodoroRemaining = pomodoroMinutes(pomodoroMode) * 60;
      updatePomodoroDisplay();
    }

    function switchPomodoroMode() {
      if (pomodoroMode === "study") {
        pomodoroSessions += 1;
        localStorage.setItem(POMODORO_KEY, String(pomodoroSessions));
        checkAchievements();
      }
      playPomodoroSound();
      showPomodoroNotification();
      pomodoroMode = pomodoroMode === "study" ? "short" : "study";
      if (el.pomodoroMode) el.pomodoroMode.value = pomodoroMode;
      pomodoroRemaining = pomodoroMinutes(pomodoroMode) * 60;
      renderProfileSummary();
      showToast(pomodoroMode !== "study" ? "Descanso activo" : "Volver a estudiar", pomodoroMode !== "study" ? "Terminó el bloque. Toma un descanso." : "Descanso terminado. Inicia otro bloque.", "success");
    }

    function pomodoroMinutes(mode) {
      const input = mode === "study" ? el.pomodoroStudy : el.pomodoroBreak;
      const fallback = mode === "study" ? 25 : mode === "long" ? 15 : 5;
      if (mode === "long") return 15;
      return Math.max(1, Number(input?.value) || fallback);
    }

    function updatePomodoroDisplay() {
      if (!el.pomodoroDisplay) return;
      if (!pomodoroRunning && (!pomodoroRemaining || pomodoroRemaining <= 0)) pomodoroRemaining = pomodoroMinutes(pomodoroMode) * 60;
      const minutes = Math.floor(pomodoroRemaining / 60);
      const seconds = pomodoroRemaining % 60;
      el.pomodoroDisplay.textContent = `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
      const total = pomodoroMinutes(pomodoroMode) * 60;
      const progress = total ? 314 * (1 - (pomodoroRemaining / total)) : 0;
      if (el.pomodoroProgress) el.pomodoroProgress.style.strokeDashoffset = String(progress);
      if (el.pomodoroSessions) el.pomodoroSessions.textContent = `${pomodoroSessions} sesiones completadas.`;
      const label = pomodoroMode === "study" ? "Sesión de estudio" : pomodoroMode === "long" ? "Descanso largo" : "Descanso corto";
      el.pomodoroStatus.textContent = `${label}${pomodoroRunning ? " en curso" : " pausada"}`;
    }

    function playPomodoroSound() {
      try {
        const context = new (window.AudioContext || window.webkitAudioContext)();
        const oscillator = context.createOscillator();
        const gain = context.createGain();
        oscillator.type = "sine";
        oscillator.frequency.value = 440;
        gain.gain.setValueAtTime(0.001, context.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.08, context.currentTime + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, context.currentTime + 0.3);
        oscillator.connect(gain);
        gain.connect(context.destination);
        oscillator.start();
        oscillator.stop(context.currentTime + 0.3);
      } catch {}
    }

    function requestPomodoroNotificationPermission() {
      if (!("Notification" in window) || Notification.permission !== "default") return;
      Notification.requestPermission().catch(() => {});
    }

    function showPomodoroNotification() {
      if (!("Notification" in window) || Notification.permission !== "granted") return;
      try {
        new Notification("Sesión completada, toma un descanso", {
          body: "Portal Estudiantil de Economía",
          tag: "pomodoro-economia"
        });
      } catch {}
    }

    function renderCurriculum() {
      if (!el.curriculumGrid) return;
      const statuses = appData.curriculumStatus || {};
      const total = countSubjects();
      const approved = Object.values(statuses).filter((status) => status === "aprobada").length;
      const progress = total ? Math.round((approved / total) * 100) : 0;
      el.curriculumProgressBar.style.width = `${progress}%`;
      el.curriculumProgressText.textContent = `${approved} de ${total} materias aprobadas, promedio de avance ${progress} por ciento.`;
      el.curriculumGrid.innerHTML = CYCLES.map((cycle) => `<article class="portal-card cycle-progress-card"><h3>${cycle.name}</h3>${cycle.subjects.map((subject) => {
        const status = statuses[subject.id] || "pendiente";
        return `<div class="curriculum-subject ${status}"><span>${subject.name}</span><select data-curriculum-subject="${subject.id}"><option value="pendiente" ${status === "pendiente" ? "selected" : ""}>Pendiente</option><option value="en-curso" ${status === "en-curso" ? "selected" : ""}>En curso</option><option value="aprobada" ${status === "aprobada" ? "selected" : ""}>Aprobada</option></select></div>`;
      }).join("")}</article>`).join("");
    }

    function handleCurriculumChange(event) {
      const select = event.target.closest("[data-curriculum-subject]");
      if (!select) return;
      appData.curriculumStatus[select.dataset.curriculumSubject] = select.value;
      localStorage.setItem(CURRICULUM_STATE_KEY, JSON.stringify(appData.curriculumStatus));
      saveData();
      renderCurriculum();
      renderAcademicCurve();
      checkAchievements();
    }

    function renderBanco() {
      const cycleId = el.bancoFilterCiclo.value;
      const type = el.bancoFilterTipo.value;
      renderBancoSubjectChips();
      const selectedSubject = el.bancoSubjectChips?.dataset.subject || "all";
      const exams = visibleResources().filter((r) => {
        const subject = subjectName(r.cycleId, r.subjectId);
        const haystack = normalize(`${r.title} ${r.description} ${subject} ${findCycle(r.cycleId)?.name || ""} ${r.date} ${r.source === DRIVE_RESOURCE_SOURCE ? "google drive" : "local"}`);
        return r.typeId === "examenes" && (!cycleId || r.cycleId === cycleId) && (!type || haystack.includes(normalize(type))) && (selectedSubject === "all" || r.subjectId === selectedSubject);
      });
      const grouped = CYCLES.map((cycle) => {
        const subjects = cycle.subjects.map((subject) => ({ subject, exams: exams.filter((exam) => exam.cycleId === cycle.id && exam.subjectId === subject.id) })).filter((group) => group.exams.length || (isAdmin && (!cycleId || cycleId === cycle.id)));
        return { cycle, subjects };
      }).filter((group) => group.subjects.length);
      const content = grouped.length
        ? `<div class="exam-tree">${grouped.map(renderExamCycleTree).join("")}</div>`
        : `<div class="banco-empty-wrap">${renderEmpty("Sin exámenes en este filtro", "Sube PDFs a Google Drive dentro de la carpeta Exámenes de cada materia y pulsa Reintentar sincronización. También puedes agregar un enlace manual desde el modo administrador.")}</div>`;
      el.bancoTableBody.innerHTML = `<tr class="${grouped.length ? "" : "banco-empty-row"}"><td colspan="5">${renderBancoDrivePanel(exams.length)}${content}</td></tr>`;
    }

    function renderBancoDrivePanel(examCount = 0) {
      const driveExams = visibleResources().filter((item) => item.typeId === "examenes" && item.source === DRIVE_RESOURCE_SOURCE).length;
      const statusText = driveRepositoryStatus.loading
        ? "Sincronizando Drive..."
        : driveRepositoryStatus.error
        ? "Drive necesita revisión"
        : driveRepositoryStatus.enabled
        ? `Drive conectado: ${driveExams} examen(es) sincronizado(s)`
        : "Drive no configurado";
      const statusClass = driveRepositoryStatus.loading ? "warning" : driveRepositoryStatus.error ? "error" : driveRepositoryStatus.enabled ? "success" : "muted";
      const helper = driveRepositoryStatus.error
        ? "Revisa que Apps Script esté publicado como Web App pública y que la URL termine en /exec. Mientras tanto puedes abrir la carpeta Drive."
        : "Para subir exámenes: Drive → Repositorio Economía → Ciclo → Materia → Exámenes. Sube el PDF y luego pulsa Reintentar sincronización.";
      return `<section class="banco-drive-panel ${statusClass}">
        <div>
          <span class="section-tag">Exámenes vinculados con Drive</span>
          <h3>${escapeHtml(statusText)}</h3>
          <p>${escapeHtml(helper)}</p>
          <small>Mostrando ${examCount} examen(es) según el filtro actual.</small>
        </div>
        <div class="banco-drive-actions">
          <button class="btn-primary" type="button" data-banco-drive-sync>Reintentar sincronización</button>
          <a class="btn-secondary" href="${escapeAttribute(DRIVE_FOLDER_URL)}" target="_blank" rel="noopener noreferrer">Abrir carpeta Drive</a>
          ${isAdmin ? `<button class="btn-secondary" type="button" data-banco-add="${escapeAttribute((el.bancoFilterCiclo.value || CYCLES[0].id) + "|" + ((el.bancoSubjectChips?.dataset.subject && el.bancoSubjectChips.dataset.subject !== "all") ? el.bancoSubjectChips.dataset.subject : findCycle(el.bancoFilterCiclo.value || CYCLES[0].id)?.subjects[0]?.id || ""))}">Agregar enlace manual</button>` : ""}
        </div>
      </section>`;
    }

    function renderBancoSubjectChips() {
      if (!el.bancoSubjectChips) return;
      const activeSubject = el.bancoSubjectChips.dataset.subject || "all";
      const activeCycle = el.bancoSubjectChips.dataset.cycle || "";
      const cycle = findCycle(activeCycle);
      if (!cycle) {
        el.bancoSubjectChips.innerHTML = `
          <div class="filter-stage">
            <div class="filter-stage-header">
              <div>
                <strong>Filtro por materia</strong>
                <span>Primero selecciona un ciclo</span>
              </div>
            </div>
            <div class="filter-list">
              <button class="subject-chip ${activeSubject === "all" ? "active" : ""}" type="button" data-banco-subject="all">Todas las materias</button>
              ${CYCLES.map((item) => `<button class="filter-list-button" type="button" data-banco-cycle="${item.id}"><span>${item.name}</span><small>${item.subjects.length} materias</small></button>`).join("")}
            </div>
          </div>`;
        return;
      }
      el.bancoSubjectChips.innerHTML = `
        <div class="filter-stage">
          <button class="filter-back" type="button" data-banco-back>← Volver a ciclos</button>
          <div class="filter-stage-header">
            <div>
              <strong>${cycle.name}</strong>
              <span>Ahora elige una materia</span>
            </div>
          </div>
          <div class="filter-list">
            <button class="subject-chip ${activeSubject === "all" && el.bancoFilterCiclo.value === cycle.id ? "active" : ""}" type="button" data-banco-cycle-all="${cycle.id}">Todas las materias de ${cycle.name}</button>
            ${cycle.subjects.map((subject) => `<button class="subject-chip ${activeSubject === subject.id ? "active" : ""}" type="button" data-banco-subject="${subject.id}">${subject.name}</button>`).join("")}
          </div>
        </div>`;
    }

    function handleBancoSubjectChipClick(event) {
      const cycleButton = event.target.closest("[data-banco-cycle]");
      if (cycleButton) {
        el.bancoSubjectChips.dataset.cycle = cycleButton.dataset.bancoCycle;
        el.bancoSubjectChips.dataset.subject = "all";
        el.bancoFilterCiclo.value = cycleButton.dataset.bancoCycle;
        renderBanco();
        return;
      }
      const cycleAllButton = event.target.closest("[data-banco-cycle-all]");
      if (cycleAllButton) {
        el.bancoSubjectChips.dataset.cycle = cycleAllButton.dataset.bancoCycleAll;
        el.bancoSubjectChips.dataset.subject = "all";
        el.bancoFilterCiclo.value = cycleAllButton.dataset.bancoCycleAll;
        renderBanco();
        return;
      }
      const backButton = event.target.closest("[data-banco-back]");
      if (backButton) {
        delete el.bancoSubjectChips.dataset.cycle;
        renderBancoSubjectChips();
        return;
      }
      const chip = event.target.closest("[data-banco-subject]");
      if (!chip) return;
      el.bancoSubjectChips.dataset.subject = chip.dataset.bancoSubject;
      if (chip.dataset.bancoSubject === "all") {
        delete el.bancoSubjectChips.dataset.cycle;
        el.bancoFilterCiclo.value = "";
      } else {
        const cycle = findCycleBySubject(chip.dataset.bancoSubject);
        if (cycle) {
          el.bancoSubjectChips.dataset.cycle = cycle.id;
          el.bancoFilterCiclo.value = cycle.id;
        }
      }
      renderBanco();
    }

    function renderExamCycleTree(group) {
      return `<details><summary>${group.cycle.name} · ${group.subjects.reduce((sum, item) => sum + item.exams.length, 0)} exámenes</summary><div class="exam-subjects">${group.subjects.map(({ subject, exams }) => `<details><summary>${subject.name}${isAdmin ? ` <button class="mini-action" type="button" data-banco-add="${group.cycle.id}|${subject.id}">Agregar examen</button>` : ""}</summary><div class="exam-items">${exams.length ? exams.map((item, index) => renderExamCard(item, index)).join("") : `<div class="banco-empty-wrap compact">${renderEmpty("Sin exámenes registrados", "Sube el PDF en Google Drive: " + group.cycle.name + " / " + subject.name + " / Exámenes.")}</div>`}</div></details>`).join("")}</div></details>`;
    }

    function renderExamCard(item, index = 0) {
      const sourceLabel = item.source === DRIVE_RESOURCE_SOURCE ? "Google Drive" : "Local";
      const openUrl = materialOpenUrl(item);
      const downloadUrl = materialDownloadUrl(item);
      const canPreview = isPdfResource(item) || /drive\.google|docs\.google/i.test(item.url || item.webViewUrl || "");
      return `<article class="exam-card" style="--row-index:${index}">
        <strong>${escapeHtml(item.title)}</strong>
        <div class="portal-card-meta">
          <span class="exam-type-badge ${examTypeClass(inferExamType(item))}">${inferExamType(item)}</span>
          <span>${formatDate(item.date)}</span>
          <span>${escapeHtml(sourceLabel)}</span>
        </div>
        <p>${escapeHtml(item.description || "Examen disponible para consulta académica.")}</p>
        <div class="inline-actions">
          ${canPreview ? `<button class="btn-secondary" type="button" data-preview-pdf="${item.id}">Ver PDF</button>` : ""}
          <a class="card-action" href="${escapeAttribute(openUrl)}" target="_blank" rel="noopener noreferrer">Abrir en Drive</a>
          ${downloadUrl ? `<a class="btn-secondary" href="${escapeAttribute(downloadUrl)}" target="_blank" rel="noopener noreferrer">Descargar</a>` : ""}
          <button class="btn-secondary" type="button" data-calendar-exam="${item.id}">Añadir al calendario</button>
        </div>
      </article>`;
    }
    function handleBancoClick(event) {
      const syncDrive = event.target.closest("[data-banco-drive-sync]");
      const previewPdf = event.target.closest("[data-preview-pdf]");
      const add = event.target.closest("[data-banco-add]");
      const calendar = event.target.closest("[data-calendar-exam]");
      if (syncDrive) {
        syncDrive.disabled = true;
        syncDrive.textContent = "Sincronizando...";
        loadDriveRepositoryResources().then(() => {
          renderAll();
          showSection("banco", false);
          showToast("Drive actualizado", "Se volvió a cargar el banco de exámenes desde Google Drive.", "success");
        }).catch(() => {
          renderBanco();
          showToast("No se pudo sincronizar", "Revisa la implementación de Apps Script y los permisos de Drive.", "error");
        });
        return;
      }
      if (previewPdf) return openPdfModal(previewPdf.dataset.previewPdf);
      if (calendar) {
        const exam = visibleResources().find((item) => item.id === calendar.dataset.calendarExam);
        if (exam) downloadCalendarEvent({ id: exam.id, titulo: exam.title, fecha: exam.date, lugar: subjectName(exam.cycleId, exam.subjectId), descripcion: exam.description });
        return;
      }
      if (!add || !isAdmin) return;
      event.preventDefault();
      event.stopPropagation();
      const [cycleId, subjectId] = add.dataset.bancoAdd.split("|");
      openMaterialModal({ typeId: "examenes", cycleId, subjectId });
    }
    function inferExamType(item) {
      const text = normalize(`${item.title} ${item.description}`);
      if (text.includes("interciclo")) return "Interciclo";
      if (text.includes("final")) return "Final";
      if (text.includes("deber")) return "Deber";
      if (text.includes("practica")) return "Práctica";
      if (text.includes("leccion")) return "Lección";
      return "Examen";
    }
    function renderDocentes() {
      el.docentesContainer.innerHTML = appData.docentes.map((d) => {
        const phone = normalizePhone(d.whatsapp || "");
        const whatsapp = phone ? `<a class="btn-secondary" href="https://wa.me/${phone}" target="_blank" rel="noopener noreferrer">Enviar WhatsApp</a>` : `<button class="btn-secondary btn-disabled" type="button" disabled>WhatsApp no disponible</button>`;
        return `<article class="portal-card docente-card"><div class="docente-band"></div><span class="avatar-initials">${initials(d.nombre)}</span><h3>${escapeHtml(d.nombre)}</h3><p>${escapeHtml(d.titulo)}</p><p class="docente-materia">${escapeHtml(d.materia)}</p><div class="consulta-pill"><strong>Horas de consulta</strong><span>${escapeHtml(d.horario || "Horario por definir")}</span></div><div class="contact-icons"><a href="mailto:${escapeAttribute(d.email)}" title="Correo">✉</a><span title="${escapeAttribute(d.horario || "Horario por definir")}">H</span><span title="${escapeAttribute(d.materia)}">M</span></div><div class="inline-actions"><a class="card-action" href="mailto:${escapeAttribute(d.email)}">Enviar correo</a>${whatsapp}</div></article>`;
      }).join("") + renderSuggestionCard("Docentes", "Comparte de forma anónima una sugerencia sobre atención docente, horarios o comunicación.");
    }
    function renderSuggestionCard(title, text) {
      const url = appData.settings.suggestionFormUrl || "https://forms.gle/";
      return `<article class="suggestion-card"><span class="section-tag">Sugerencias</span><h3>Dejar sugerencia anónima</h3><p>${escapeHtml(text)}</p><a class="btn-secondary" href="${escapeAttribute(url)}" target="_blank" rel="noopener noreferrer">Abrir Google Forms</a></article>`;
    }
    function renderEventos() { const events = latest(appData.eventos, "fecha", 99); el.eventosContainer.innerHTML = events.length ? events.map(renderEventCard).join("") : renderEmpty("No hay eventos próximos", "Cuando se publiquen actividades aparecerán aquí."); }
    function renderRecursos() { el.recursosContainer.innerHTML = [["Repositorio", "repositorio"], ["Herramientas", "herramientas"], ["Tutorías", "tutorias"], ["Consultas", "consultas"], ["Buzón", "buzon"], ["Docentes", "docentes"], ["Eventos", "eventos"]].map(([label, tab]) => `<a class="quick-card" href="#${tab}" data-tab="${tab}"><strong>${label.slice(0, 2)}</strong><span>${label}</span></a>`).join(""); el.recursosContainer.querySelectorAll("[data-tab]").forEach((n) => n.addEventListener("click", (e) => { e.preventDefault(); showSection(n.dataset.tab, true); })); }
    function renderOportunidades() { el.oportunidadesContainer.innerHTML = latest(appData.oportunidades, "fecha", 99).map(renderOpportunityCard).join(""); }
    function renderComunidad() { el.comunidadContainer.innerHTML = ["Club de Lectura Económica", "Club de Investigación", "Boletín Económico", "Debates Económicos"].map((name) => `<article class="portal-card"><span class="portal-card-icon">${name.slice(0, 2)}</span><h3>${name}</h3><p>Espacio estudiantil para compartir, debatir y crear comunidad académica.</p></article>`).join(""); }
    function renderRepresentantes() {
      el.representantesContainer.innerHTML = appData.representantes.map((r) => `<article class="portal-card representante-card"><span class="avatar-initials">${initials(r.nombre)}</span><h3>${escapeHtml(r.nombre)}</h3><p>${escapeHtml(r.cargo)}</p><div class="portal-card-meta"><span>${escapeHtml(r.ciclo)}</span><span>${escapeHtml(r.email)}</span></div><p>${escapeHtml(r.funciones)}</p><div class="inline-actions rep-social-actions"><a class="btn-secondary" href="mailto:${escapeAttribute(r.email)}">Correo</a>${r.redes ? `<a class="btn-secondary" href="${escapeAttribute(r.redes)}" target="_blank" rel="noopener noreferrer">Redes sociales ↗</a>` : `<span class="schedule-source">Sin redes registradas</span>`}</div></article>`).join("");
    }
    function renderFAQ() { el.faqList.innerHTML = ["El repositorio se organiza por ciclo, materia y categoría.", "Los formularios se envían por FormSubmit al correo configurado.", "El panel admin permite editar contenido y exportar/importar datos.", "Los cambios se guardan en LocalStorage del navegador."].map((text, i) => `<article class="faq-item"><h3>Pregunta frecuente ${i + 1}</h3><p>${text}</p></article>`).join(""); }

    function renderGracias() {
      const wrap = document.querySelector("#gracias .section-wrap");
      if (!wrap) return;
      const last = loadJson("portal_last_thanks", null);
      const map = {
        consulta: ["Consulta registrada", "Tu consulta fue registrada. Te responderán por el medio indicado."],
        buzon: ["Solicitud registrada", "Tu solicitud fue registrada. El administrador la revisará en 24 a 48 horas."],
        tutoria: ["Inscripción registrada", "Tu inscripción fue registrada. El tutor te contactará pronto."],
        merch: ["Reserva registrada", "Tu reserva fue registrada. Te contactaremos para coordinar la entrega."]
      };
      const [title, text] = map[last?.type] || ["Gracias", "Tu información fue registrada correctamente."];
      wrap.innerHTML = `<div class="section-header"><span class="section-tag">Mensaje enviado</span><h2>${title}</h2><p>${text}</p>${last?.code ? `<div class="tracking-code">Código de seguimiento: <strong>${escapeHtml(last.code)}</strong></div>` : ""}</div><div class="quick-row" style="justify-content:center"><a class="btn-primary" href="#inicio" data-tab="inicio">Volver al inicio</a><a class="btn-secondary" href="#repositorio" data-tab="repositorio">Ir al repositorio</a><a class="btn-secondary" href="#perfil" data-profile-link>Ver historial</a></div>`;
      wrap.querySelectorAll("[data-tab]").forEach((node) => node.addEventListener("click", (event) => {
        event.preventDefault();
        showSection(node.dataset.tab, true);
      }));
      wrap.querySelector("[data-profile-link]")?.addEventListener("click", (event) => {
        event.preventDefault();
        openProfilePanel();
      });
    }

    function renderEventCard(item) {
      const date = dateParts(item.fecha);
      return `<article class="portal-card event-card"><div class="event-date-card"><span class="month">${date.month}</span><span class="day">${date.day}</span></div><div><h3>${escapeHtml(item.titulo)}</h3><p>${escapeHtml(item.descripcion)}</p><div class="portal-card-meta"><span>${formatDate(item.fecha)}</span><span>${escapeHtml(item.lugar)}</span></div><div class="inline-actions calendar-action">${item.link ? `<a class="card-action" href="${escapeAttribute(item.link)}" target="_blank">Inscribirme</a>` : ""}<button class="btn-secondary" type="button" data-calendar-event="${item.id}">Añadir al calendario</button></div></div></article>`;
    }
    function renderCompactEvent(item) {
      const date = dateParts(item.fecha);
      return `<article class="portal-card home-highlight-card">
        <div class="home-date-pill"><span>${date.month}</span><strong>${date.day}</strong></div>
        <div class="home-highlight-body">
          <h3>${escapeHtml(item.titulo)}</h3>
          <p>${formatDate(item.fecha)} · ${escapeHtml(item.lugar || "Lugar por definir")}</p>
          <div class="inline-actions compact-actions">
            <button class="mini-action" type="button" data-calendar-event="${item.id}">Calendario</button>
            <button class="mini-action" type="button" data-tab="eventos">Ver eventos</button>
          </div>
        </div>
      </article>`;
    }
    function renderOpportunityCard(item) {
      const urgent = daysUntil(item.fecha) <= 7;
      return `<article class="portal-card opportunity-card">${urgent ? `<span class="urgency-badge">Próximo a vencer</span>` : ""}<span class="portal-card-icon">${escapeHtml(item.tipo.slice(0, 2))}</span><h3>${escapeHtml(item.titulo)}</h3><p>${escapeHtml(item.descripcion)}</p><div class="portal-card-meta"><span>${escapeHtml(item.institucion)}</span><span>Hasta: ${formatDate(item.fecha)}</span></div>${item.link ? `<a class="card-action" href="${escapeAttribute(item.link)}" target="_blank">Postular</a>` : ""}</article>`;
    }
    function renderCompactOpportunity(item) {
      const remaining = daysUntil(item.fecha);
      const urgent = Number.isFinite(remaining) && remaining >= 0 && remaining <= 7;
      return `<article class="portal-card home-highlight-card opportunity-mini-card">
        <div class="home-type-pill ${urgent ? "urgent" : ""}">${urgent ? "Próximo" : escapeHtml(item.tipo.slice(0, 3).toUpperCase())}</div>
        <div class="home-highlight-body">
          <h3>${escapeHtml(item.titulo)}</h3>
          <p>${escapeHtml(item.tipo)} · ${escapeHtml(item.institucion)}</p>
          <div class="inline-actions compact-actions">
            ${item.link ? `<a class="mini-action" href="${escapeAttribute(item.link)}" target="_blank" rel="noopener noreferrer">Abrir</a>` : ""}
            <button class="mini-action" type="button" data-tab="oportunidades">Ver más</button>
          </div>
        </div>
      </article>`;
    }

    function handleEventActions(event) {
      const button = event.target.closest("[data-calendar-event]");
      if (!button) return;
      const item = (appData.eventos || []).find((eventItem) => eventItem.id === button.dataset.calendarEvent);
      if (!item) return;
      downloadCalendarEvent(item);
    }

    function downloadCalendarEvent(item) {
      const start = calendarDate(item.fecha);
      const endDate = new Date(String(item.fecha || new Date().toISOString().slice(0, 10)) + "T00:00:00");
      endDate.setDate(endDate.getDate() + 1);
      const end = calendarDate(endDate.toISOString().slice(0, 10));
      const ics = [
        "BEGIN:VCALENDAR",
        "VERSION:2.0",
        "PRODID:-//Portal Economia UCuenca//ES",
        "BEGIN:VEVENT",
        `UID:${item.id}@portal-economia-ucuenca`,
        `DTSTAMP:${calendarTimestamp(new Date())}`,
        `DTSTART;VALUE=DATE:${start}`,
        `DTEND;VALUE=DATE:${end}`,
        `SUMMARY:${icsText(item.titulo)}`,
        `DESCRIPTION:${icsText(item.descripcion || "Evento académico")}`,
        `LOCATION:${icsText(item.lugar || "Universidad de Cuenca")}`,
        "END:VEVENT",
        "END:VCALENDAR"
      ].join("\r\n");
      const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${slugify(item.titulo || "evento")}.ics`;
      a.click();
      URL.revokeObjectURL(url);
      showToast("Evento descargado", "Puedes abrir el archivo .ics para añadirlo a tu calendario.", "success");
    }

    function calendarDate(value) {
      return String(value || new Date().toISOString().slice(0, 10)).replaceAll("-", "");
    }

    function calendarTimestamp(date) {
      return date.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
    }

    function icsText(value) {
      return String(value || "").replace(/\\/g, "\\\\").replace(/\n/g, "\\n").replace(/,/g, "\\,").replace(/;/g, "\\;");
    }

    function openApp(appId) {
      const config = APP_CONFIG[appId];
      if (!config) return;
      activeApp = appId;
      activeAppMode = config.mode;
      if (config.mode === "panel") {
        closeApp("modal");
        el.appPanel.dataset.activeApp = appId;
        el.appPanelTitle.textContent = config.title;
        el.appPanelCrumb.textContent = config.crumb;
        el.appPanel.hidden = false;
        el.appBackdrop.hidden = false;
        renderActiveApp();
        requestAnimationFrame(() => {
          el.appPanel.classList.add("open");
          el.appBackdrop.classList.add("open");
        });
      } else {
        closeApp("panel");
        el.appModal.dataset.activeApp = appId;
        el.appModalTitle.textContent = config.title;
        el.appModalCrumb.textContent = config.crumb;
        el.appModal.hidden = false;
        renderActiveApp();
        el.appModal.classList.add("open");
        resetActiveAppScroll();
        requestAnimationFrame(() => {
          el.appModal.classList.add("open");
          resetActiveAppScroll();
          setTimeout(resetActiveAppScroll, 80);
        });
      }
    }

    function closeApp(scope = "all") {
      if (typeof scope !== "string") scope = "all";
      if ((scope === "all" || scope === "panel") && el.appPanel && !el.appPanel.hidden) {
        el.appPanel.classList.remove("open");
        el.appBackdrop?.classList.remove("open");
        setTimeout(() => {
          if (!el.appPanel.classList.contains("open")) {
            el.appPanel.hidden = true;
            el.appPanel.removeAttribute("data-active-app");
            if (el.appBackdrop) el.appBackdrop.hidden = true;
          }
        }, 260);
      }
      if ((scope === "all" || scope === "modal") && el.appModal && !el.appModal.hidden) {
        el.appModal.classList.remove("open");
        setTimeout(() => {
          if (!el.appModal.classList.contains("open")) {
            el.appModal.hidden = true;
            el.appModal.removeAttribute("data-active-app");
          }
        }, 300);
      }
      if (scope === "all") activeApp = null;
    }

    function openDriveRepositoryNotice() {
      const savedUrl = appData.settings.simplifiedDriveUrl || "";
      const url = savedUrl && savedUrl !== "https://drive.google.com/" ? savedUrl : DRIVE_FOLDER_URL;
      const overlay = document.createElement("div");
      overlay.className = "drive-notice-modal";
      overlay.innerHTML = `<article class="drive-notice-card" role="dialog" aria-modal="true" aria-labelledby="driveNoticeTitle">
        <button class="syllabus-back" type="button" data-close-drive-notice>← Atrás</button>
        <span class="section-tag">Repositorio alternativo</span>
        <h3 id="driveNoticeTitle">Drive / repositorio simplificado</h3>
        <p>Este enlace de Drive queda habilitado como respaldo en caso de emergencia, caída de conexión o necesidad de acceso rápido. El repositorio principal recomendado sigue siendo esta página web, porque aquí los materiales están organizados por ciclo, materia, tipo, favoritos y búsqueda dinámica.</p>
        <div class="drive-notice-actions">
          <a class="btn-primary ${url ? "" : "disabled"}" href="${escapeAttribute(url || "#")}" target="_blank" rel="noopener noreferrer" aria-label="Abrir repositorio simplificado en Drive">Abrir Drive ↗</a>
          <button class="btn-secondary" type="button" data-tab-from-drive="repositorio">Usar repositorio web</button>
        </div>
      </article>`;
      const close = () => {
        document.removeEventListener("keydown", onKeydown);
        overlay.remove();
      };
      const onKeydown = (event) => { if (event.key === "Escape") close(); };
      overlay.addEventListener("click", (event) => {
        if (event.target === overlay || event.target.closest("[data-close-drive-notice]")) close();
        if (event.target.closest("[data-tab-from-drive]")) {
          close();
          showSection("repositorio", true);
        }
      });
      document.addEventListener("keydown", onKeydown);
      document.body.appendChild(overlay);
      overlay.querySelector("[data-close-drive-notice]")?.focus();
    }

    function activeAppContainer() {
      return activeAppMode === "panel" ? el.appPanelContent : el.appModalContent;
    }

    function resetActiveAppScroll() {
      const container = activeAppContainer();
      [container, el.appModal, el.appPanel].forEach((node) => {
        if (!node) return;
        node.scrollTop = 0;
        node.scrollLeft = 0;
        node.scrollTo?.({ top: 0, left: 0, behavior: "auto" });
      });
    }

    function renderActiveApp() {
      const container = activeAppContainer();
      if (!container || !activeApp) return;
      const renderers = {
        apa: renderApaApp,
        notesExchange: renderNotesExchangeApp,
        studyGroups: renderStudyGroupsApp,
        achievements: renderAchievementsApp,
        glossary: renderGlossaryApp,
        quiz: renderQuizApp,
        timeline: renderTimelineApp,
        tasks: renderTasksApp
      };
      container.innerHTML = renderers[activeApp]?.() || renderEmpty("Aplicación no disponible", "Este módulo todavía no está configurado.");
      resetActiveAppScroll();
    }

    function handleAppClick(event) {
      const tab = event.target.closest("[data-app-tab]");
      if (tab) {
        const value = tab.dataset.appTab;
        if (activeApp === "apa") apaType = value;
        if (activeApp === "notesExchange") notesTab = value;
        if (activeApp === "studyGroups") groupsTab = value;
        renderActiveApp();
        return;
      }
      const action = event.target.closest("[data-app-action]");
      if (!action) return;
      const name = action.dataset.appAction;
      if (name === "apa-copy") return copyGeneratedApa();
      if (name === "apa-save") return saveGeneratedApa();
      if (name === "apa-export") return exportApaList();
      if (name === "apa-delete") return deleteApa(action.dataset.id);
      if (name === "note-save") return saveNote(action.dataset.id);
      if (name === "note-rate") return rateNote(action.dataset.id, Number(action.dataset.value || 0));
      if (name === "group-detail") { selectedGroupId = action.dataset.id; return renderActiveApp(); }
      if (name === "group-back") { selectedGroupId = null; return renderActiveApp(); }
      if (name === "task-form") { taskShowForm = !taskShowForm; return renderActiveApp(); }
      if (name === "task-delete") return deleteTask(action.dataset.id);
      if (name === "glossary-detail") { glossaryState.detailId = action.dataset.id; return renderActiveApp(); }
      if (name === "glossary-reset") { glossaryState = { query: "", category: "all", difficulty: "all", detailId: "", quiz: null }; return renderActiveApp(); }
      if (name === "glossary-quiz") { glossaryState.quiz = startGlossaryQuiz(); return renderActiveApp(); }
      if (name === "glossary-answer") return answerGlossaryQuiz(Number(action.dataset.value));
      if (name === "quiz-start") return startMainQuiz();
      if (name === "quiz-answer") return answerMainQuiz(Number(action.dataset.value));
      if (name === "quiz-next") return nextMainQuiz();
      if (name === "quiz-reset") { quizState = { running: false, questions: [], index: 0, answers: [], selected: null, lastCorrect: null, saved: false }; return renderActiveApp(); }
      if (name === "timeline-school") { timelineSchool = action.dataset.value; return renderActiveApp(); }
    }

    function handleAppSubmit(event) {
      if (!event.target.matches("[data-app-form]")) return;
      event.preventDefault();
      const form = event.target;
      const type = form.dataset.appForm;
      if (type === "apa") generateApa(form);
      if (type === "note") createNote(form);
      if (type === "group") createStudyGroup(form);
      if (type === "join-group") joinStudyGroup(form);
      if (type === "group-chat") addGroupChat(form);
      if (type === "task") createTask(form);
      renderActiveApp();
    }

    function handleAppInput(event) {
      if (!activeApp) return;
      if (event.target.matches("[data-glossary-query]")) {
        glossaryState.query = event.target.value;
        renderActiveApp();
        setTimeout(() => {
          const input = activeAppContainer()?.querySelector("[data-glossary-query]");
          if (input) {
            input.focus();
            input.setSelectionRange(input.value.length, input.value.length);
          }
        }, 0);
      }
      if (event.target.matches("[data-group-search]")) {
        event.target.closest(".app-modal-body").querySelectorAll("[data-group-card]").forEach((card) => {
          card.hidden = !normalize(card.textContent).includes(normalize(event.target.value));
        });
      }
    }

    function handleAppChange(event) {
      if (!activeApp) return;
      if (event.target.matches("[data-glossary-category]")) {
        glossaryState.category = event.target.value;
        renderActiveApp();
      }
      if (event.target.matches("[data-glossary-difficulty]")) {
        glossaryState.difficulty = event.target.value;
        renderActiveApp();
      }
      if (event.target.matches("[data-task-status]")) updateTaskStatus(event.target.dataset.id, event.target.value);
      if (event.target.id === "quizCycle") {
        const subjectSelect = document.getElementById("quizSubject");
        if (subjectSelect) subjectSelect.innerHTML = subjectOptions(event.target.value, "");
      }
    }

    function renderApaApp() {
      const tabs = ["book", "article", "web", "thesis", "chapter"];
      const labels = { book: "Libro", article: "Artículo", web: "Sitio web", thesis: "Tesis", chapter: "Capítulo" };
      const list = loadJson(APA_KEY, []);
      return `<div class="app-tabs">${tabs.map((id) => `<button class="app-tab ${apaType === id ? "active" : ""}" type="button" data-app-tab="${id}">${labels[id]}</button>`).join("")}</div>
        <form class="portal-form-grid" data-app-form="apa">
          <input type="hidden" name="type" value="${apaType}">
          ${apaFields(apaType)}
          <button class="btn-primary full" type="submit">Generar cita APA</button>
        </form>
        ${generatedApa ? `<div class="apa-output">${generatedApa}</div><div class="inline-actions"><button class="btn-secondary" type="button" data-app-action="apa-copy">Copiar</button><button class="btn-primary" type="button" data-app-action="apa-save">Guardar en mi lista</button></div>` : ""}
        <div class="view-heading"><div><h3>Mi biblioteca</h3><p>${list.length} citas guardadas.</p></div><button class="btn-secondary" type="button" data-app-action="apa-export">Exportar todo</button></div>
        <div class="admin-list">${list.length ? list.map((item) => `<div class="admin-row"><div>${item.html}</div><button class="btn-danger" type="button" data-app-action="apa-delete" data-id="${item.id}">Eliminar</button></div>`).join("") : renderEmpty("Sin citas guardadas", "Genera y guarda referencias para crear tu bibliografía.")}</div>`;
    }

    function apaFields(type) {
      const common = `<label><span>Autor</span><input name="author" placeholder="Apellido, N." required></label><label><span>Año</span><input name="year" placeholder="2026" required></label><label class="full"><span>Título</span><input name="title" required></label>`;
      if (type === "article") return `${common}<label><span>Revista</span><input name="container" required></label><label><span>Volumen/Número</span><input name="volume"></label><label><span>DOI o URL</span><input name="url"></label>`;
      if (type === "web") return `${common}<label><span>Sitio web</span><input name="container" required></label><label class="full"><span>URL</span><input name="url" required></label>`;
      if (type === "thesis") return `${common}<label><span>Universidad</span><input name="container" required></label><label><span>Tipo</span><input name="volume" value="Tesis"></label><label><span>URL</span><input name="url"></label>`;
      if (type === "chapter") return `${common}<label><span>Libro</span><input name="container" required></label><label><span>Páginas</span><input name="volume" placeholder="pp. 12-28"></label><label><span>Editorial</span><input name="publisher"></label>`;
      return `${common}<label><span>Editorial</span><input name="publisher" required></label><label><span>URL o DOI</span><input name="url"></label>`;
    }

    function generateApa(form) {
      const data = Object.fromEntries(new FormData(form));
      const author = formatApaAuthor(data.author);
      const year = escapeHtml(data.year || "s. f.");
      const title = escapeHtml(data.title || "Sin título");
      const url = data.url ? ` ${escapeHtml(data.url)}` : "";
      if (data.type === "article") generatedApa = `${author} (${year}). ${title}. <em>${escapeHtml(data.container || "Revista")}</em>${data.volume ? `, ${escapeHtml(data.volume)}` : ""}.${url}`;
      else if (data.type === "web") generatedApa = `${author} (${year}). <em>${title}</em>. ${escapeHtml(data.container || "Sitio web")}.${url}`;
      else if (data.type === "thesis") generatedApa = `${author} (${year}). <em>${title}</em> [${escapeHtml(data.volume || "Tesis")}]. ${escapeHtml(data.container || "Universidad")}.${url}`;
      else if (data.type === "chapter") generatedApa = `${author} (${year}). ${title}. En <em>${escapeHtml(data.container || "Libro")}</em>${data.volume ? ` (${escapeHtml(data.volume)})` : ""}. ${escapeHtml(data.publisher || "Editorial")}.${url}`;
      else generatedApa = `${author} (${year}). <em>${title}</em>. ${escapeHtml(data.publisher || "Editorial")}.${url}`;
      showToast("Cita generada", "Puedes copiarla o guardarla en tu biblioteca.", "success");
    }

    function formatApaAuthor(value) {
      const text = String(value || "Autor desconocido").trim();
      const [last, rest] = text.split(",").map((part) => part.trim());
      return `${escapeHtml((last || text).toUpperCase())}${rest ? `, ${escapeHtml(rest)}` : ""}`;
    }

    function copyGeneratedApa() {
      const plain = generatedApa.replace(/<[^>]+>/g, "");
      navigator.clipboard?.writeText(plain).then(() => showToast("Copiado", "La cita APA está en el portapapeles.", "success")).catch(() => showToast("No se pudo copiar", "Selecciona la cita manualmente.", "error"));
    }

    function saveGeneratedApa() {
      if (!generatedApa) return;
      const list = loadJson(APA_KEY, []);
      localStorage.setItem(APA_KEY, JSON.stringify([...list, { id: uid(), html: generatedApa, text: generatedApa.replace(/<[^>]+>/g, "") }]));
      document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: 10, reason: "Cita APA guardada" } }));
      checkAchievements();
      renderActiveApp();
    }

    function deleteApa(id) {
      localStorage.setItem(APA_KEY, JSON.stringify(loadJson(APA_KEY, []).filter((item) => item.id !== id)));
      renderActiveApp();
    }

    function exportApaList() {
      const list = loadJson(APA_KEY, []).map((item) => item.text).sort().join("\n\n");
      downloadText("bibliografia-apa.txt", list || "Sin citas guardadas.");
    }

    function renderNotesExchangeApp() {
      const notes = loadJson(NOTES_EXCHANGE_KEY, []);
      const mine = notes.filter((n) => n.mine);
      const saved = loadJson("savedNotes", []);
      const filtered = notesTab === "mine" ? mine : notesTab === "saved" ? notes.filter((n) => saved.includes(n.id)) : notes;
      return `<div class="app-tabs">${["explore:Explorar apuntes", "mine:Mis apuntes subidos", "saved:Mis apuntes guardados"].map((pair) => { const [id, label] = pair.split(":"); return `<button class="app-tab ${notesTab === id ? "active" : ""}" type="button" data-app-tab="${id}">${label}</button>`; }).join("")}</div>
        <form class="portal-form-grid" data-app-form="note"><label><span>Título</span><input name="title" required></label><label><span>Ciclo</span><select name="cycle">${cycleOptionsHtml()}</select></label><label><span>Materia</span><select name="subject">${subjectOptionsHtml()}</select></label><label class="full"><span>Descripción</span><input name="description" maxlength="200" required></label><label class="full"><span>Contenido del apunte</span><textarea name="content" required></textarea></label><button class="btn-primary full" type="submit">Subir apunte</button></form>
        <div class="app-grid">${filtered.length ? filtered.map((note) => renderNoteCard(note, mine)).join("") : renderEmpty("No hay apuntes aún", "Sube el primer apunte para desbloquear el intercambio.")}</div>`;
    }

    function renderNoteCard(note, mine) {
      const unlocked = note.mine || mine.some((item) => item.cycle === note.cycle);
      const avg = note.votes?.length ? (note.votes.reduce((a, b) => a + b, 0) / note.votes.length).toFixed(1) : "0.0";
      return `<article class="app-card" data-note-id="${note.id}"><span class="badge-blue">${escapeHtml(findCycle(note.cycle)?.name || "Ciclo")}</span><h3>${escapeHtml(note.title)}</h3><p>${escapeHtml(note.description)}</p><small>${escapeHtml(subjectById(note.subject)?.name || note.subject)} · ${escapeHtml(note.author || "Estudiante C3")} · ${formatDate(note.date)}</small><div>${unlocked ? `<p>${escapeHtml(note.content).slice(0, 260)}...</p><div class="inline-actions">${[1,2,3,4,5].map((star) => `<button class="btn-secondary" type="button" data-app-action="note-rate" data-id="${note.id}" data-value="${star}">${star}</button>`).join("")}<button class="btn-secondary" type="button" data-app-action="note-save" data-id="${note.id}">Guardar</button></div>` : `<p><strong>Bloqueado.</strong> Sube un apunte propio de este ciclo para desbloquearlo.</p>`}</div><span class="badge-gold">Calidad ${avg}/5</span></article>`;
    }

    function createNote(form) {
      const data = Object.fromEntries(new FormData(form));
      const notes = loadJson(NOTES_EXCHANGE_KEY, []);
      notes.unshift({ id: uid(), ...data, author: "Estudiante C3", date: new Date().toISOString().slice(0, 10), mine: true, votes: [], saved: false });
      localStorage.setItem(NOTES_EXCHANGE_KEY, JSON.stringify(notes));
      form.reset();
      document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: 20, reason: "Apunte subido" } }));
      checkAchievements();
      showToast("Apunte publicado", "El intercambio se actualizó correctamente.", "success");
    }

    function saveNote(id) {
      const saved = new Set(loadJson("savedNotes", []));
      saved.add(id);
      localStorage.setItem("savedNotes", JSON.stringify([...saved]));
      showToast("Apunte guardado", "Lo verás en Mis apuntes guardados.", "success");
    }

    function rateNote(id, value) {
      const notes = loadJson(NOTES_EXCHANGE_KEY, []);
      const note = notes.find((item) => item.id === id);
      if (note) note.votes = [...(note.votes || []), value].slice(-30);
      localStorage.setItem(NOTES_EXCHANGE_KEY, JSON.stringify(notes));
      renderActiveApp();
    }

    function renderStudyGroupsApp() {
      const groups = loadJson(STUDY_GROUPS_KEY, defaultStudyGroups());
      if (selectedGroupId) return renderStudyGroupDetail(groups.find((g) => g.id === selectedGroupId));
      const mine = groups.filter((g) => (g.members || []).some((m) => m.mine));
      const list = groupsTab === "mine" ? mine : groups;
      return `<div class="app-tabs"><button class="app-tab ${groupsTab === "explore" ? "active" : ""}" type="button" data-app-tab="explore">Explorar grupos</button><button class="app-tab ${groupsTab === "mine" ? "active" : ""}" type="button" data-app-tab="mine">Mi grupo</button></div>
        <input class="repo-search" type="search" data-group-search placeholder="Buscar por materia o grupo">
        <form class="portal-form-grid" data-app-form="group"><label><span>Nombre del grupo</span><input name="name" required></label><label><span>Ciclo</span><select name="cycle">${cycleOptionsHtml()}</select></label><label><span>Materia</span><select name="subject">${subjectOptionsHtml()}</select></label><label><span>Modalidad</span><select name="mode"><option>Presencial</option><option>Virtual</option></select></label><label><span>Día</span><input name="day" placeholder="Martes" required></label><label><span>Hora inicio</span><input name="start" type="time" required></label><label><span>Hora fin</span><input name="end" type="time" required></label><label><span>Lugar o Meet</span><input name="place" required></label><label><span>Máximo</span><input name="max" type="number" min="2" value="8"></label><label class="full"><span>Descripción</span><input name="description"></label><button class="btn-primary full" type="submit">Crear grupo</button></form>
        <div class="app-grid">${list.map(renderStudyGroupCard).join("") || renderEmpty("Sin grupos activos", "Crea el primer grupo de estudio.")}</div>`;
    }

    function renderStudyGroupCard(group) {
      return `<article class="app-card" data-group-card><h3>${escapeHtml(group.name)}</h3><p>${escapeHtml(subjectById(group.subject)?.name || group.subject)} · ${escapeHtml(findCycle(group.cycle)?.name || "")}</p><div class="portal-card-meta"><span>${escapeHtml(group.day)} ${escapeHtml(group.start)}-${escapeHtml(group.end)}</span><span>${(group.members || []).length}/${group.max} miembros</span></div><p>${escapeHtml(group.place)}</p><div class="inline-actions"><button class="btn-primary" type="button" data-app-action="group-detail" data-id="${group.id}">Ver detalles</button></div></article>`;
    }

    function renderStudyGroupDetail(group) {
      if (!group) return renderEmpty("Grupo no encontrado", "Vuelve a explorar grupos.");
      return `<button class="btn-secondary" type="button" data-app-action="group-back">Volver</button><article class="app-card"><h3>${escapeHtml(group.name)}</h3><p>${escapeHtml(group.description || "Grupo de estudio activo.")}</p><div class="portal-card-meta"><span>${escapeHtml(group.mode)}</span><span>${escapeHtml(group.day)} ${escapeHtml(group.start)}-${escapeHtml(group.end)}</span><span>${escapeHtml(group.place)}</span></div></article>
        <form class="portal-form-grid" data-app-form="join-group"><input type="hidden" name="groupId" value="${group.id}"><label><span>Nombre o apodo</span><input name="name" required></label><button class="btn-primary" type="submit">Unirse</button></form>
        <div class="app-grid"><article class="app-card"><h3>Miembros</h3>${(group.members || []).map((m) => `<p>${escapeHtml(m.name)}</p>`).join("") || "<p>Sin miembros aún.</p>"}</article><article class="app-card"><h3>Chat del grupo</h3>${(group.chat || []).map((m) => `<p><strong>${escapeHtml(m.name)}</strong> · ${escapeHtml(m.time)}<br>${escapeHtml(m.text)}</p>`).join("") || "<p>Sin mensajes.</p>"}<form data-app-form="group-chat"><input type="hidden" name="groupId" value="${group.id}"><label><span>Mensaje</span><input name="text" required></label><button class="btn-secondary" type="submit">Enviar</button></form></article><article class="app-card"><h3>Tablón</h3><p>${escapeHtml(group.board || "Usa este espacio para acuerdos, lecturas y recordatorios del grupo.")}</p></article></div>`;
    }

    function createStudyGroup(form) {
      const groups = loadJson(STUDY_GROUPS_KEY, defaultStudyGroups());
      groups.unshift({ id: uid(), ...Object.fromEntries(new FormData(form)), members: [], chat: [], board: "" });
      localStorage.setItem(STUDY_GROUPS_KEY, JSON.stringify(groups));
      form.reset();
      document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: 35, reason: "Grupo de estudio creado" } }));
      checkAchievements();
      showToast("Grupo creado", "Ya aparece en el directorio.", "success");
    }

    function joinStudyGroup(form) {
      const data = Object.fromEntries(new FormData(form));
      const groups = loadJson(STUDY_GROUPS_KEY, defaultStudyGroups());
      const group = groups.find((item) => item.id === data.groupId);
      if (group && (group.members || []).length < Number(group.max || 8)) group.members = [...(group.members || []), { name: data.name, mine: true }];
      localStorage.setItem(STUDY_GROUPS_KEY, JSON.stringify(groups));
      showToast("Inscripción registrada", "Ya formas parte del grupo.", "success");
    }

    function addGroupChat(form) {
      const data = Object.fromEntries(new FormData(form));
      const groups = loadJson(STUDY_GROUPS_KEY, defaultStudyGroups());
      const group = groups.find((item) => item.id === data.groupId);
      if (group) group.chat = [...(group.chat || []), { name: studentProfile.name || "Estudiante", text: data.text, time: new Date().toLocaleTimeString("es-EC", { hour: "2-digit", minute: "2-digit" }) }];
      localStorage.setItem(STUDY_GROUPS_KEY, JSON.stringify(groups));
      form.reset();
    }

    function renderAchievementsApp() {
      const state = achievementState();
      const badges = achievementDefinitions();
      const rank = xpRank(state.xp);
      const unlocked = badges.filter((badge) => state.badges.includes(badge.id)).length;
      return `<article class="achievement-summary">
        <div>
          <span class="badge-gold">${rank.name}</span>
          <h3>${state.xp} XP</h3>
          <p>${rank.next}</p>
        </div>
        <strong>${unlocked}/${badges.length}</strong>
      </article>
      <div class="curriculum-progress achievement-progress"><span style="width:${rank.progress}%"></span></div>
      <div class="achievement-list">${badges.map((badge) => {
        const done = state.badges.includes(badge.id);
        return `<article class="achievement-item ${done ? "is-unlocked" : "is-locked"}">
          <span class="achievement-dot">${done ? "OK" : ""}</span>
          <div>
            <h3>${escapeHtml(badge.name)}</h3>
            <p>${escapeHtml(badge.description)}</p>
          </div>
          <span class="badge-gold">${badge.xp} XP</span>
        </article>`;
      }).join("")}</div>`;
    }

    function handleXpEarned(event) {
      const amount = Number(event.detail?.amount || 0);
      if (!amount) return;
      const state = achievementState();
      state.xp += amount;
      localStorage.setItem(ACHIEVEMENTS_KEY, JSON.stringify(state));
    }

    function checkAchievements() {
      const state = achievementState();
      achievementDefinitions().forEach((badge) => {
        if (!state.badges.includes(badge.id) && badge.condition()) unlockBadge(state, badge);
      });
      localStorage.setItem(ACHIEVEMENTS_KEY, JSON.stringify(state));
    }

    function unlockBadge(state, badge) {
      state.badges.push(badge.id);
      state.xp += badge.xp;
      showXpToast(`Insignia desbloqueada: ${badge.name}`, `+${badge.xp} XP`);
    }

    function achievementState() {
      const state = loadJson(ACHIEVEMENTS_KEY, { xp: 0, badges: [], visits: [] });
      const today = new Date().toISOString().slice(0, 10);
      if (!state.visits.includes(today)) state.visits = [...state.visits, today].slice(-14);
      localStorage.setItem(ACHIEVEMENTS_KEY, JSON.stringify(state));
      return state;
    }

    function achievementDefinitions() {
      return [
        { id: "first-upload", name: "Primera subida", xp: 50, description: "Subir el primer material al repositorio.", condition: () => appData.resources.length > 0 },
        { id: "schedule-full", name: "Horario completo", xp: 75, description: "Llenar los cinco días del horario.", condition: () => new Set((appData.studentSchedules || []).map((i) => i.day)).size >= 5 },
        { id: "pomodoro-pro", name: "Pomodoro Pro", xp: 100, description: "Completar 10 sesiones Pomodoro.", condition: () => pomodoroSessions >= 10 },
        { id: "curriculum-half", name: "Malla al día", xp: 150, description: "Aprobar más del 50% de materias.", condition: () => Object.values(appData.curriculumStatus || {}).filter((s) => s === "aprobada").length / countSubjects() > 0.5 },
        { id: "apa-reader", name: "Bibliófilo", xp: 80, description: "Guardar 10 citas APA.", condition: () => loadJson(APA_KEY, []).length >= 10 },
        { id: "notes-master", name: "Maestro de apuntes", xp: 120, description: "Subir 5 apuntes.", condition: () => loadJson(NOTES_EXCHANGE_KEY, []).filter((n) => n.mine).length >= 5 },
        { id: "leader", name: "Líder estudiantil", xp: 100, description: "Crear un grupo de estudio.", condition: () => loadJson(STUDY_GROUPS_KEY, []).length > 0 },
        { id: "quiz-master", name: "Quiz master", xp: 90, description: "Completar 5 quizzes.", condition: () => loadJson(QUIZ_HISTORY_KEY, []).length >= 5 },
        { id: "streak", name: "Racha de 7 días", xp: 200, description: "Ingresar al portal 7 días distintos.", condition: () => achievementState().visits.length >= 7 }
      ];
    }

    function xpRank(xp) {
      const ranks = [[0, 100, "Estudiante Novato"], [101, 300, "Analista Económico"], [301, 600, "Economista Junior"], [601, 1000, "Economista Senior"], [1001, Infinity, "Maestro de la Economía"]];
      const current = ranks.find(([min, max]) => xp >= min && xp <= max) || ranks[0];
      const next = current[1] === Infinity ? "Rango máximo alcanzado." : `Siguiente rango en ${Math.max(0, current[1] + 1 - xp)} XP.`;
      const progress = current[1] === Infinity ? 100 : Math.round(((xp - current[0]) / (current[1] - current[0] + 1)) * 100);
      return { name: current[2], progress, next };
    }

    function renderGlossaryApp() {
      const terms = glossaryTerms().filter((term) => (!glossaryState.query || normalize(`${term.term} ${term.definition}`).includes(normalize(glossaryState.query))) && (glossaryState.category === "all" || term.category === glossaryState.category) && (glossaryState.difficulty === "all" || term.difficulty === glossaryState.difficulty));
      const detail = glossaryTerms().find((term) => term.id === glossaryState.detailId) || terms[0];
      const categories = ["all", ...new Set(glossaryTerms().map((term) => term.category))];
      const activeCategory = glossaryState.category === "all" ? "Todas las áreas" : glossaryState.category;
      const activeDifficulty = glossaryState.difficulty === "all" ? "Todos los niveles" : glossaryState.difficulty;
      return `<section class="glossary-app glossary-app-pro">
        <div class="glossary-hero">
          <div>
            <span class="section-tag">Glosario académico</span>
            <h3>Conceptos económicos para estudiar y responder mejor</h3>
            <p>Busca por término, filtra por área y revisa definición, fórmula, ejemplo aplicado y uso académico sin perder el contexto.</p>
          </div>
          <div class="glossary-hero-metrics" aria-label="Resumen del glosario">
            <span><strong>${terms.length}</strong><small>resultados</small></span>
            <span><strong>${categories.length - 1}</strong><small>áreas</small></span>
          </div>
          <div class="glossary-hero-actions">
            <button class="btn-secondary" type="button" data-app-action="glossary-reset">Limpiar filtros</button>
            <button class="btn-primary" type="button" data-app-action="glossary-quiz">Modo Quiz</button>
          </div>
        </div>
        ${glossaryState.quiz ? renderGlossaryQuiz() : `<div class="glossary-layout">
          <div class="glossary-main-column">
            <div class="tools-grid glossary-tools">
              <input class="repo-search" data-glossary-query value="${escapeAttribute(glossaryState.query)}" placeholder="Buscar término económico">
              <select data-glossary-category>${categories.map((cat) => `<option value="${cat}" ${glossaryState.category === cat ? "selected" : ""}>${cat === "all" ? "Todas las categorías" : cat}</option>`).join("")}</select>
              <select data-glossary-difficulty>${["all", "básico", "intermedio", "avanzado"].map((d) => `<option value="${d}" ${glossaryState.difficulty === d ? "selected" : ""}>${d === "all" ? "Todas las dificultades" : d}</option>`).join("")}</select>
            </div>
            <div class="glossary-statusbar">
              <span><strong>${escapeHtml(activeCategory)}</strong> · ${escapeHtml(activeDifficulty)}</span>
              <span>${detail ? `Detalle activo: ${escapeHtml(detail.term)}` : "Selecciona un concepto para revisar el detalle"}</span>
            </div>
            <div class="app-grid glossary-grid">${terms.map((term) => `<article class="app-card glossary-term-card ${detail?.id === term.id ? "active" : ""}">
            <div class="glossary-term-top"><span class="badge-blue">${escapeHtml(term.category)}</span><span>${escapeHtml(term.difficulty)}</span></div>
            <h3>${highlightText(term.term, glossaryState.query)}</h3>
            <p>${highlightText(words(term.definition, 30), glossaryState.query)}</p>
            <button class="btn-secondary" type="button" data-app-action="glossary-detail" data-id="${term.id}">Ver detalle</button>
          </article>`).join("") || renderEmpty("Sin términos", "Ajusta los filtros del glosario.")}</div>
          </div>
          ${detail ? `<aside class="app-card glossary-detail">
            <div class="glossary-detail-head"><span class="badge-blue">${escapeHtml(detail.category)}</span><span>${escapeHtml(detail.difficulty)}</span></div>
            <h3>${escapeHtml(detail.term)}</h3>
            <p>${formatMathText(detail.definition)}</p>
            ${detail.formula ? `<div class="glossary-formula"><span>Fórmula o criterio</span><code>${escapeHtml(detail.formula)}</code></div>` : ""}
            <div class="apa-output">${formatMathText(detail.example)}</div>
            <div class="glossary-extra"><strong>Uso académico:</strong> ${formatMathText(detail.use || "Se usa para interpretar evidencia, construir argumentos y conectar teoría con problemas económicos reales.")}</div>
            <div class="glossary-extra glossary-writing-tip"><strong>Formato recomendado:</strong> define el concepto, explica el mecanismo, agrega un ejemplo y cierra con interpretación económica.</div>
            <div class="quick-row">${(detail.relatedTerms || []).map((id) => `<button class="app-chip" type="button" data-app-action="glossary-detail" data-id="${id}">${escapeHtml(glossaryTerms().find((t) => t.id === id)?.term || id)}</button>`).join("")}</div>
          </aside>` : ""}
        </div>`}
      </section>`;
    }

    function startGlossaryQuiz() {
      return { items: shuffle(glossaryTerms()).slice(0, 10), index: 0, score: 0, answered: false };
    }

    function renderGlossaryQuiz() {
      const quiz = glossaryState.quiz;
      const current = quiz.items[quiz.index];
      if (!current) {
        document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: quiz.score * 5, reason: "Quiz de glosario" } }));
        return `<article class="app-card glossary-quiz-card"><h3>Resultado final</h3><p>Puntaje: ${quiz.score}/${quiz.items.length}</p><div class="inline-actions"><button class="btn-primary" type="button" data-app-action="glossary-quiz">Nuevo quiz</button><button class="btn-secondary" type="button" data-app-action="glossary-reset">Volver al glosario</button></div></article>`;
      }
      const options = shuffle([current, ...glossaryTerms().filter((t) => t.id !== current.id).slice(0, 3)]);
      return `<article class="app-card glossary-quiz-card"><div class="quiz-meta"><span>${quiz.index + 1}/${quiz.items.length}</span><span>${escapeHtml(current.category)}</span><span>${escapeHtml(current.difficulty)}</span></div><h3>¿Qué término corresponde?</h3><p>${escapeHtml(current.definition)}</p><div class="app-grid glossary-quiz-options">${options.map((option) => `<button class="btn-secondary" type="button" data-app-action="glossary-answer" data-value="${option.id === current.id ? 1 : 0}">${escapeHtml(option.term)}</button>`).join("")}</div></article>`;
    }

    function answerGlossaryQuiz(correct) {
      if (!glossaryState.quiz) return;
      glossaryState.quiz.score += correct ? 1 : 0;
      glossaryState.quiz.index += 1;
      renderActiveApp();
    }

    function renderQuizApp() {
      if (!quizState.running) return `<section class="quiz-shell"><article class="app-card quiz-start-card"><div><span class="section-tag">Autoevaluación</span><h3>Comenzar quiz</h3><p>Elige materia y dificultad. Las preguntas usan ejercicios aplicados por asignatura.</p></div><div class="portal-form-grid compact-form-grid"><label><span>Ciclo</span><select id="quizCycle">${cycleOptionsHtml()}</select></label><label><span>Materia</span><select id="quizSubject">${subjectOptions(CYCLES[0].id, "")}</select></label><label><span>Dificultad</span><select id="quizDifficulty"><option value="facil">Fácil · 10 preguntas</option><option value="medio">Medio · 15 preguntas</option><option value="dificil">Difícil · 20 preguntas</option></select></label><button class="btn-primary" type="button" data-app-action="quiz-start">Comenzar Quiz</button></div></article><div class="admin-list quiz-history">${loadJson(QUIZ_HISTORY_KEY, []).slice(0, 6).map((r) => `<p>${formatDate(r.date)} · ${r.score}/${r.total} · ${escapeHtml(r.subject || "Quiz")}</p>`).join("")}</div></section>`;
      const current = quizState.questions[quizState.index];
      if (!current) {
        const score = quizState.answers.filter(Boolean).length;
        return `<article class="app-card quiz-result-card"><h3>Resultado: ${score}/${quizState.questions.length}</h3><p>${score >= quizState.questions.length * .7 ? "Excelente dominio. Sigue practicando con ejercicios de mayor dificultad." : "Buen intento. Revisa las explicaciones y vuelve a intentar con calma."}</p><div class="quiz-review-list">${quizState.questions.map((q, i) => !quizState.answers[i] ? `<article><strong>${formatMathText(q.question)}</strong><p><b>Correcta:</b> ${formatMathText(q.options[q.correct])}</p><p>${formatMathText(q.explanation)}</p><p><b>Sugerencia:</b> ${formatMathText(q.tip || "Identifica primero los datos, escribe la fórmula y sustituye paso a paso.")}</p></article>` : "").join("") || "<p>No tuviste errores en este intento.</p>"}</div><button class="btn-primary" type="button" data-app-action="quiz-reset">Volver</button></article>`;
      }
      const answered = quizState.selected !== null && quizState.selected !== undefined;
      return `<section class="quiz-shell"><article class="app-card quiz-question-card"><div class="curriculum-progress"><span style="width:${Math.round(((quizState.index + 1) / quizState.questions.length) * 100)}%"></span></div><div class="quiz-meta"><span>${quizState.index + 1}/${quizState.questions.length}</span><span>${escapeHtml(current.subjectName || "Materia")}</span><span>${escapeHtml(current.difficulty)}</span></div><h3>${formatMathText(current.question)}</h3><div class="quiz-options-grid">${current.options.map((option, index) => { const state = answered && index === current.correct ? "correct" : answered && index === quizState.selected ? "wrong" : ""; return `<button class="btn-secondary quiz-option ${state}" type="button" data-app-action="quiz-answer" data-value="${index}" ${answered ? "disabled" : ""}><span>${String.fromCharCode(65 + index)}</span>${formatMathText(option)}</button>`; }).join("")}</div>${answered ? `<div class="quiz-feedback ${quizState.lastCorrect ? "success" : "error"}"><strong>${quizState.lastCorrect ? "Respuesta correcta" : "Respuesta incorrecta"}</strong><p><b>Correcta:</b> ${formatMathText(current.options[current.correct])}</p><p>${formatMathText(current.explanation)}</p><p><b>Sugerencia:</b> ${formatMathText(current.tip || "Identifica la variable clave y resuelve con la fórmula correspondiente.")}</p><button class="btn-primary" type="button" data-app-action="quiz-next">${quizState.index + 1 >= quizState.questions.length ? "Ver resultado" : "Siguiente pregunta"}</button></div>` : ""}</article></section>`;
    }

    function startMainQuiz() {
      const difficulty = document.getElementById("quizDifficulty")?.value || "facil";
      const cycle = document.getElementById("quizCycle")?.value || "";
      const subject = document.getElementById("quizSubject")?.value || "";
      const count = difficulty === "dificil" ? 20 : difficulty === "medio" ? 15 : 10;
      const all = quizQuestions();
      const exact = all.filter((q) => q.materia === subject && q.difficulty === difficulty);
      const sameSubject = all.filter((q) => q.materia === subject && q.difficulty !== difficulty);
      const pool = [...new Map([...exact, ...sameSubject].map((item) => [item.id, item])).values()];
      if (!pool.length) {
        showToast("No hay preguntas disponibles", "Esta materia todavía no tiene preguntas en el banco.", "error");
        return;
      }
      const selected = shuffle(pool).slice(0, Math.min(count, pool.length));
      if (selected.length < count) showToast("Banco limitado", `Esta materia tiene ${selected.length} preguntas disponibles. El quiz usará solo esas preguntas.`, "info");
      quizState = { running: true, questions: selected, index: 0, answers: [], selected: null, lastCorrect: null, saved: false, subject: subjectById(subject)?.name || "Quiz" };
      renderActiveApp();
    }

    function answerMainQuiz(index) {
      const q = quizState.questions[quizState.index];
      if (!q || quizState.selected !== null && quizState.selected !== undefined) return;
      const correct = index === q.correct;
      quizState.answers[quizState.index] = correct;
      quizState.selected = index;
      quizState.lastCorrect = correct;
      showToast(correct ? "Respuesta correcta" : "Revisa la explicación", correct ? "Buen trabajo." : "La respuesta correcta y la sugerencia están debajo de la pregunta.", correct ? "success" : "info");
      renderActiveApp();
    }

    function completeMainQuiz() {
      if (quizState.saved) return;
      if (quizState.index >= quizState.questions.length) {
        const score = quizState.answers.filter(Boolean).length;
        const history = loadJson(QUIZ_HISTORY_KEY, []);
        localStorage.setItem(QUIZ_HISTORY_KEY, JSON.stringify([{ date: new Date().toISOString().slice(0, 10), score, total: quizState.questions.length, subject: quizState.subject || "Quiz" }, ...history]));
        document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: score * 6, reason: "Quiz completado" } }));
        checkAchievements();
        quizState.saved = true;
      }
    }

    function nextMainQuiz() {
      quizState.index += 1;
      quizState.selected = null;
      quizState.lastCorrect = null;
      if (quizState.index >= quizState.questions.length) completeMainQuiz();
      renderActiveApp();
    }

    function renderTimelineApp() {
      const schools = ["all", ...new Set(timelineItems().map((item) => item.school))];
      const items = timelineItems().filter((item) => timelineSchool === "all" || item.school === timelineSchool);
      return `<section class="timeline-app"><div class="timeline-intro"><div><span class="section-tag">Pensamiento económico</span><h3>${items.length} hitos ${timelineSchool === "all" ? "principales" : `de ${escapeHtml(timelineSchool)}`}</h3><p>Recorrido cronológico por autores, obras y debates que explican valor, mercado, Estado, crisis, instituciones, información y comportamiento.</p></div><div class="timeline-count-card"><strong>${items[0]?.year || ""}</strong><span>${items.at(-1)?.year || ""}</span></div></div><div class="app-tabs">${schools.map((school) => `<button class="app-chip ${timelineSchool === school ? "active" : ""}" type="button" data-app-action="timeline-school" data-value="${school}">${school === "all" ? "Todas" : school}</button>`).join("")}</div><div class="timeline-track">${items.map((item, index) => `<article class="timeline-item" style="--school-color:${item.color};--row:${index % 2}"><span class="badge-blue">${item.year}</span><h3>${escapeHtml(item.person)}</h3><p class="timeline-work"><strong>${escapeHtml(item.work)}</strong></p><p>${escapeHtml(item.description)}</p><div class="timeline-tags"><span class="badge-gold">${escapeHtml(item.school)}</span><span>${escapeHtml(item.concept)}</span></div></article>`).join("")}</div></section>`;
    }

    function renderTasksApp() {
      archiveOldTasks();
      const tasks = loadJson(TASK_TRACKER_KEY, []);
      const pending = tasks.filter((task) => task.status !== "Completada").length;
      const columns = ["Pendiente", "En progreso", "Completada"];
      return `<div class="view-heading"><div><h3>${pending} tareas pendientes</h3><p>Organiza entregas, lecturas y evaluaciones.</p></div><button class="btn-primary" type="button" data-app-action="task-form">Nueva tarea</button></div>${taskShowForm ? `<form class="portal-form-grid" data-app-form="task"><label><span>Título</span><input name="title" required></label><label><span>Materia</span><select name="subject">${subjectOptionsHtml()}</select></label><label><span>Fecha límite</span><input name="due" type="date" required></label><label><span>Prioridad</span><select name="priority"><option>Alta</option><option>Media</option><option>Baja</option></select></label><label class="full"><span>Notas</span><textarea name="notes"></textarea></label><button class="btn-primary full" type="submit">Guardar tarea</button></form>` : ""}<div class="kanban-board">${columns.map((col) => `<section class="kanban-column ${col === "Pendiente" ? "pending" : col === "En progreso" ? "progress" : "done"}"><h3>${col}</h3>${tasks.filter((task) => task.status === col).map(renderTaskCard).join("") || renderEmpty("Sin tareas", "No hay elementos en esta columna.")}</section>`).join("")}</div>${renderTaskCalendar(tasks)}`;
    }

    function renderTaskCard(task) {
      return `<article class="app-card"><span class="${taskUrgencyClass(task)}">${escapeHtml(task.priority)}</span><h3>${escapeHtml(task.title)}</h3><p>${escapeHtml(subjectById(task.subject)?.name || task.subject)}</p><small>Vence: ${formatDate(task.due)}</small><select data-task-status data-id="${task.id}">${["Pendiente", "En progreso", "Completada"].map((status) => `<option ${task.status === status ? "selected" : ""}>${status}</option>`).join("")}</select><button class="btn-secondary" type="button" data-app-action="task-delete" data-id="${task.id}">Eliminar</button></article>`;
    }

    function createTask(form) {
      const tasks = loadJson(TASK_TRACKER_KEY, []);
      tasks.unshift({ id: uid(), ...Object.fromEntries(new FormData(form)), status: "Pendiente", createdAt: Date.now() });
      localStorage.setItem(TASK_TRACKER_KEY, JSON.stringify(tasks));
      taskShowForm = false;
      updateTaskBadge();
      showToast("Tarea creada", "Tu tablero se actualizó.", "success");
    }

    function updateTaskStatus(id, status) {
      const tasks = loadJson(TASK_TRACKER_KEY, []);
      const task = tasks.find((item) => item.id === id);
      if (task) {
        task.status = status;
        if (status === "Completada") {
          task.completedAt = Date.now();
          document.dispatchEvent(new CustomEvent("xpEarned", { detail: { amount: 12, reason: "Tarea completada" } }));
        }
      }
      localStorage.setItem(TASK_TRACKER_KEY, JSON.stringify(tasks));
      updateTaskBadge();
      renderActiveApp();
    }

    function deleteTask(id) {
      localStorage.setItem(TASK_TRACKER_KEY, JSON.stringify(loadJson(TASK_TRACKER_KEY, []).filter((task) => task.id !== id)));
      updateTaskBadge();
      renderActiveApp();
    }

    function renderTaskCalendar(tasks) {
      const days = Array.from({ length: 31 }, (_, i) => i + 1);
      return `<article class="app-card"><h3>Calendario mensual</h3><div class="quick-row">${days.map((day) => {
        const has = tasks.some((task) => new Date(task.due + "T00:00:00").getDate() === day);
        return `<span class="app-chip ${has ? "active" : ""}">${day}</span>`;
      }).join("")}</div></article>`;
    }

    function updateTaskBadge() {
      const pending = loadJson(TASK_TRACKER_KEY, []).filter((task) => task.status !== "Completada").length;
      document.querySelectorAll('[data-app="tasks"]').forEach((button) => {
        button.dataset.pending = String(pending);
        button.title = `${pending} tareas pendientes`;
      });
    }

    function openGalleryModal(id) {
      const item = appData.merch.find((x) => x.id === id);
      const images = parseGallery(item?.imagenes);
      el.requestModalContent.innerHTML = `
        <div class="modal-header"><div><span class="eyebrow">Galería merch</span><h2>${escapeHtml(item?.nombre || "Producto")}</h2></div><button class="icon-only" type="button" data-close-request aria-label="Cerrar galería">×</button></div>
        ${images.length ? `<div class="gallery-grid">${images.map((src) => `<a href="${escapeAttribute(src)}" target="_blank" rel="noopener noreferrer"><img src="${escapeAttribute(src)}" alt="${escapeAttribute(item.nombre)}"></a>`).join("")}</div>` : renderEmpty("Sin imágenes cargadas", "El administrador puede agregar links de imágenes desde el panel de Merch.")}
        <div class="modal-actions"><button class="btn-primary" type="button" data-close-request>Cerrar</button></div>`;
      el.requestModalContent.querySelectorAll("[data-close-request]").forEach((node) => node.addEventListener("click", closeRequestModal));
      el.requestModal.hidden = false;
    }
    function parseGallery(value = "") { return String(value || "").split(";").map((src) => src.trim()).filter(Boolean).slice(0, 4); }

    function openRequestModal(type, id) {
      const isTutoria = type === "tutoria";
      const item = isTutoria ? appData.tutorias.find((x) => x.id === id) : appData.merch.find((x) => x.id === id);
      const subject = isTutoria ? `Nueva inscripción a tutoría de ${item.materia}` : `Nueva reserva de merch: ${item.nombre}`;
      el.requestModalContent.innerHTML = `
        <div class="modal-header"><div><span class="eyebrow">${isTutoria ? "Tutoría" : "Merch"}</span><h2>${escapeHtml(isTutoria ? item.materia : item.nombre)}</h2></div><button class="icon-only" type="button" data-close-request aria-label="Cerrar solicitud">×</button></div>
        <form class="formsubmit-form" id="dynamicRequestForm" method="POST" target="formSubmitFrame">
          <input type="hidden" name="_captcha" value="false"><input type="hidden" name="_template" value="table"><input type="hidden" name="_subject" value="${escapeAttribute(subject)}"><input type="hidden" name="_next" value="">
          <input type="hidden" name="${isTutoria ? "Materia" : "Producto"}" value="${escapeAttribute(isTutoria ? item.materia : item.nombre)}">
          <div class="portal-form-grid">
            <label><span>Nombre</span><input name="Nombre" id="requestName" type="text" required></label>
            <label><span>Correo</span><input name="Correo" id="requestEmail" type="email" required></label>
            <label><span>Ciclo</span><select name="Ciclo" id="requestCycle">${el.consultaCiclo.innerHTML}</select></label>
            ${isTutoria ? '<label class="full"><span>Mensaje opcional</span><textarea name="Mensaje" id="requestMessage" placeholder="Cuenta brevemente qué necesitas reforzar"></textarea></label>' : '<label><span>Talla</span><select name="Talla" id="requestSize"><option>No aplica</option><option>XS</option><option>S</option><option>M</option><option>L</option><option>XL</option></select></label><label><span>Cantidad</span><input name="Cantidad" id="requestQuantity" type="number" min="1" value="1" required></label><label class="full"><span>Método de pago preferido</span><select name="Método de pago" id="requestPayment"><option>Efectivo</option><option>Transferencia</option><option>Por coordinar</option></select></label>'}
          </div>
          <div class="modal-actions"><button class="btn-secondary" type="button" data-close-request>Cancelar</button><button class="btn-primary" type="submit">Enviar</button></div>
        </form>`;
      applyFormSubmitConfig();
      prefillKnownForms();
      el.requestModalContent.querySelectorAll("[data-close-request]").forEach((node) => node.addEventListener("click", closeRequestModal));
      document.getElementById("dynamicRequestForm").addEventListener("submit", (event) => {
        const name = document.getElementById("requestName").value.trim();
        const email = document.getElementById("requestEmail").value.trim();
        const cycle = document.getElementById("requestCycle").value;
        if (!name || !email) { event.preventDefault(); return showToast("Campos incompletos", "Completa nombre y correo.", "error"); }
        const message = isTutoria ? (document.getElementById("requestMessage")?.value.trim() || item.tema) : `${item.nombre} · Talla: ${document.getElementById("requestSize")?.value || "No aplica"} · Cantidad: ${document.getElementById("requestQuantity")?.value || "1"} · Pago: ${document.getElementById("requestPayment")?.value || "Por coordinar"}`;
        saveMessage({ type: isTutoria ? "Tutoría" : "Merch", name, email, cycle, subject, materia: isTutoria ? item.materia : "", producto: isTutoria ? "" : item.nombre, message, status: isTutoria ? "pendiente" : "pendiente" });
        showToast(isTutoria ? "Inscripción registrada" : "Reserva registrada", isTutoria ? "El tutor te contactará pronto." : "Te contactaremos para coordinar la entrega.", "success");
        setTimeout(closeRequestModal, 250);
        setTimeout(() => showSection("gracias", true), 300);
      });
      el.requestModal.hidden = false;
    }

    function openBookReservation(id) {
      const book = (appData.physicalBooks || []).find((item) => item.id === id);
      if (!book) return;
      const subject = `Reserva de libro físico: ${book.titulo}`;
      el.requestModalContent.innerHTML = `
        <div class="modal-header"><div><span class="eyebrow">Biblioteca física</span><h2>${escapeHtml(book.titulo)}</h2></div><button class="icon-only" type="button" data-close-request aria-label="Cerrar biblioteca física">×</button></div>
        <form class="formsubmit-form" id="bookReservationForm" method="POST" target="formSubmitFrame">
          <input type="hidden" name="_captcha" value="false"><input type="hidden" name="_template" value="table"><input type="hidden" name="_subject" value="${escapeAttribute(subject)}"><input type="hidden" name="_next" value="">
          <input type="hidden" name="Libro" value="${escapeAttribute(book.titulo)}">
          <div class="portal-form-grid">
            <label><span>Nombre completo</span><input name="Nombre" id="bookName" type="text" required></label>
            <label><span>Correo institucional</span><input name="Correo" id="bookEmail" type="email" required></label>
            <label><span>Ciclo</span><select name="Ciclo" id="bookCycle">${el.consultaCiclo.innerHTML}</select></label>
            <label><span>Teléfono o WhatsApp</span><input name="Teléfono" id="bookPhone" type="tel" placeholder="Opcional"></label>
            <label><span>Fecha sugerida de retiro</span><input name="Fecha de retiro" id="bookPickup" type="date"></label>
            <label class="full"><span>Comentario</span><textarea name="Comentario" id="bookMessage" placeholder="Horario en el que podrías acercarte o información adicional"></textarea></label>
          </div>
          <div class="modal-actions"><button class="btn-secondary" type="button" data-close-request>Cancelar</button><button class="btn-primary" type="submit">Reservar libro</button></div>
        </form>`;
      applyFormSubmitConfig();
      prefillKnownForms();
      el.requestModalContent.querySelectorAll("[data-close-request]").forEach((node) => node.addEventListener("click", closeRequestModal));
      document.getElementById("bookReservationForm").addEventListener("submit", (event) => {
        const name = document.getElementById("bookName").value.trim();
        const email = document.getElementById("bookEmail").value.trim();
        const cycle = document.getElementById("bookCycle").value;
        if (!name || !email || !cycle) { event.preventDefault(); return showToast("Campos incompletos", "Completa nombre, correo y ciclo.", "error"); }
        const pickup = document.getElementById("bookPickup").value;
        const phone = document.getElementById("bookPhone").value.trim();
        const message = `${book.titulo} · Retiro sugerido: ${pickup || "por coordinar"} · WhatsApp: ${phone || "no registrado"} · ${document.getElementById("bookMessage").value.trim()}`;
        saveMessage({ type: "Libro Físico", name, email, cycle, producto: book.titulo, subject, message, status: "pendiente" });
        showToast("Reserva registrada", "Te contactaremos para coordinar el retiro presencial.", "success");
        setTimeout(closeRequestModal, 250);
        setTimeout(() => showSection("gracias", true), 300);
      });
      el.requestModal.hidden = false;
    }
    function closeRequestModal() { el.requestModal.hidden = true; }

    function submitConsulta(event) {
      if (!updateFormValidation(el.consultaForm, true)) {
        event.preventDefault(); return showToast("Completa todos los campos antes de enviar.", "error", "Campos incompletos");
      }
      if (!navigator.onLine) {
        event.preventDefault(); return showToast("No hay conexión para enviar la consulta. Inténtalo nuevamente cuando tengas internet.", "error", "Error de red");
      }
      const saved = saveMessage({ type: "Consulta", name: el.consultaNombre.value, email: el.consultaEmail.value, cycle: el.consultaCiclo.value, subject: el.consultaTipo.value, message: el.consultaMensaje.value, status: "pendiente" });
      localStorage.setItem("portal_last_thanks", JSON.stringify({ type: "consulta", code: saved.trackingCode, date: saved.date }));
      showToast("Consulta enviada correctamente", `Código de seguimiento: ${saved.trackingCode}`, "success");
      setTimeout(() => { el.consultaForm.reset(); updateFormValidation(el.consultaForm); showSection("gracias", true); }, 300);
    }
    function submitBuzon(event) {
      if (!updateFormValidation(el.buzonForm, true)) {
        event.preventDefault(); return showToast("Completa todos los campos antes de enviar.", "error", "Campos incompletos");
      }
      if (!navigator.onLine) {
        event.preventDefault(); return showToast("No hay conexión para enviar la solicitud. Inténtalo nuevamente cuando tengas internet.", "error", "Error de red");
      }
      const saved = saveMessage({ type: "Buzón Académico", name: el.buzonNombre.value, email: "", cycle: el.buzonCiclo.value, materia: el.buzonMateria.value, subject: el.buzonTipoSolicitud.value, message: `${el.buzonMateria.value}: ${el.buzonMotivo.value}`, status: "recibida" });
      localStorage.setItem("portal_last_thanks", JSON.stringify({ type: "buzon", code: saved.trackingCode, date: saved.date }));
      showToast("Solicitud enviada correctamente", `Código de seguimiento: ${saved.trackingCode}`, "success");
      setTimeout(() => { el.buzonForm.reset(); updateFormValidation(el.buzonForm); showSection("gracias", true); }, 300);
    }
    function validateRequired(ids) { const missing = ids.map((id) => document.getElementById(id)).find((field) => !field.value.trim()); if (missing) { missing.focus(); return false; } return true; }

    function setupRealtimeValidation() {
      const forms = [el.consultaForm, el.buzonForm].filter(Boolean);
      forms.forEach((form) => {
        getValidationFields(form).forEach((field) => {
          if (field.tagName === "TEXTAREA") field.maxLength = 500;
          ["input", "change", "blur"].forEach((eventName) => field.addEventListener(eventName, () => updateFormValidation(form)));
          updateTextareaCounter(field);
        });
        updateFormValidation(form);
      });
    }

    function getValidationFields(form) {
      const ids = form?.id === "consultaForm"
        ? ["consultaNombre", "consultaEmail", "consultaCiclo", "consultaTipo", "consultaMensaje"]
        : ["buzonNombre", "buzonCiclo", "buzonMateria", "buzonTipoExamen", "buzonTipoSolicitud", "buzonFechaActual", "buzonFechaSugerida", "buzonMotivo"];
      return ids.map((id) => document.getElementById(id)).filter(Boolean);
    }

    function updateFormValidation(form, reveal = false) {
      if (!form) return false;
      let valid = true;
      getValidationFields(form).forEach((field) => {
        const message = validateFieldMessage(field);
        valid = valid && !message;
        const shouldReveal = reveal || field.dataset.touched === "true" || String(field.value || "").trim().length > 0;
        setFieldError(field, shouldReveal ? message : "");
        updateTextareaCounter(field);
        if (!field.dataset.validationBlurBound) {
          field.dataset.validationBlurBound = "true";
          field.addEventListener("blur", () => {
            field.dataset.touched = "true";
            setFieldError(field, validateFieldMessage(field));
            updateFormValidation(form);
          });
        }
      });
      const submit = form.querySelector('button[type="submit"]');
      if (submit) submit.disabled = !valid;
      return valid;
    }

    function validateFieldMessage(field) {
      const value = String(field.value || "").trim();
      if (!value) return "Este campo es obligatorio.";
      if (field.type === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return "Ingresa un correo válido.";
      if (field.tagName === "TEXTAREA" && value.length > 500) return "Máximo 500 caracteres.";
      return "";
    }

    function setFieldError(field, message) {
      const holder = field.closest("label") || field.parentElement;
      if (!holder) return;
      let error = holder.querySelector(".field-error");
      if (!error) {
        error = document.createElement("small");
        error.className = "field-error";
        holder.appendChild(error);
      }
      field.classList.toggle("is-invalid", Boolean(message));
      error.textContent = message || "";
      error.hidden = !message;
    }

    function updateTextareaCounter(field) {
      if (!field || field.tagName !== "TEXTAREA") return;
      const holder = field.closest("label") || field.parentElement;
      let counter = holder?.querySelector(".char-counter");
      if (!counter && holder) {
        counter = document.createElement("small");
        counter.className = "char-counter";
        holder.appendChild(counter);
      }
      if (!counter) return;
      const length = String(field.value || "").length;
      counter.textContent = `${length}/500 caracteres`;
      counter.classList.toggle("danger", length >= 400);
    }

    function openAdminLogin() {
      if (isAdmin) return openAdminPanel();
      el.adminPasswordInput.value = "";
      const note = el.adminLoginModal?.querySelector(".admin-security-note");
      if (note) {
        note.innerHTML = ADMIN_AUTH_SCRIPT_URL
          ? "Autenticación remota activa mediante Apps Script. Si el despliegue no tiene <code>doPost</code> publicado todavía, se usará un respaldo temporal por hash local."
          : "Autenticación segura no configurada. El portal usará un respaldo temporal por hash local; publica Apps Script para producción.";
      }
      el.adminLoginModal.hidden = false;
      setTimeout(() => el.adminPasswordInput.focus(), 50);
    }
    function closeAdminLogin() { el.adminLoginModal.hidden = true; }
    async function validateAdminByAppsScript(email, password) {
      if (!ADMIN_AUTH_SCRIPT_URL) return { ok: false, skipped: true };
      const body = new URLSearchParams({
        action: "validateAdmin",
        email: email || appData.settings.adminEmail || ADMIN_EMAIL,
        password: String(password || "")
      });
      try {
        const response = await fetch(ADMIN_AUTH_SCRIPT_URL, {
          method: "POST",
          body,
          cache: "no-store"
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return await response.json();
      } catch (error) {
        console.warn("Validación admin remota no disponible.", error);
        return { ok: false, skipped: true, error: error.message };
      }
    }

    async function submitAdminLogin(event) {
      event.preventDefault();
      const submitButton = event.submitter || el.adminLoginForm.querySelector('button[type="submit"]');
      submitButton?.classList.add("is-loading");
      if (submitButton) submitButton.disabled = true;
      const password = el.adminPasswordInput.value;
      const remote = await validateAdminByAppsScript(appData.settings.adminEmail, password);
      const canUseFallback = remote.skipped || remote.requiresSetup || /HTTP|Failed|fetch|Network|no disponible|Load failed|CORS/i.test(remote.error || "");
      const localOk = canUseFallback ? await validateLocalAdminFallback(password) : false;
      submitButton?.classList.remove("is-loading");
      if (submitButton) submitButton.disabled = false;
      if (!remote.ok && !localOk) return showToast("Acceso denegado", remote.error || "Contraseña incorrecta.", "error");
      if (localOk && !remote.ok) showToast("Acceso con respaldo local", "Publica el nuevo Apps Script para usar autenticación remota real.", "info");
      isAdmin = true;
      sessionStorage.setItem("portal_admin_active", "true");
      touchAdminSession();
      logAdminAction("Inició sesión", "admin", "Acceso al panel de administración");
      closeAdminLogin();
      renderAll();
      openAdminPanel();
    }

    async function validateLocalAdminFallback(password) {
      if (!ADMIN_LOCAL_FALLBACK_SHA256 || !password) return false;
      const hash = await sha256Text(password);
      return hash && hash.toLowerCase() === ADMIN_LOCAL_FALLBACK_SHA256.toLowerCase();
    }

    async function sha256Text(value) {
      try {
        if (!window.crypto?.subtle) return "";
        const bytes = new TextEncoder().encode(String(value || ""));
        const digest = await window.crypto.subtle.digest("SHA-256", bytes);
        return Array.from(new Uint8Array(digest)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
      } catch {
        return "";
      }
    }
    function logoutAdmin() {
      logAdminAction("Cerró sesión", "admin", "Salida manual del panel de administración");
      isAdmin = false;
      sessionStorage.removeItem("portal_admin_active");
      sessionStorage.removeItem(ADMIN_LAST_ACTIVITY_KEY);
      clearTimeout(adminInactivityTimer);
      closeAdminPanel();
      renderAll();
    }
    function syncAdminMode() {
      document.body.classList.toggle("admin-active", isAdmin);
      el.adminModeBar.hidden = !isAdmin;
      if (el.addMaterialButton) el.addMaterialButton.hidden = !isAdmin;
      el.adminOpenButton.setAttribute("aria-label", isAdmin ? "Abrir panel administrador activo" : "Abrir panel administrador");
    }
    function openAdminPanel() {
      touchAdminSession();
      el.adminPanel.hidden = false;
      renderAdminTabs();
      renderAdminContent();
      maybeShowBackupReminder();
    }
    function closeAdminPanel() { el.adminPanel.hidden = true; editState = {}; }
    function validateAdminSessionOnLoad() {
      if (!isAdmin) return;
      const last = Number(sessionStorage.getItem(ADMIN_LAST_ACTIVITY_KEY) || 0);
      if (last && Date.now() - last > ADMIN_SESSION_TIMEOUT_MS) {
        isAdmin = false;
        sessionStorage.removeItem("portal_admin_active");
        sessionStorage.removeItem(ADMIN_LAST_ACTIVITY_KEY);
        showToast("Sesión cerrada", "La sesión anterior expiró por inactividad.", "info");
        return;
      }
      touchAdminSession();
    }
    function touchAdminSession() {
      if (!isAdmin) return;
      sessionStorage.setItem(ADMIN_LAST_ACTIVITY_KEY, String(Date.now()));
      clearTimeout(adminInactivityTimer);
      adminInactivityTimer = setTimeout(expireAdminSession, ADMIN_SESSION_TIMEOUT_MS);
    }
    function expireAdminSession() {
      if (!isAdmin) return;
      isAdmin = false;
      sessionStorage.removeItem("portal_admin_active");
      sessionStorage.removeItem(ADMIN_LAST_ACTIVITY_KEY);
      clearTimeout(adminInactivityTimer);
      closeAdminPanel();
      renderAll();
      showToast("Sesión cerrada", "Sesión cerrada por inactividad.", "info");
    }
    function maybeShowBackupReminder() {
      if (!isAdmin || adminBackupReminderShown) return;
      const last = Number(localStorage.getItem(ADMIN_BACKUP_REMINDER_KEY) || 0);
      if (Date.now() - last < ADMIN_BACKUP_INTERVAL_MS) return;
      adminBackupReminderShown = true;
      localStorage.setItem(ADMIN_BACKUP_REMINDER_KEY, String(Date.now()));
      showToast("Respaldo recomendado", "Han pasado varios días desde el último respaldo. Exporta una copia JSON para evitar pérdida de datos.", "info");
    }
    function renderAdminTabs() {
      const tabs = [["dashboard", "Dashboard"], ["drive", "Drive"], ["repositorio", "Repositorio"], ["physicalBooks", "Libros"], ["schedules", "Horarios"], ["alertas", "Alertas"], ["introClasses", "Intro"], ["carreraCards", "Carrera"], ["tutorias", "Tutorías"], ["merch", "Merch"], ["docentes", "Docentes"], ["representantes", "Representantes"], ["eventos", "Eventos"], ["oportunidades", "Oportunidades"], ["mensajes", "Bandejas"], ["config", "Configuración"], ["backup", "Respaldo"]];
      el.adminTabs.innerHTML = tabs.map(([id, label]) => `<button class="${adminTab === id ? "active" : ""}" data-admin-tab="${id}">${label}</button>`).join("");
      el.adminTabs.querySelectorAll("[data-admin-tab]").forEach((btn) => btn.addEventListener("click", () => { adminTab = btn.dataset.adminTab; renderAdminTabs(); renderAdminContent(); }));
    }
    function renderAdminContent() {
      const renderers = { dashboard: renderAdminDashboard, drive: renderAdminDriveDiagnostic, repositorio: renderAdminRepositorio, physicalBooks: () => renderAdminCrud("physicalBooks"), schedules: () => renderAdminCrud("schedules"), alertas: renderAdminAlertas, introClasses: () => renderAdminCrud("introClasses"), carreraCards: () => renderAdminCrud("carreraCards"), tutorias: () => renderAdminCrud("tutorias"), merch: () => renderAdminCrud("merch"), docentes: () => renderAdminCrud("docentes"), representantes: () => renderAdminCrud("representantes"), eventos: () => renderAdminCrud("eventos"), oportunidades: () => renderAdminCrud("oportunidades"), mensajes: renderAdminMensajes, config: renderAdminConfig, backup: renderAdminBackup };
      el.adminContent.innerHTML = renderers[adminTab]();
      bindAdminContent();
    }
    function bindAdminContent() {
      el.adminContent.querySelectorAll("[data-edit]").forEach((btn) => btn.addEventListener("click", () => { editState[adminTab] = btn.dataset.edit; renderAdminContent(); }));
      el.adminContent.querySelectorAll("[data-delete]").forEach((btn) => btn.addEventListener("click", () => deleteAdminItem(btn.dataset.collection, btn.dataset.delete)));
      el.adminContent.querySelectorAll("[data-toggle-hidden]").forEach((btn) => btn.addEventListener("click", () => toggleResource(btn.dataset.toggleHidden)));
      el.adminContent.querySelectorAll("[data-read-message]").forEach((btn) => btn.addEventListener("click", () => markMessage(btn.dataset.readMessage)));
      el.adminContent.querySelectorAll("[data-delete-message]").forEach((btn) => btn.addEventListener("click", () => deleteMessage(btn.dataset.deleteMessage)));
      el.adminContent.querySelectorAll("[data-message-status]").forEach((btn) => btn.addEventListener("click", () => setMessageStatus(btn.dataset.messageStatus, btn.dataset.status)));
      el.adminContent.querySelectorAll("[data-export-messages]").forEach((btn) => btn.addEventListener("click", () => exportMessagesCsv(btn.dataset.exportMessages)));
      el.adminContent.querySelectorAll("[data-open-admin-tab]").forEach((btn) => btn.addEventListener("click", () => { adminTab = btn.dataset.openAdminTab; renderAdminTabs(); renderAdminContent(); }));
      el.adminContent.querySelector("[data-admin-drive-sync]")?.addEventListener("click", async () => {
        const button = el.adminContent.querySelector("[data-admin-drive-sync]");
        button?.classList.add("is-loading");
        if (button) button.disabled = true;
        await loadDriveRepositoryResources({ refresh: true });
        renderAll();
        adminTab = "drive";
        renderAdminTabs();
        renderAdminContent();
      });
      el.adminContent.querySelector("[data-admin-sheets-sync]")?.addEventListener("click", async () => {
        const button = el.adminContent.querySelector("[data-admin-sheets-sync]");
        button?.classList.add("is-loading");
        if (button) button.disabled = true;
        const result = await syncCriticalCollectionsToSheets({ force: true });
        showToast(result.ok ? "Sheets sincronizado" : "Sheets no disponible", result.ok ? "Datos críticos enviados a Google Sheets." : (result.error || "Revisa Apps Script."), result.ok ? "success" : "error");
        renderAdminContent();
      });
      el.adminContent.querySelectorAll("[data-toggle-alert-priority]").forEach((btn) => btn.addEventListener("click", () => toggleAlertPriority(btn.dataset.collection, btn.dataset.toggleAlertPriority)));
      el.adminContent.querySelector("#adminResourceForm")?.addEventListener("submit", submitAdminResource);
      el.adminContent.querySelector("#adminResourceCycle")?.addEventListener("change", (event) => {
        const subjectSelect = el.adminContent.querySelector('[name="subjectId"]');
        subjectSelect.innerHTML = subjectOptions(event.target.value, "");
      });
      el.adminContent.querySelector("#adminCrudForm")?.addEventListener("submit", submitAdminCrud);
      el.adminContent.querySelector("#adminConfigForm")?.addEventListener("submit", submitAdminConfig);
      el.adminContent.querySelector("#exportData")?.addEventListener("click", exportData);
      el.adminContent.querySelector("#importData")?.addEventListener("change", importData);
    }

    function driveDiagnosticMessages() {
      const messages = [];
      if (!DRIVE_REPOSITORY_API_URL) messages.push("Falta configurar la URL de Apps Script.");
      if (DRIVE_REPOSITORY_API_URL && !/\/exec(?:\?|$)/.test(DRIVE_REPOSITORY_API_URL)) messages.push("La URL de Apps Script debe terminar en /exec.");
      if (!DRIVE_ROOT_FOLDER_ID) messages.push("Falta configurar el ID de carpeta raíz.");
      if (driveRepositoryStatus.loading) messages.push("La sincronización está en proceso. En carpetas grandes puede tardar cerca de un minuto.");
      if (driveRepositoryStatus.error) {
        if (/inicio de sesi[oó]n|privad|Failed to fetch|script p[uú]blico/i.test(driveRepositoryStatus.error)) messages.push("Apps Script puede estar privado o sin permisos para cualquier persona.");
        if (/doGet|secuencia de comandos/i.test(driveRepositoryStatus.error)) messages.push("El despliegue publicado no contiene la función doGet. Guarda Code.gs y reimplementa una versión nueva.");
        if (/carpeta|folder|permission|permiso/i.test(driveRepositoryStatus.error)) messages.push("Revisa permisos de la carpeta raíz y de los archivos.");
        messages.push(driveRepositoryStatus.error);
      }
      if (!driveRepositoryStatus.loading && !driveRepositoryStatus.error && driveRepositoryStatus.count === 0) messages.push("Drive está conectado, pero no se encontraron archivos compatibles o las carpetas no coinciden con los ciclos/materias del portal.");
      return messages;
    }

    function renderAdminDriveDiagnostic() {
      const status = driveRepositoryStatus.loading ? "Cargando" : driveRepositoryStatus.error ? "Error" : driveRepositoryStatus.enabled ? "Conectado" : "No configurado";
      const statusClass = driveRepositoryStatus.loading ? "warning" : driveRepositoryStatus.error ? "error" : "success";
      const driveFiles = appData.resources.filter((item) => item.source === DRIVE_RESOURCE_SOURCE);
      const messages = driveDiagnosticMessages();
      const rows = [
        ["Estado", status],
        ["URL Apps Script", DRIVE_REPOSITORY_API_URL || "Sin configurar"],
        ["ID carpeta raíz", DRIVE_ROOT_FOLDER_ID || "Sin configurar"],
        ["Archivos encontrados", String(driveRepositoryStatus.count || driveFiles.length)],
        ["Última sincronización", driveRepositoryStatus.updatedAt ? `${formatDate(driveRepositoryStatus.updatedAt.slice(0, 10))} · ${driveRepositoryStatus.updatedAt.slice(11, 19)}` : "Pendiente"],
        ["PDFs Drive en portal", String(driveFiles.filter(isPdfResource).length)],
        ["Sheets", sheetsSyncStatus.loading ? "Sincronizando" : sheetsSyncStatus.error ? "Error" : sheetsSyncStatus.updatedAt ? "Sincronizado" : "Pendiente"]
      ];
      return `<div class="admin-card drive-diagnostic-card">
        <div class="view-heading">
          <div><h3>Diagnóstico Drive</h3><p>Revisa la conexión entre el portal, Apps Script y la carpeta raíz de Google Drive.</p></div>
          <span class="drive-status-pill ${statusClass}">${status}</span>
        </div>
        <div class="drive-diagnostic-grid">${rows.map(([label, value]) => `<div><span>${label}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}</div>
        <div class="drive-diagnostic-actions">
          <button class="btn-primary" type="button" data-admin-drive-sync ${driveRepositoryStatus.loading ? "disabled" : ""}>${driveRepositoryStatus.loading ? `<span class="btn-spinner" aria-hidden="true"></span> Sincronizando` : "Reintentar sincronización"}</button>
          <button class="btn-secondary" type="button" data-admin-sheets-sync ${sheetsSyncStatus.loading ? "disabled" : ""}>${sheetsSyncStatus.loading ? `<span class="btn-spinner" aria-hidden="true"></span> Sincronizando Sheets` : "Sincronizar con Sheets"}</button>
          <a class="btn-secondary" href="https://script.google.com/home" target="_blank" rel="noopener noreferrer">Abrir Apps Script</a>
          <a class="btn-secondary" href="${escapeAttribute(DRIVE_FOLDER_URL)}" target="_blank" rel="noopener noreferrer">Abrir carpeta Drive</a>
          <a class="btn-secondary" href="${escapeAttribute(DRIVE_REPOSITORY_API_URL)}" target="_blank" rel="noopener noreferrer">Probar /exec</a>
        </div>
        <div class="drive-diagnostic-messages">${messages.length ? messages.map((msg) => `<p>${escapeHtml(msg)}</p>`).join("") : "<p>La configuración básica se ve correcta.</p>"}</div>
      </div>
      <div class="admin-card"><h3>Seguridad del administrador</h3><p>La contraseña del frontend solo protege la interfaz local. Para producción, valida el correo o token del administrador con Apps Script y registra accesos desde una hoja o propiedad del script.</p></div>`;
    }

    function renderAdminDashboard() {
      const pendingTutorias = countMessages("Tutoría", "pendiente");
      const pendingConsultas = (appData.messages || []).filter((m) => m.type === "Consulta" && m.status !== "respondida").length;
      const pendingBuzon = (appData.messages || []).filter((m) => m.type === "Buzón Académico" && !["aprobada", "rechazada"].includes(m.status)).length;
      const pendingReservas = (appData.messages || []).filter((m) => m.type === "Merch" && m.status !== "entregada").length;
      const pendingBooks = (appData.messages || []).filter((m) => m.type === "Libro Físico" && m.status !== "entregada").length;
      const upcomingCount = upcomingItems([...(appData.eventos || []), ...(appData.oportunidades || []), ...visibleResources().filter((item) => item.typeId === "examenes")]).length;
      const totalResources = appData.resources.length;
      const cards = [
        ["Cuadros de carrera", (appData.carreraCards || []).length, "carreraCards"],
        ["Docentes", appData.docentes.length, "docentes"],
        ["Libros físicos", (appData.physicalBooks || []).length, "physicalBooks"],
        ["Recursos subidos", totalResources, "repositorio"],
        ["Inscripciones pendientes", pendingTutorias, "mensajes"],
        ["Consultas por responder", pendingConsultas, "mensajes"],
        ["Solicitudes en buzón", pendingBuzon, "mensajes"],
        ["Reservas merch", pendingReservas, "mensajes"],
        ["Reservas de libros", pendingBooks, "mensajes"],
        ["Alertas activas", upcomingCount, "alertas"]
      ];
      const log = (appData.adminLog || []).slice(0, 6);
      return `<div class="admin-card"><h3>Dashboard general</h3><p>Resumen del portal y accesos rápidos de administración.</p><div class="metric-grid">${cards.map(([label, value, tab]) => `<button class="metric-card" type="button" data-open-admin-tab="${tab}"><strong>${value}</strong><span>${label}</span></button>`).join("")}</div></div><div class="admin-card"><h3>Acciones rápidas</h3><div class="inline-actions"><button class="btn-primary" data-open-admin-tab="repositorio" type="button">Agregar recurso</button><button class="btn-secondary" data-open-admin-tab="tutorias" type="button">Gestionar tutorías</button><button class="btn-secondary" data-open-admin-tab="merch" type="button">Gestionar merch</button><button class="btn-secondary" data-open-admin-tab="config" type="button">Configuración</button></div></div><div class="admin-card"><h3>Últimas acciones del administrador</h3><div class="admin-list">${log.length ? log.map((entry) => adminRow(entry.action, `${formatDate(entry.date.slice(0, 10))} · ${escapeHtml(entry.type)}<br>${escapeHtml(entry.detail || "")}`, "")).join("") : renderEmpty("Sin acciones registradas", "Las acciones administrativas aparecerán aquí.")}</div></div>`;
    }

    function renderAdminRepositorio() {
      const id = editState.repositorio;
      const item = appData.resources.find((r) => r.id === id) || {};
      return `<div class="admin-card"><h3>${id ? "Editar recurso" : "Agregar recurso"}</h3><form id="adminResourceForm" class="admin-form-grid"><input type="hidden" name="id" value="${item.id || ""}">${resourceFormFields(item)}<div class="full modal-actions"><button class="btn-primary" type="submit">${id ? "Guardar cambios" : "Agregar recurso"}</button></div></form></div><div class="admin-card"><h3>Recursos publicados</h3><div class="admin-list">${appData.resources.map((r) => adminRow(r.title, `${findCycle(r.cycleId)?.name || ""} · ${subjectName(r.cycleId, r.subjectId)} · ${categoryLabel(r.typeId)}${r.hidden ? " · oculto" : ""}`, `<button class="btn-secondary" data-edit="${r.id}">Editar</button><button class="btn-secondary" data-toggle-hidden="${r.id}">${r.hidden ? "Mostrar" : "Ocultar"}</button><button class="btn-danger" data-collection="resources" data-delete="${r.id}">Eliminar</button>`)).join("")}</div></div>`;
    }
    function resourceFormFields(item) {
      return `<label><span>Título</span><input name="title" value="${escapeAttribute(item.title || "")}" required></label><label><span>Tipo</span><select name="typeId">${CATEGORIES.map((c) => `<option value="${c.id}" ${item.typeId === c.id ? "selected" : ""}>${c.label}</option>`).join("")}</select></label><label><span>Ciclo</span><select name="cycleId" id="adminResourceCycle">${CYCLES.map((c) => `<option value="${c.id}" ${item.cycleId === c.id ? "selected" : ""}>${c.name}</option>`).join("")}</select></label><label><span>Materia</span><select name="subjectId">${subjectOptions(item.cycleId || CYCLES[0].id, item.subjectId)}</select></label><label class="full"><span>Descripción</span><textarea name="description">${escapeHtml(item.description || "")}</textarea></label><label class="full"><span>Link externo o archivo Base64</span><input name="url" value="${escapeAttribute(item.url || "")}" placeholder="https://drive.google.com/... o archivo .pdf"></label><label><span>Archivo PDF local</span><input name="file" type="file" accept="application/pdf,.pdf"></label><label><span>Fecha</span><input name="date" type="date" value="${item.date || new Date().toISOString().slice(0, 10)}"></label>`;
    }
    function subjectOptions(cycleId, selected) { return (findCycle(cycleId)?.subjects || []).map((s) => `<option value="${s.id}" ${selected === s.id ? "selected" : ""}>${s.name}</option>`).join(""); }
    async function submitAdminResource(event) {
      event.preventDefault();
      const form = event.currentTarget;
      const data = Object.fromEntries(new FormData(form).entries());
      const file = form.file.files[0];
      if (file && file.type !== "application/pdf") return showToast("Archivo no válido", "Sube un PDF para usar el visor integrado del repositorio.", "error");
      const url = file ? await fileToBase64(file) : data.url;
      const previous = data.id ? appData.resources.find((resource) => resource.id === data.id) : null;
      const previousVersions = previous ? [
        ...(previous.previousVersions || []),
        { date: new Date().toISOString(), title: previous.title, description: previous.description, url: previous.url, typeId: previous.typeId, admin: "Administrador" }
      ].slice(-10) : [];
      const payload = { id: data.id || uid(), title: data.title, typeId: data.typeId, description: data.description, url, uploader: "Administrador", date: data.date, cycleId: data.cycleId, subjectId: data.subjectId, hidden: previous?.hidden || false, fileName: file?.name || previous?.fileName || "", fileType: file?.type || previous?.fileType || "", previousVersions };
      upsert("resources", payload);
      logAdminAction(previous ? "Editó material" : "Agregó material", "resources", data.title, payload.id);
      editState.repositorio = null;
      saveData(); renderAll(); renderAdminContent();
      scrollToCreatedItem(`[data-edit="${CSS.escape(payload.id)}"]`);
    }

    function renderAdminCrud(collection) {
      const rows = appData[collection] || [];
      const item = rows.find((x) => x.id === editState[collection]) || {};
      const fields = getCrudFields(collection, item);
      return `<div class="admin-card"><h3>${item.id ? "Editar" : "Agregar"} ${collectionLabel(collection)}</h3><form id="adminCrudForm" class="admin-form-grid"><input type="hidden" name="collection" value="${collection}"><input type="hidden" name="id" value="${item.id || ""}">${fields}<div class="full modal-actions"><button class="btn-primary" type="submit">Guardar</button></div></form></div><div class="admin-card"><h3>Listado</h3><div class="admin-list">${rows.map((row) => adminRow(adminItemTitle(collection, row), adminRowDescription(collection, row), `<button class="btn-secondary" data-edit="${row.id}">Editar</button><button class="btn-danger" data-collection="${collection}" data-delete="${row.id}">Eliminar</button>`)).join("")}</div></div>`;
    }
    function adminItemTitle(collection, row) {
      if (collection === "schedules") return `${subjectName(row.cycleId, row.subjectId) || row.subjectId || "Horario"} · ${row.day || ""}`;
      return row.nombre || row.titulo || row.materia || "Sin título";
    }
    function collectionLabel(collection) {
      return ({ physicalBooks: "libro físico", schedules: "horario", introClasses: "clase introductoria", carreraCards: "cuadro de carrera", tutorias: "tutoría", merch: "producto", docentes: "docente", representantes: "representante", eventos: "evento", oportunidades: "oportunidad" })[collection] || collection;
    }
    function adminRowDescription(collection, row) {
      if (collection === "merch") {
        const sale = parseMoney(row.precio);
        const cost = parseMoney(row.costoUnitario);
        const margin = sale - cost;
        return `${escapeHtml(row.descripcion || "")}<span class="admin-private-note">Precio venta: ${escapeHtml(row.precio || "$0.00")} · Costo unitario: ${escapeHtml(row.costoUnitario || "$0.00")} · Margen estimado: $${margin.toFixed(2)}</span>`;
      }
      if (collection === "schedules") return `${findCycle(row.cycleId)?.name || ""} · ${row.group || "Grupo 1"} · ${row.start || ""} - ${row.end || ""} · ${row.aula || "Aula por definir"} · ${row.docente || ""}`;
      if (collection === "introClasses") return `${row.descripcion || ""} · ${row.nivel || "Introductorio"} · ${row.tutor || ""}`;
      return row.resumen || row.tema || row.materia || row.cargo || row.descripcion || row.institucion || row.precio || row.autor || "";
    }
    function getCrudFields(collection, item) {
      const map = {
        physicalBooks: [["titulo", "Título del libro"], ["autor", "Autor o área responsable"], ["estado", "Estado"], ["descripcion", "Descripción", "textarea"]],
        schedules: [["cycleId", "Ciclo", "cycleSelect"], ["group", "Grupo", "groupSelect"], ["subjectId", "Materia", "subjectSelect"], ["day", "Día", "daySelect"], ["start", "Inicio", "time"], ["end", "Fin", "time"], ["aula", "Aula"], ["docente", "Docente"]],
        introClasses: [["materia", "Materia"], ["descripcion", "Descripción corta", "textarea"], ["nivel", "Nivel"], ["tutor", "Tutor o canal"], ["videoUrl", "Link de YouTube"]],
        carreraCards: [["orden", "Número"], ["titulo", "Título"], ["resumen", "Resumen corto", "textarea"], ["detalle", "Introducción extensa", "textarea"], ["videos", "Links de videos separados por punto y coma", "textarea"]],
        tutorias: [["materia", "Materia"], ["tema", "Tema"], ["nivel", "Nivel"], ["horario", "Horario"], ["modalidad", "Modalidad"], ["tutor", "Tutor"], ["syllabus", "Mini sílabo"], ["domina", "Temas que domina"]],
        merch: [["nombre", "Producto"], ["descripcion", "Descripción", "textarea"], ["precio", "Precio final de venta"], ["costoUnitario", "Costo Unitario de Compra"], ["imagenes", "Imágenes o links de galería (separadas por punto y coma)", "textarea"]],
        docentes: [["nombre", "Nombre"], ["titulo", "Título"], ["materia", "Materia"], ["email", "Correo"], ["whatsapp", "WhatsApp con código de país"], ["horario", "Horario de atención"]],
        representantes: [["nombre", "Nombre"], ["ciclo", "Ciclo"], ["cargo", "Cargo"], ["email", "Correo"], ["redes", "Página o redes sociales"], ["funciones", "Funciones"]],
        eventos: [["titulo", "Título"], ["fecha", "Fecha", "date"], ["lugar", "Lugar"], ["descripcion", "Descripción", "textarea"], ["link", "Link de inscripción"], ["alertPriority", "Alerta prioritaria", "checkbox"]],
        oportunidades: [["tipo", "Tipo"], ["titulo", "Título"], ["institucion", "Institución"], ["fecha", "Fecha límite", "date"], ["descripcion", "Descripción", "textarea"], ["link", "Link"], ["alertPriority", "Alerta prioritaria", "checkbox"]]
      };
      return map[collection].map(([name, label, type]) => crudField(name, label, type, item)).join("");
    }
    function crudField(name, label, type, item) {
      if (type === "textarea") return `<label class="full"><span>${label}</span><textarea name="${name}">${escapeHtml(item[name] || "")}</textarea></label>`;
      if (type === "checkbox") return `<label style="display:flex;align-items:center;gap:8px"><input name="${name}" type="checkbox" ${item[name] ? "checked" : ""}> ${label}</label>`;
      if (type === "cycleSelect") return `<label><span>${label}</span><select name="${name}">${SCHEDULE_CYCLES.map((cycle) => `<option value="${cycle.id}" ${item[name] === cycle.id ? "selected" : ""}>${cycle.name}</option>`).join("")}</select></label>`;
      if (type === "groupSelect") return `<label><span>${label}</span><select name="${name}">${["Grupo 1", "Grupo 2", "Grupo 3"].map((group) => `<option ${((item[name] || "Grupo 1") === group) ? "selected" : ""}>${group}</option>`).join("")}</select></label>`;
      if (type === "subjectSelect") return `<label><span>${label}</span><select name="${name}">${SCHEDULE_CYCLES.flatMap((cycle) => cycle.subjects.map((subject) => `<option value="${subject.id}" ${item[name] === subject.id ? "selected" : ""}>${cycle.name} · ${subject.name}</option>`)).join("")}</select></label>`;
      if (type === "daySelect") return `<label><span>${label}</span><select name="${name}">${["Lunes", "Martes", "Miércoles", "Jueves", "Viernes"].map((day) => `<option ${item[name] === day ? "selected" : ""}>${day}</option>`).join("")}</select></label>`;
      return `<label><span>${label}</span><input name="${name}" type="${type || "text"}" value="${escapeAttribute(item[name] || "")}"></label>`;
    }
    function submitAdminCrud(event) {
      event.preventDefault();
      const data = Object.fromEntries(new FormData(event.currentTarget).entries());
      const collection = data.collection;
      delete data.collection;
      data.id = data.id || uid();
      if (["eventos", "oportunidades"].includes(collection)) data.alertPriority = Boolean(data.alertPriority);
      const previous = (appData[collection] || []).some((item) => item.id === data.id);
      upsert(collection, data);
      logAdminAction(previous ? `Editó ${collectionLabel(collection)}` : `Agregó ${collectionLabel(collection)}`, collection, adminItemTitle(collection, data), data.id);
      editState[collection] = null;
      saveData(); renderAll(); renderAdminContent();
      scrollToCreatedItem(`[data-edit="${CSS.escape(data.id)}"]`);
    }

    function renderAdminAlertas() {
      const rows = [
        ...(appData.eventos || []).map((item) => ({ ...item, collection: "eventos", label: "Evento" })),
        ...(appData.oportunidades || []).map((item) => ({ ...item, collection: "oportunidades", label: "Oportunidad" }))
      ].sort((a, b) => new Date(a.fecha || "2999-12-31") - new Date(b.fecha || "2999-12-31"));
      const exams = visibleResources().filter((item) => item.typeId === "examenes");
      return `<div class="admin-card"><h3>Alertas de fechas próximas</h3><p>Marca eventos u oportunidades como prioritarias para mostrarlas aunque no estén dentro de los próximos 7 días.</p><div class="admin-list">${rows.map((row) => adminRow(`${row.label}: ${row.titulo}`, `${formatDate(row.fecha)} · ${row.descripcion || row.institucion || ""}<br><strong>${row.alertPriority ? "Alerta prioritaria activa" : "Alerta normal"}</strong>`, `<button class="btn-secondary" data-collection="${row.collection}" data-toggle-alert-priority="${row.id}">${row.alertPriority ? "Quitar prioridad" : "Marcar prioritaria"}</button>`)).join("") || renderEmpty("Sin fechas", "Agrega eventos u oportunidades para activar alertas.")}</div></div><div class="admin-card"><h3>Exámenes con fecha</h3><div class="admin-list">${exams.map((exam) => adminRow(exam.title, `${formatDate(exam.date)} · ${subjectName(exam.cycleId, exam.subjectId)} · ${findCycle(exam.cycleId)?.name || ""}`, `<button class="btn-secondary" data-open-admin-tab="repositorio">Editar en repositorio</button>`)).join("") || renderEmpty("Sin exámenes", "Los exámenes se administran desde Repositorio.")}</div></div>`;
    }

    function toggleAlertPriority(collection, id) {
      const item = (appData[collection] || []).find((row) => row.id === id);
      if (!item) return;
      item.alertPriority = !item.alertPriority;
      logAdminAction(item.alertPriority ? "Activó alerta prioritaria" : "Desactivó alerta prioritaria", collection, item.titulo || item.nombre || "", id);
      saveData();
      renderAll();
      renderAdminContent();
    }

    function renderAdminMensajes() {
      const groups = [
        ["Tutoría", "Inscripciones recibidas", ["pendiente", "atendida"]],
        ["Merch", "Reservas recibidas", ["pendiente", "entregada", "cancelada"]],
        ["Libro Físico", "Reservas de libros físicos", ["pendiente", "entregada", "cancelada"]],
        ["Consulta", "Consultas recibidas", ["pendiente", "en proceso", "respondida"]],
        ["Buzón Académico", "Buzón de solicitudes", ["recibida", "en revisión", "aprobada", "rechazada"]]
      ];
      return groups.map(([type, title, statuses]) => renderMessageGroup(type, title, statuses)).join("");
    }
    function renderMessageGroup(type, title, statuses) {
      const rows = (appData.messages || []).filter((m) => m.type === type);
      return `<div class="admin-card"><div class="view-heading"><div><h3>${title}</h3><p>${rows.length} registros guardados en localStorage.</p></div><button class="btn-secondary" type="button" data-export-messages="${type}">Exportar CSV</button></div><div class="admin-list">${rows.length ? rows.map((m) => adminRow(`${m.name || "Sin nombre"} · ${m.email || "Sin correo"}`, `${formatDate(m.date)} · ${m.cycle || "Sin ciclo"} · ${m.subject || ""}<br>${escapeHtml(m.message)}<br><strong>Estado:</strong> ${escapeHtml(m.status || (m.read ? "leído" : "pendiente"))}`, `<select data-message-select="${m.id}">${statuses.map((status) => `<option ${m.status === status ? "selected" : ""}>${status}</option>`).join("")}</select><button class="btn-secondary" data-message-status="${m.id}" data-status="">Actualizar</button><button class="btn-secondary" data-read-message="${m.id}">${m.read ? "No leído" : "Marcar leído"}</button><button class="btn-danger" data-delete-message="${m.id}">Eliminar</button>`)).join("") : renderEmpty("Sin registros", "Aún no hay información en esta bandeja.")}</div></div>`;
    }
    function renderAdminConfig() {
      const s = appData.settings;
      const indicators = indicatorSettings();
      return `<div class="admin-card"><h3>Configuración general</h3><form id="adminConfigForm" class="admin-form-grid"><label><span>Correo de notificaciones</span><input name="adminEmail" type="email" value="${escapeAttribute(s.adminEmail)}"></label><div class="admin-security-note full"><strong>Contraseña administrada en Apps Script</strong><span>Configura <code>ADMIN_PASSWORD</code> o <code>ADMIN_PASSWORD_SHA256</code> en las propiedades del script. El frontend ya no guarda una contraseña local editable.</span></div><label class="full"><span>Link del video del Kit de Nuevo Ingreso</span><input name="kitVideo" value="${escapeAttribute(s.kitVideo || "")}" placeholder="https://www.youtube.com/watch?v=..."></label><label class="full"><span>Google Forms para sugerencias anónimas</span><input name="suggestionFormUrl" value="${escapeAttribute(s.suggestionFormUrl || "")}" placeholder="https://forms.gle/..."></label><label class="full"><span>Drive / repositorio simplificado</span><input name="simplifiedDriveUrl" value="${escapeAttribute(s.simplifiedDriveUrl || "")}" placeholder="https://drive.google.com/..."></label><label class="full"><span>Bienvenida</span><textarea name="welcome">${escapeHtml(s.welcome)}</textarea></label><label class="full"><span>Misión</span><textarea name="mission">${escapeHtml(s.mission)}</textarea></label><label class="full"><span>Visión</span><textarea name="vision">${escapeHtml(s.vision)}</textarea></label><div class="full"><h3>Indicadores económicos editables</h3></div><label><span>Inflación Ecuador</span><input name="indicadorInflacion" value="${escapeAttribute(indicators.inflacion)}"></label><label><span>Riesgo País</span><input name="indicadorRiesgo" value="${escapeAttribute(indicators.riesgo)}"></label><label><span>Precio Petróleo WTI</span><input name="indicadorWti" value="${escapeAttribute(indicators.wti)}"></label><label><span>Fecha de actualización</span><input name="indicadorFecha" value="${escapeAttribute(indicators.fecha)}"></label><div class="full"><h3>Secciones visibles</h3><div class="quick-row">${SECTIONS.map((section) => `<label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="section-${section}" ${s.enabledSections[section] ? "checked" : ""}> ${section}</label>`).join("")}</div></div><div class="full modal-actions"><button class="btn-primary" type="submit">Guardar configuración</button></div></form></div>`;
    }
    function submitAdminConfig(event) {
      event.preventDefault();
      const data = Object.fromEntries(new FormData(event.currentTarget).entries());
      appData.settings.adminEmail = data.adminEmail || ADMIN_EMAIL;
      appData.settings.kitVideo = data.kitVideo || "https://www.youtube.com/watch?v=NU52K6NRXbA";
      appData.settings.suggestionFormUrl = data.suggestionFormUrl || "https://forms.gle/";
      appData.settings.simplifiedDriveUrl = data.simplifiedDriveUrl || "";
      appData.settings.welcome = data.welcome;
      appData.settings.mission = data.mission;
      appData.settings.vision = data.vision;
      localStorage.setItem(INDICATORS_KEY, JSON.stringify({ inflacion: data.indicadorInflacion || "Sin dato", riesgo: data.indicadorRiesgo || "Sin dato", wti: data.indicadorWti || "Sin dato", fecha: data.indicadorFecha || "Actualización manual" }));
      appData.settings.enabledSections = Object.fromEntries(SECTIONS.map((section) => [section, Boolean(data["section-" + section])]));
      appData.settings.enabledSections.inicio = true;
      logAdminAction("Cambió configuración", "config", "Actualizó ajustes generales e indicadores");
      saveData(); applyFormSubmitConfig(); renderAll(); renderAdminContent();
    }
    function renderAdminBackup() {
      return `<div class="admin-card"><h3>Respaldo de datos</h3><p>Exporta o importa toda la información editable como JSON.</p><div class="inline-actions"><button class="btn-primary" id="exportData" type="button">Exportar JSON</button><label class="btn-secondary">Importar JSON<input id="importData" type="file" accept="application/json" hidden></label></div></div>`;
    }

    function adminRow(title, desc, actions) { return `<div class="admin-row"><div><strong>${escapeHtml(title || "Sin título")}</strong><p>${desc || ""}</p></div><div class="admin-row-actions">${actions}</div></div>`; }
    async function deleteAdminItem(collection, id) { if (!(await confirmAction("Eliminar elemento", "Esta acción quitará el registro del portal. Puedes exportar un respaldo antes si lo necesitas."))) return; const item = (appData[collection] || []).find((row) => row.id === id); appData[collection] = (appData[collection] || []).filter((row) => row.id !== id); logAdminAction(`Eliminó ${collectionLabel(collection)}`, collection, adminItemTitle(collection, item || {}), id); saveData(); renderAll(); renderAdminContent(); }
    function toggleResource(id) { const item = appData.resources.find((r) => r.id === id); if (item) { item.hidden = !item.hidden; logAdminAction(item.hidden ? "Ocultó material" : "Mostró material", "resources", item.title, id); } saveData(); renderAll(); renderAdminContent(); }
    async function deleteResourceInline(id) { if (!(await confirmAction("Eliminar recurso", "El material desaparecerá del repositorio, favoritos y banco si corresponde."))) return; const item = appData.resources.find((resource) => resource.id === id); appData.resources = appData.resources.filter((resource) => resource.id !== id); logAdminAction("Eliminó material", "resources", item?.title || "Recurso", id); saveData(); renderAll(); if (!el.adminPanel.hidden) renderAdminContent(); }
    function markMessage(id) { const item = appData.messages.find((m) => m.id === id); if (item) { item.read = !item.read; logAdminAction(item.read ? "Marcó mensaje leído" : "Marcó mensaje no leído", "mensajes", item.type || "Mensaje", id); } saveData(); renderAdminContent(); }
    function setMessageStatus(id, status) {
      const item = appData.messages.find((m) => m.id === id);
      const select = el.adminContent.querySelector(`[data-message-select="${id}"]`);
      if (item) item.status = status || select?.value || item.status || "pendiente";
      if (item) logAdminAction("Actualizó estado de mensaje", "mensajes", `${item.type || "Mensaje"}: ${item.status}`, id);
      saveData();
      renderAdminContent();
    }
    function deleteMessage(id) { const item = appData.messages.find((m) => m.id === id); appData.messages = appData.messages.filter((m) => m.id !== id); logAdminAction("Eliminó mensaje", "mensajes", item?.type || "Mensaje", id); saveData(); renderAdminContent(); }
    function upsert(collection, payload) { appData[collection] = appData[collection] || []; const index = appData[collection].findIndex((item) => item.id === payload.id); if (index >= 0) appData[collection][index] = { ...appData[collection][index], ...payload }; else appData[collection].push(payload); }
    function addResource(payload) {
      const item = { id: uid(), ...payload };
      appData.resources.push(item);
      saveData();
      return item;
    }

    function hydrateDriveRepositoryCache() {
      const cached = loadJson(DRIVE_CACHE_KEY, null);
      if (!cached || !Array.isArray(cached.files) || !cached.files.length) return;
      applyDriveRepositoryPayload(cached, { fromCache: true });
    }

    function applyDriveRepositoryPayload(payload, options = {}) {
      const files = Array.isArray(payload) ? payload : (payload.files || payload.resources || []);
      const driveResources = files.map(mapDriveFileToResource).filter(Boolean);
      const localResources = appData.resources.filter((item) => item.source !== DRIVE_RESOURCE_SOURCE);
      const seen = new Set();
      appData.resources = [...localResources, ...driveResources].filter((item) => {
        const key = item.id || `${item.cycleId}-${item.subjectId}-${item.typeId}-${item.url}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
      driveRepositoryStatus = {
        enabled: true,
        loading: Boolean(options.fromCache && DRIVE_REPOSITORY_API_URL),
        count: driveResources.length,
        error: "",
        updatedAt: payload.updatedAt || payload.cachedAt || new Date().toISOString(),
        cached: Boolean(options.fromCache)
      };
      return driveResources;
    }

    async function loadDriveRepositoryResources(options = {}) {
      if (!DRIVE_REPOSITORY_API_URL) {
        driveRepositoryStatus = { enabled: false, loading: false, count: 0, error: "", updatedAt: "" };
        return;
      }
      driveRepositoryStatus = { ...driveRepositoryStatus, enabled: true, loading: true, error: "" };
      try {
        const endpoint = new URL(DRIVE_REPOSITORY_API_URL, window.location.href);
        endpoint.searchParams.set("format", "json");
        endpoint.searchParams.set("rootFolderId", DRIVE_ROOT_FOLDER_ID);
        if (options.refresh) endpoint.searchParams.set("refresh", "1");
        endpoint.searchParams.set("_", Date.now().toString());
        const payload = await readDriveRepositoryPayload(endpoint);
        if (payload && payload.ok === false) throw new Error(payload.error || "Apps Script devolvió un error.");
        const driveResources = applyDriveRepositoryPayload(payload);
        try {
          localStorage.setItem(DRIVE_CACHE_KEY, JSON.stringify({
            files: Array.isArray(payload) ? payload : (payload.files || payload.resources || []),
            updatedAt: payload.updatedAt || new Date().toISOString(),
            cachedAt: new Date().toISOString()
          }));
        } catch (cacheError) {
          console.warn("No se pudo guardar caché de Drive.", cacheError);
        }
      } catch (error) {
        console.warn("No se pudo sincronizar Google Drive.", error);
        const cachedDriveCount = appData.resources.filter((item) => item.source === DRIVE_RESOURCE_SOURCE).length;
        driveRepositoryStatus = { enabled: true, loading: false, count: cachedDriveCount, error: error.message || "Error de conexión", updatedAt: driveRepositoryStatus.updatedAt || "" };
      }
    }

    async function readDriveRepositoryPayload(endpoint) {
      try {
        const response = await fetch(endpoint.toString(), { cache: "no-store" });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const text = await response.text();
        if (/accounts\.google|ServiceLogin|signin|Inicia sesi[oó]n/i.test(text)) {
          throw new Error("Apps Script responde una pantalla de inicio de sesión");
        }
        try {
          return JSON.parse(text);
        } catch (error) {
          const scriptError = extractAppsScriptError(text);
          throw new Error(scriptError || "Apps Script no devolvió JSON válido");
        }
      } catch (fetchError) {
        return fetchDriveRepositoryJsonp(endpoint).catch((jsonpError) => {
          const reason = fetchError?.message || "Fetch falló";
          const jsonpReason = jsonpError?.message || "sin respuesta JSONP";
          throw new Error(`${reason}; respaldo JSONP: ${jsonpReason}`);
        });
      }
    }

    function extractAppsScriptError(text) {
      const clean = String(text || "")
        .replace(/<style[\s\S]*?<\/style>/gi, " ")
        .replace(/<script[\s\S]*?<\/script>/gi, " ")
        .replace(/<[^>]+>/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      const missingDoGet = clean.match(/No se encontr[oó][^\.]*(?:doGet|secuencia de comandos)[^\.]*/i);
      if (missingDoGet) return missingDoGet[0];
      if (/Exception|Error/i.test(clean)) return clean.slice(0, 220);
      return "";
    }

    function fetchDriveRepositoryJsonp(endpoint) {
      return new Promise((resolve, reject) => {
        const callback = `__driveRepoCallback_${Date.now()}_${Math.random().toString(16).slice(2)}`;
        const url = new URL(endpoint.toString());
        const script = document.createElement("script");
        let finished = false;
        const timeout = window.setTimeout(() => {
          cleanup();
          reject(new Error("tiempo de espera agotado"));
        }, 20000);
        const cleanup = () => {
          if (finished) return;
          finished = true;
          window.clearTimeout(timeout);
          delete window[callback];
          script.remove();
        };
        window[callback] = (payload) => {
          cleanup();
          resolve(payload);
        };
        script.onerror = () => {
          cleanup();
          reject(new Error("no se pudo cargar el script público"));
        };
        url.searchParams.set("callback", callback);
        script.src = url.toString();
        document.head.appendChild(script);
      });
    }

    function mapDriveFileToResource(file) {
      const cycle = matchDriveCycle(file.cycleId || file.cycle, file.cycleName || file.ciclo);
      if (!cycle) return null;
      const subject = matchDriveSubject(cycle, file.subjectId || file.subject, file.subjectName || file.materia);
      if (!subject) return null;
      const fileId = file.id || file.fileId || getGoogleDriveId(file.url || file.previewUrl || file.webViewUrl);
      const previewUrl = file.previewUrl || buildDrivePreviewUrl(file);
      const openUrl = file.webViewUrl || file.viewUrl || file.url || previewUrl;
      const typeId = normalizeDriveCategory(file.typeId || file.categoryId || file.categoryName || file.categoria || file.folderName || file.mimeType || file.name);
      const title = file.title || file.name || "Documento de Google Drive";
      return {
        id: `drive-${fileId || slugify(`${cycle.id}-${subject.id}-${typeId}-${title}`)}`,
        title,
        typeId,
        description: file.description || `Archivo sincronizado automáticamente desde Google Drive para ${subject.name}.`,
        url: previewUrl || openUrl,
        webViewUrl: openUrl,
        viewUrl: openUrl,
        downloadUrl: file.downloadUrl || (fileId ? `https://drive.google.com/uc?export=download&id=${fileId}` : ""),
        uploader: file.uploader || "Google Drive",
        date: String(file.updatedAt || file.createdAt || new Date().toISOString()).slice(0, 10),
        cycleId: cycle.id,
        subjectId: subject.id,
        hidden: false,
        fileName: file.name || title,
        fileType: file.mimeType || "",
        source: DRIVE_RESOURCE_SOURCE
      };
    }

    function matchDriveCycle(cycleId, cycleName) {
      const byId = cycleId ? CYCLES.find((cycle) => cycle.id === cycleId) : null;
      if (byId) return byId;
      const needle = normalize(cycleName || cycleId || "");
      return CYCLES.find((cycle) => normalize(cycle.name) === needle || normalize(cycle.name).includes(needle) || needle.includes(normalize(cycle.name)));
    }

    function matchDriveSubject(cycle, subjectId, subjectNameValue) {
      const byId = subjectId ? cycle.subjects.find((subject) => subject.id === subjectId) : null;
      if (byId) return byId;
      const needle = normalize(subjectNameValue || subjectId || "");
      return cycle.subjects.find((subject) => normalize(subject.name) === needle || normalize(subject.name).includes(needle) || needle.includes(normalize(subject.name)));
    }

    function normalizeDriveCategory(value) {
      const text = normalize(value || "");
      const direct = CATEGORIES.find((cat) => cat.id === value || normalize(cat.label) === text || text.includes(normalize(cat.label)));
      if (direct) return direct.id;
      if (/apunte|nota/.test(text)) return "apuntes";
      if (/diapositiva|presentacion|slide/.test(text)) return "diapositivas";
      if (/guia|guía/.test(text)) return "guias";
      if (/ejercicio|resuelto/.test(text)) return "ejercicios";
      if (/examen|prueba|leccion|lección/.test(text)) return "examenes";
      if (/libro|lectura|pdf/.test(text)) return "lecturas";
      if (/video/.test(text)) return "videos";
      if (/grabada|clase/.test(text)) return "clases-grabadas";
      if (/proyecto|trabajo/.test(text)) return "proyectos";
      return "adicional";
    }

    function buildDrivePreviewUrl(file) {
      const id = file.id || file.fileId || getGoogleDriveId(file.url || "");
      if (!id) return file.url || "";
      const mime = String(file.mimeType || "");
      if (mime === "application/vnd.google-apps.document") return `https://docs.google.com/document/d/${id}/preview`;
      if (mime === "application/vnd.google-apps.presentation") return `https://docs.google.com/presentation/d/${id}/preview`;
      if (mime === "application/vnd.google-apps.spreadsheet") return `https://docs.google.com/spreadsheets/d/${id}/preview`;
      return `https://drive.google.com/file/d/${id}/preview`;
    }

    function renderDriveRepositoryStatus() {
      if (!driveRepositoryStatus.enabled) {
        return `<div class="drive-sync-card muted"><strong>Google Drive no configurado</strong><span>Pega la URL /exec de Apps Script en DRIVE_REPOSITORY_API_URL para cargar PDFs automáticamente.</span></div>`;
      }
      if (driveRepositoryStatus.loading) {
        const cachedText = driveRepositoryStatus.cached && driveRepositoryStatus.count
          ? `Mostrando ${driveRepositoryStatus.count} materiales guardados mientras se actualiza Drive.`
          : "Buscando materiales en tu carpeta.";
        return `<div class="drive-sync-card muted"><strong>Sincronizando Google Drive</strong><span>${cachedText} Esta conexión puede tardar cerca de un minuto, pero el portal sigue funcionando.</span><a class="mini-action" href="${escapeAttribute(DRIVE_FOLDER_URL)}" target="_blank" rel="noopener noreferrer">Abrir carpeta</a></div>`;
      }
      if (driveRepositoryStatus.error) {
        const missingDoGet = /doGet|funci[oó]n de la secuencia/i.test(driveRepositoryStatus.error);
        const accessIssue = /inicio de sesi[oó]n|signin|ServiceLogin|accounts\.google|Failed to fetch|no se pudo cargar el script p[uú]blico/i.test(driveRepositoryStatus.error);
        const helpText = missingDoGet
          ? "El despliegue publicado no tiene el Code.gs correcto. Pega el archivo actualizado, guarda y reimplementa una nueva versión de la Web App."
          : accessIssue
          ? "Apps Script no está disponible para la página: puede estar privado o publicado sin doGet. Pega el Code.gs actualizado y reimplementa la Web App con acceso para cualquier persona."
          : "Revisa permisos, URL /exec, despliegue de Apps Script y carpetas compartidas.";
        return `<div class="drive-sync-card error"><strong>No se pudo sincronizar Drive</strong><span>${escapeHtml(driveRepositoryStatus.error)}. ${helpText}</span><a class="mini-action" href="${escapeAttribute(DRIVE_FOLDER_URL)}" target="_blank" rel="noopener noreferrer">Abrir carpeta Drive</a></div>`;
      }
      return `<div class="drive-sync-card success"><strong>Google Drive conectado</strong><span>${driveRepositoryStatus.count} documentos sincronizados${driveRepositoryStatus.updatedAt ? ` · ${formatDate(driveRepositoryStatus.updatedAt.slice(0, 10))}` : ""}</span></div>`;
    }

    function renderDriveFolderFallback() {
      if (!driveRepositoryStatus.error) return "";
      const embedUrl = `https://drive.google.com/embeddedfolderview?id=${encodeURIComponent(DRIVE_ROOT_FOLDER_ID)}#grid`;
      return `<section class="drive-folder-fallback" aria-label="Vista directa de Google Drive">
        <div class="drive-folder-fallback-head">
          <div>
            <strong>Vista directa del Drive</strong>
            <span>Mientras Apps Script se reimplementa, puedes ver la carpeta aquí dentro de la página.</span>
          </div>
          <a class="mini-action active" href="${escapeAttribute(DRIVE_FOLDER_URL)}" target="_blank" rel="noopener noreferrer">Abrir en Drive</a>
        </div>
        <iframe src="${escapeAttribute(embedUrl)}" title="Repositorio Drive Economía" loading="lazy"></iframe>
      </section>`;
    }
    function saveMessage(payload) {
      const message = { id: uid(), date: new Date().toISOString(), read: false, trackingCode: generateTrackingCode(payload.type), ...payload };
      appData.messages.unshift(message);
      saveData();
      renderNotifications();
      renderProfileSummary();
      return message;
    }
    function generateTrackingCode(type) {
      const prefix = type === "Buzón Académico" ? "BUZ" : type === "Consulta" ? "CON" : type === "Tutoría" ? "TUT" : type === "Merch" ? "MER" : "SOL";
      const year = new Date().getFullYear();
      const count = (appData.messages || []).filter((item) => item.trackingCode?.startsWith(`${prefix}-${year}`)).length + 1;
      return `${prefix}-${year}-${String(count).padStart(4, "0")}`;
    }
    function countMessages(type, status) { return (appData.messages || []).filter((m) => m.type === type && (!status || m.status === status)).length; }
    function exportMessagesCsv(type) {
      const rows = (appData.messages || []).filter((m) => m.type === type);
      const headers = ["Fecha", "Tipo", "Estado", "Nombre", "Correo", "Ciclo", "Materia/Producto", "Asunto", "Mensaje"];
      const csv = [headers, ...rows.map((m) => [formatDate(m.date), m.type, m.status || "", m.name || "", m.email || "", m.cycle || "", m.materia || m.producto || "", m.subject || "", m.message || ""])].map((row) => row.map(csvCell).join(",")).join("\n");
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${slugify(type)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    }
    function csvCell(value) { return `"${String(value ?? "").replaceAll('"', '""')}"`; }

    function applyFormSubmitConfig() {
      const action = "https://formsubmit.co/" + (appData.settings.adminEmail || ADMIN_EMAIL);
      document.querySelectorAll(".formsubmit-form").forEach((form) => {
        form.action = action;
        const next = form.querySelector('input[name="_next"]');
        if (next) next.value = location.href.split("#")[0] + "#gracias";
      });
    }
    function applySectionVisibility() {
      const enabled = appData.settings.enabledSections || {};
      document.querySelectorAll("[data-section]").forEach((section) => {
        if (["gracias"].includes(section.dataset.section)) return;
        section.classList.toggle("hidden-section", !enabled[section.dataset.section]);
      });
      document.querySelectorAll("#navLinks [data-tab]").forEach((link) => link.classList.toggle("hidden-section", !enabled[link.dataset.tab]));
    }

    function visibleResources() { return appData.resources.filter((r) => !r.hidden); }
    function getResources({ cycleId, subjectId, typeId, query } = {}) {
      const q = normalize(query || "");
      return visibleResources().filter((r) => {
        const sourceOk = repoState.sourceFilter === "all"
          || (repoState.sourceFilter === "drive" && r.source === DRIVE_RESOURCE_SOURCE)
          || (repoState.sourceFilter === "local" && r.source !== DRIVE_RESOURCE_SOURCE);
        const searchable = [
          r.title,
          r.description,
          r.uploader,
          r.fileName,
          r.fileType,
          r.source === DRIVE_RESOURCE_SOURCE ? "Google Drive Drive automático" : "Local",
          categoryLabel(r.typeId),
          subjectName(r.cycleId, r.subjectId),
          findCycle(r.cycleId)?.name,
          resourceKind(r)
        ].join(" ");
        return sourceOk && (!cycleId || r.cycleId === cycleId) && (!subjectId || r.subjectId === subjectId) && (!typeId || typeId === "all" || r.typeId === typeId) && (!q || normalize(searchable).includes(q));
      }).sort((a, b) => repoState.sortOrder === "asc" ? new Date(a.date) - new Date(b.date) : new Date(b.date) - new Date(a.date));
    }
    function countResources(filters) { return getResources(filters).length; }
    function countSubjects() { return new Set(SUBJECTS.map((subject) => subject.name)).size; }
    function findCycle(id) { return CYCLES.find((cycle) => cycle.id === id); }
    function findCycleBySubject(subjectId) { return CYCLES.find((cycle) => cycle.subjects.some((subject) => subject.id === subjectId)); }
    function subjectName(cycleId, subjectId) { return findCycle(cycleId)?.subjects.find((s) => s.id === subjectId)?.name || ""; }
    function categoryLabel(id) { return CATEGORIES.find((cat) => cat.id === id)?.label || id; }
    function linkLabel(id) { return ({ apuntes: "Ver apuntes", videos: "Ver video", "clases-grabadas": "Abrir clase", examenes: "Ver examen", diapositivas: "Ver diapositivas" })[id] || "Abrir link"; }
    function getYouTubeId(url) {
      const text = String(url || "");
      const match = text.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
      return match ? match[1] : "";
    }
    function normalizeYouTubeEmbed(url) {
      const youtubeId = getYouTubeId(url);
      return youtubeId ? `https://www.youtube.com/embed/${youtubeId}` : escapeAttribute(url || "https://www.youtube.com/embed/NU52K6NRXbA");
    }
    function renderVideoFrame(url, title = "Video") {
      const youtubeId = getYouTubeId(url);
      return youtubeId
        ? `<iframe src="https://www.youtube.com/embed/${escapeAttribute(youtubeId)}" title="${escapeAttribute(title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`
        : `<a class="portal-card" href="${escapeAttribute(url)}" target="_blank" rel="noopener noreferrer"><h3>Recurso externo</h3><p>${escapeHtml(url)}</p></a>`;
    }
    function getGoogleDriveId(url) {
      const text = String(url || "");
      const patterns = [
        /drive\.google\.com\/file\/d\/([^/?#]+)/i,
        /drive\.google\.com\/open\?id=([^&#]+)/i,
        /drive\.google\.com\/uc\?id=([^&#]+)/i,
        /[?&]id=([^&#]+)/i
      ];
      for (const pattern of patterns) {
        const match = text.match(pattern);
        if (match?.[1]) return decodeURIComponent(match[1]);
      }
      return "";
    }
    function isPdfResource(item) {
      const url = String(item?.url || "").toLowerCase();
      return item?.fileType === "application/pdf" || url.startsWith("data:application/pdf") || /\.pdf(\?|#|$)/.test(url) || /drive\.google\.com\//.test(url);
    }
    function pdfViewerUrl(item) {
      const url = String(item?.url || "");
      const driveId = getGoogleDriveId(url);
      if (driveId) return `https://drive.google.com/file/d/${driveId}/preview`;
      return url;
    }
    function renderPdfPreview(item) {
      if (!isPdfResource(item)) return "";
      const viewerUrl = pdfViewerUrl(item);
      if (!viewerUrl) return "";
      return `<div class="pdf-preview" aria-label="Vista previa PDF: ${escapeAttribute(item.title)}"><div class="pdf-preview-header"><strong>Vista previa del PDF</strong><span>${escapeHtml(item.fileName || "Lectura disponible")}</span></div><iframe src="${escapeAttribute(viewerUrl)}" title="${escapeAttribute(item.title)}" loading="lazy"></iframe></div>`;
    }
    function renderEmpty(title, text) { return `<div class="empty-state"><div><strong>${title}</strong><span>${text}</span></div></div>`; }
    function latest(items, field, limit) { return [...items].sort((a, b) => new Date(b[field]) - new Date(a[field])).slice(0, limit); }
    function initials(value) {
      return String(value || "NA").replace(/^(Eco\.|Mgtr\.|PhD\.|Est\.)\s*/i, "").split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase()).join("") || "NA";
    }
    function resourceKind(item) {
      const url = String(item.url || "").toLowerCase();
      if (isPdfResource(item)) return "pdf";
      if (["videos", "clases-grabadas"].includes(item.typeId) || url.includes("youtube") || url.includes("youtu.be")) return "video";
      if (/\.(png|jpg|jpeg|gif|webp|svg)(\?|$)/.test(url)) return "image";
      if (/\.(pdf|doc|docx|xls|xlsx|ppt|pptx|zip)(\?|$)/.test(url) || ["apuntes", "diapositivas", "guias", "lecturas", "examenes"].includes(item.typeId)) return "document";
      return "link";
    }
    function examTypeClass(value) {
      return normalize(value).replace("á", "a").replace("é", "e").replace("í", "i").replace("ó", "o").replace("ú", "u");
    }
    function dateParts(value) {
      const date = new Date(String(value || new Date().toISOString().slice(0, 10)) + "T00:00:00");
      return {
        day: String(date.getDate()).padStart(2, "0"),
        month: date.toLocaleDateString("es-EC", { month: "short" }).replace(".", "").toUpperCase()
      };
    }
    function daysUntil(value) {
      const target = new Date(String(value || new Date().toISOString().slice(0, 10)) + "T00:00:00");
      const today = new Date(new Date().toISOString().slice(0, 10) + "T00:00:00");
      return Math.ceil((target - today) / 86400000);
    }
    function cycleOptionsHtml(selected = "") {
      return CYCLES.map((cycle) => `<option value="${cycle.id}" ${cycle.id === selected ? "selected" : ""}>${cycle.name}</option>`).join("");
    }
    function subjectOptionsHtml(selected = "") {
      return SUBJECTS.map((subject) => `<option value="${subject.id}" ${subject.id === selected ? "selected" : ""}>${subject.cycleName} · ${subject.name}</option>`).join("");
    }
    function subjectById(id) {
      return SUBJECTS.find((subject) => subject.id === id);
    }
    function words(value, max) {
      return String(value || "").split(/\s+/).slice(0, max).join(" ");
    }
    function shuffle(items) {
      return [...items].map((value) => ({ value, sort: Math.random() })).sort((a, b) => a.sort - b.sort).map((item) => item.value);
    }
    function downloadText(filename, text) {
      const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
    }
    function showXpToast(title, message) {
      if (!el.toastContainer) return showToast(title, message, "success");
      const toast = document.createElement("div");
      toast.className = "toast success xp-toast";
      toast.innerHTML = `<div><span class="toast-icon">XP</span><strong>${escapeHtml(title)}</strong><p>${escapeHtml(message)}</p></div><button type="button" aria-label="Cerrar notificación">×</button><span class="toast-progress"></span>`;
      const removeToast = () => { toast.classList.add("is-leaving"); setTimeout(() => toast.remove(), 220); };
      toast.querySelector("button").addEventListener("click", removeToast);
      el.toastContainer.appendChild(toast);
      setTimeout(removeToast, 4200);
    }
