    function seedResource(typeId, title, description, url, cycleId, subjectNameValue, uploader, date) {
      const cycle = findCycle(cycleId);
      const subject = cycle?.subjects.find((item) => item.name === subjectNameValue);
      if (!cycle || !subject) return null;
      return { id: uid(), title, typeId, description, url, uploader, date, cycleId: cycle.id, subjectId: subject.id, hidden: false };
    }
    function migrateOldResources() {
      try {
        return (JSON.parse(localStorage.getItem(OLD_REPO_KEY)) || []).map((item) => ({ id: uid(), title: item.title, typeId: item.typeId, description: item.description, url: item.url, uploader: item.uploader, date: item.date, cycleId: item.cycleId, subjectId: item.subjectId, hidden: false }));
      } catch { return []; }
    }
    function loadData() {
      try {
        const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
        return saved ? mergeData(defaultData, saved) : structuredClone(defaultData);
      } catch { return structuredClone(defaultData); }
    }
    function mergeData(base, saved) { return { ...structuredClone(base), ...saved, settings: { ...base.settings, ...(saved.settings || {}), enabledSections: { ...base.settings.enabledSections, ...(saved.settings?.enabledSections || {}) } } }; }
    function saveData() {
      try {
        safeSetLocalStorage(STORAGE_KEY, JSON.stringify(appData));
        syncMirrorStorage();
        if (isAdmin) invalidateRenderedSections();
        scheduleCriticalCollectionsSync();
        return true;
      } catch (error) {
        console.error("No se pudo guardar la informacion local.", error);
        const isQuotaError = error?.name === "QuotaExceededError" || error?.name === "NS_ERROR_DOM_QUOTA_REACHED" || error?.code === 22 || error?.code === 1014;
        showToast(
          isQuotaError ? "Almacenamiento lleno" : "No se pudo guardar",
          isQuotaError
            ? "El navegador no tiene espacio suficiente para guardar mas datos. Usa enlaces externos o exporta un respaldo."
            : "Ocurrio un problema al guardar los datos locales. Intenta nuevamente.",
          "error"
        );
        return false;
      }
    }

    let criticalSheetsSyncTimer = null;

    function scheduleCriticalCollectionsSync() {
      if (!isAdmin || !DRIVE_REPOSITORY_API_URL) return;
      clearTimeout(criticalSheetsSyncTimer);
      criticalSheetsSyncTimer = setTimeout(() => {
        syncCriticalCollectionsToSheets().catch((error) => console.warn("Sincronización Sheets omitida.", error));
      }, 1600);
    }

    async function loadCriticalCollectionsFromSheets(options = {}) {
      if (!DRIVE_REPOSITORY_API_URL) return { ok: false, skipped: true };
      try {
        const endpoint = new URL(DRIVE_REPOSITORY_API_URL, window.location.href);
        endpoint.searchParams.set("action", "loadCollections");
        endpoint.searchParams.set("collections", CRITICAL_SHEET_COLLECTIONS.join(","));
        endpoint.searchParams.set("_", Date.now().toString());
        const loadPromise = readDriveRepositoryPayload(endpoint);
        const payload = options.timeoutMs
          ? await Promise.race([loadPromise, new Promise((resolve) => setTimeout(() => resolve({ ok: false, timedOut: true }), options.timeoutMs))])
          : await loadPromise;
        if (!payload?.ok || !payload.collections) return payload || { ok: false };
        let changed = false;
        CRITICAL_SHEET_COLLECTIONS.forEach((collection) => {
          const remoteRows = payload.collections[collection];
          if (!Array.isArray(remoteRows) || !remoteRows.length) return;
          appData[collection] = mergeCollectionWithServer(appData[collection] || [], remoteRows);
          changed = true;
        });
        if (changed) {
          sheetsSyncStatus = { loading: false, error: "", updatedAt: payload.updatedAt || new Date().toISOString() };
          safeSetLocalStorage(STORAGE_KEY, JSON.stringify(appData), { silent: true });
          syncMirrorStorage();
        }
        return payload;
      } catch (error) {
        sheetsSyncStatus = { loading: false, error: error.message || "No se pudo cargar Sheets", updatedAt: sheetsSyncStatus.updatedAt || "" };
        console.warn("No se pudieron cargar colecciones desde Sheets.", error);
        return { ok: false, error: error.message };
      }
    }

    function mergeCollectionWithServer(localRows, serverRows) {
      const map = new Map();
      (localRows || []).forEach((item) => map.set(item.id || uid(), item));
      (serverRows || []).forEach((item) => {
        const id = item.id || uid();
        map.set(id, { ...(map.get(id) || {}), ...item, id });
      });
      return [...map.values()];
    }

    async function syncCriticalCollectionsToSheets(options = {}) {
      if (!DRIVE_REPOSITORY_API_URL) return { ok: false, skipped: true, error: "Apps Script no configurado." };
      sheetsSyncStatus = { ...sheetsSyncStatus, loading: true, error: "" };
      try {
        for (const collection of CRITICAL_SHEET_COLLECTIONS) {
          const body = new URLSearchParams({
            action: "saveCollection",
            collection,
            data: JSON.stringify(appData[collection] || [])
          });
          const response = await fetch(DRIVE_REPOSITORY_API_URL, { method: "POST", body, cache: "no-store" });
          if (!response.ok) throw new Error(`Sheets ${collection}: HTTP ${response.status}`);
          const payload = await response.json();
          if (!payload.ok) throw new Error(payload.error || `No se pudo guardar ${collection}`);
        }
        sheetsSyncStatus = { loading: false, error: "", updatedAt: new Date().toISOString() };
        if (options.force) logAdminAction("Sincronizó Google Sheets", "sheets", "Subió colecciones críticas");
        return { ok: true };
      } catch (error) {
        sheetsSyncStatus = { loading: false, error: error.message || "Error de Sheets", updatedAt: sheetsSyncStatus.updatedAt || "" };
        console.warn("No se pudo sincronizar con Sheets.", error);
        return { ok: false, error: error.message };
      }
    }

    function safeSetLocalStorage(key, value, options = {}) {
      try {
        localStorage.setItem(key, value);
        return true;
      } catch (error) {
        if (options.silent) {
          console.warn(`No se pudo sincronizar ${key}.`, error);
          return false;
        }
        throw error;
      }
    }
    function syncMirrorStorage() {
      try {
        const mirror = (key, value) => safeSetLocalStorage(key, JSON.stringify(value), { silent: true });
        mirror("docentes_lista", appData.docentes || []);
        mirror("carrera_tarjetas", appData.carreraCards || []);
        mirror("clases_introductorias", appData.introClasses || []);
        mirror("libros_fisicos_asociacion", appData.physicalBooks || []);
        mirror("herramientas_notas", appData.gradebook || {});
        mirror("malla_estado_economia", appData.curriculumStatus || {});
        mirror(CURRICULUM_STATE_KEY, appData.curriculumStatus || {});
        mirror("horarios_ciclos", appData.schedules || []);
        mirror("horario_estudiante", appData.studentSchedules || []);
        mirror(STUDENT_SCHEDULE_KEY, appData.studentSchedules || []);
        mirror(PUBLIC_FAVORITES_KEY, favoriteIds || []);
        mirror(ADMIN_LOG_KEY, appData.adminLog || []);
        mirror("inscripciones_tutorias", (appData.messages || []).filter((m) => m.type === "Tutoría"));
        mirror("reservas_merch", (appData.messages || []).filter((m) => m.type === "Merch"));
        mirror("reservas_libros_fisicos", (appData.messages || []).filter((m) => m.type === "Libro Físico"));
        mirror("consultas_recibidas", (appData.messages || []).filter((m) => m.type === "Consulta"));
        mirror("solicitudes_buzon", (appData.messages || []).filter((m) => m.type === "Buzón Académico"));
        CYCLES.forEach((cycle) => cycle.subjects.forEach((subject) => {
          CATEGORIES.forEach((category) => {
            const resources = (appData.resources || []).filter((r) => r.cycleId === cycle.id && r.subjectId === subject.id && r.typeId === category.id);
            mirror(`repo_${cycle.id}_${subject.id}_${category.id}`, resources);
          });
          const exams = (appData.resources || []).filter((r) => r.cycleId === cycle.id && r.subjectId === subject.id && r.typeId === "examenes");
          mirror(`banco_${cycle.id}_${subject.id}`, exams);
        }));
      } catch (error) {
        console.warn("No se pudieron sincronizar las claves secundarias de localStorage.", error);
      }
    }
    function loadJson(key, fallback) {
      try {
        const value = JSON.parse(localStorage.getItem(key));
        return value ?? fallback;
      } catch {
        return fallback;
      }
    }
    function logAdminAction(action, type = "general", detail = "", affectedId = "") {
      if (!isAdmin) return;
      const entry = { id: uid(), action, type, detail, affectedId, date: new Date().toISOString() };
      appData.adminLog = [entry, ...(appData.adminLog || [])].slice(0, 300);
      safeSetLocalStorage(ADMIN_LOG_KEY, JSON.stringify(appData.adminLog), { silent: true });
    }
    function cleanupOldLocalData() {
      const cutoff = Date.now() - (90 * 24 * 60 * 60 * 1000);
      const cleanByDate = (key, dateFields = ["date", "fecha", "createdAt", "completedAt"]) => {
        const rows = loadJson(key, null);
        if (!Array.isArray(rows)) return;
        const next = rows.filter((item) => {
          const raw = dateFields.map((field) => item?.[field]).find(Boolean);
          if (!raw) return true;
          const date = new Date(raw);
          return Number.isNaN(date.getTime()) || date.getTime() >= cutoff;
        });
        if (next.length !== rows.length) safeSetLocalStorage(key, JSON.stringify(next), { silent: true });
      };
      cleanByDate(QUIZ_HISTORY_KEY);
      cleanByDate(TASK_TRACKER_KEY, ["due", "date", "createdAt", "completedAt"]);
      cleanByDate(ADMIN_LOG_KEY);
      const logs = loadJson(ADMIN_LOG_KEY, null);
      if (Array.isArray(logs)) appData.adminLog = logs.slice(0, 300);
    }
    function exportData() {
      const blob = new Blob([JSON.stringify(appData, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url; a.download = "portal-economia-respaldo.json"; a.click();
      URL.revokeObjectURL(url);
      localStorage.setItem(ADMIN_BACKUP_REMINDER_KEY, String(Date.now()));
      logAdminAction("Exportó respaldo", "backup", "Descargó portal-economia-respaldo.json");
    }
    function importData(event) {
      const file = event.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = () => {
        try {
          appData = mergeData(defaultData, JSON.parse(reader.result));
          saveData(); applyFormSubmitConfig(); renderAll(); renderAdminContent();
          showToast("Datos importados", "El respaldo JSON se restauró correctamente.", "success");
        } catch { showToast("JSON inválido", "El archivo JSON no es válido.", "error"); }
      };
      reader.readAsText(file);
    }
    function fileToBase64(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(file); }); }
    function uid() { return "id-" + Math.random().toString(16).slice(2) + "-" + Date.now().toString(16); }
    function slugify(value) { return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
    function normalize(value) { return String(value).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim(); }
    function highlightText(value, query) {
      const raw = String(value || "");
      const normalizedQuery = normalize(query || "");
      if (!normalizedQuery) return escapeHtml(raw);
      const folded = foldWithMap(raw);
      let cursor = 0;
      let position = folded.text.indexOf(normalizedQuery);
      let html = "";
      while (position !== -1) {
        const start = folded.map[position];
        const end = (folded.map[position + normalizedQuery.length - 1] ?? start) + 1;
        html += escapeHtml(raw.slice(cursor, start));
        html += `<mark>${escapeHtml(raw.slice(start, end))}</mark>`;
        cursor = end;
        position = folded.text.indexOf(normalizedQuery, position + normalizedQuery.length);
      }
      html += escapeHtml(raw.slice(cursor));
      return html;
    }
    function foldWithMap(value) {
      let text = "";
      const map = [];
      [...String(value || "")].forEach((char, index) => {
        const folded = normalize(char);
        [...folded].forEach((foldedChar) => {
          text += foldedChar;
          map.push(index);
        });
      });
      return { text, map };
    }
    function normalizePhone(value) { return String(value || "").replace(/\D/g, ""); }
    function parseMoney(value) { return Number(String(value || "0").replace(/[^0-9.-]/g, "")) || 0; }
    function formatDate(value) { if (!value) return "Sin fecha"; return new Intl.DateTimeFormat("es", { year: "numeric", month: "short", day: "2-digit" }).format(new Date(value + (String(value).includes("T") ? "" : "T00:00:00"))); }
    function formatMathText(value) {
      return escapeHtml(value)
        .replace(/\[math\]([\s\S]*?)\[\/math\]/g, '<span class="math-inline">$1</span>')
        .replace(/\[blockmath\]([\s\S]*?)\[\/blockmath\]/g, '<div class="math-block">$1</div>')
        .replace(/\[\[([\s\S]*?)\]\]/g, '<span class="math-inline">$1</span>')
        .replace(/\[eq\]([\s\S]*?)\[\/eq\]/g, '<div class="math-block">$1</div>');
    }
    function escapeHtml(value) { return String(value || "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;"); }
    function escapeAttribute(value) { return escapeHtml(value).replaceAll("`", "&#096;"); }
